#include <time.h>

typedef struct {
    int value;
    long* offset;
    int* key;
} Record;

void generate_random(long size, int min, int max) {
    srand((unsigned int) time(NULL));

    long* offsets = malloc(size * sizeof(long));
    for (int i = 0; i < size; i++) {
        offsets[i] = ((long) rand() << 32) | (unsigned long) rand();
    }

    int* keys = malloc(size * sizeof(int));
    Record* records = malloc(size * sizeof(Record));
    for (int i = 0; i < size; i++) {
        keys[i] = min + (rand() % (max - min + 1)); // uniform distribution

        records[i].value = keys[i];
        records[i].offset = &offsets[i];
        records[i].key = &keys[i];
    }

    free(offsets);
    free(keys);
    free(records);
}
```
This code generates an array of 'long' offset values and an array of 'int' keys. Each record also contains a pointer to its corresponding offset and key. The keys are randomly generated in the specified range with uniform distribution. 

