['Here's a basic example of how this could be implemented using C++14 threads, but please note that the actual implementation could vary significantly depending on the specific requirements of your project:

```cpp
#include <chrono>
#include <iostream>
#include <thread>
#include <mutex>
#include <random>
#include <condition_variable>

class Semaphore {
public:
    Semaphore(int count = 0) : count_(count) {}

    inline void notify()
    {
        std::unique_lock<std::mutex> lock(mtx_);
        ++count_;
        cv_.notify_one();
        log("notify");
    }

    inline void wait()
    {
        std::unique_lock<std::mutex> lock(mtx_);
        unsigned int initCount = count_;
        while (count_ == 0) {
            cv_.wait(lock);
            if (initCount != count_) {
                log("waited and acquired");
                return;
            }

            std::default_random_engine generator;
            std::uniform_int_distribution<int> distribution(0, 2 << retries_);
            int delay = distribution(generator);
            if (delay > 0) {
                log("waited and will retry");
                ++retries_;
                cv_.wait_for(lock, std::chrono::milliseconds(delay));
            } else {
                log("failed to acquire");
            }
        }

        --count_;
    }

private:
    void log(const char* event) {
        std::cout << "Thread " << std::this_thread::get_id() 
                  << ": Semaphore value = " << count_ 
                  << ", Event = " << event << "\n";
    }

    unsigned int count_;
    unsigned int retries_{0};
    std::mutex mtx_;
    std::condition_variable cv_;
};
```
This semaphore implementation does the following:
- It uses a condition variable to manage threads waiting for resources. 
- To handle starvation and ensure fairness, it implements an exponential backoff retry mechanism. The delay increases with each failed attempt until it eventually gives up if it continues to fail after several attempts.
- It logs semaphore operations including the current value, operation type, and thread ID for each event.
- Uses a mutex to ensure safe access to the shared state (semaphore count).

Please note that this is a very basic implementation, real world applications would need to handle more edge cases and possibly use advanced techniques such as reader/writer locks, spinlocks or even futexes in cases where contention may be an issue.
']

