};

class NetworkLogger : public Logger {
public:
    NetworkLogger(const std::string& address) : address_(address) {}

    void log(LogLevel level, const std::string& message) override {
        // Send over network
    }
private:
    std::string address_;
};

class AsyncLogger : public Logger {
public:
    AsyncLogger() {
        worker_ = std::thread([this] { this->processQueue(); });
    }
    ~AsyncLogger() {
        done_ = true;
        condition_.notify_all();
        worker_.join();
    }

    void add(std::unique_ptr<Logger> logger) {
        std::lock_guard<std::mutex> lock(mutex_);
        loggers_.push_back(std::move(logger));
    }

    void log(LogLevel level, const std::string& message) override {
        std::lock_guard<std::mutex> lock(mutex_);
        queue_.push([this, level, message] {
            for (auto& logger : loggers_) {
                logger->log(level, message);
            }
        });
        condition_.notify_one();
    }
private:
    void processQueue() {
        while (!done_) {
            std::function<void()> task;
            {
                std::unique_lock<std::mutex> lock(mutex_);
                condition_.wait(lock, [this] { return !queue_.empty(); });
                if (queue_.empty()) continue;
                task = std::move(queue_.front());
                queue_.pop();
            }
            task();
        }
    }

    bool done_ = false;
    std::thread worker_;
    std::mutex mutex_;
    std::condition_variable condition_;
    std::vector<std::unique_ptr<Logger>> loggers_;
    std::queue<std::function<void()>> queue_;
};
```

This code does not implement the complete functionality you requested but gives an idea of how one might structure such a system in C++. Developers would have to fill in the details about opening files, sending over network etc. Also remember that this is just pseudo-code and won't compile, it's meant to provide an overview of what your logging framework might look like.
