    public static XmlElement GetFirstElementByXPath(XmlDocument xmlDoc, string elementName, int timeout)
    {
        var sw = Stopwatch.StartNew();

        while (sw.ElapsedMilliseconds <= timeout)
        {
            var nodeList = xmlDoc.GetElementsByTagName(elementName);
            if (nodeList.Count == 0)
            {
                Thread.Sleep(10);
            } 
            else if (nodeList.Count > 1)
            {
                throw new InvalidOperationException("More than one element with specified name found.");
            } 
            else
