use std::env;
use std::fs::{self, DirEntry};
use std::path::PathBuf;
use std::ffi::OsStr;

pub fn set_environment_variable_for_directory(dirname: &str, path_prefix: &str) -> PathBuf {
    let dir = fs::DirBuilder::new().current_dir(".").join(dirname);
    if !dir.exists() {
        fs::create_dir(&dir).unwrap();
    } 

    match env::var_os("DIR_PATH") {
        None => env::set_var("DIR_PATH", dir),
        Some(prev) => {
            let prev = OsStr::new(prev);
            if !prev.starts_with(&OsStr::new(path_prefix)) {
                env::set_var("DIR_PATH", dir);
            }
        },
    };

    dir
}
