<?php
class UserManager {
    private $cache; // Assuming you have a caching class with get, set and delete methods
    private $db; // Assuming you have a database class with createUser, deleteUser and fetchUserById methods

    public function __construct($dbConnection) {
        $this->cache = new Cache(); // Instantiate your cache class here
        $this->db = $dbConnection; // Instantiate your DB connection class here
    }

    public function handleUserRequest() {
        $requestMethod = $_SERVER['REQUEST_METHOD'];

        if ($requestMethod == 'POST') {
            $data = json_decode(file_get_contents('php://input'), true);

            // Validate input
            $errorMessage = $this->validateInput($data);

            if (!empty($errorMessage)) {
                return json_encode(['status' => 'fail', 'message' => $errorMessage]);
            }

            // Save user to DB
            try {
                $userId = $this->saveUser($data['name'], $data['email'], $data['password']);

                // If save is successful, cache the user data
                $this->cacheUserData($userId);

                return json_encode(['status' => 'success', 'message' => 'User created successfully.']);
            } catch (Exception $e) {
                error_log($e->getMessage());
                return json_encode(['status' => 'fail', 'message' => $e->getMessage()]);
            }
        } 

        else if ($requestMethod == 'DELETE') {
            $userId = $_GET['userId'];

            // Check user has no active sessions or transactions before deleting

            try {
                $this->deleteUser($userId);
                return json_encode(['status' => 'success', 'message' => 'User deleted successfully.']);
            } catch (Exception $e) {
                error_log($e->getMessage());
                return json_encode(['status' => 'fail', 'message' => $e->getMessage()]);
            }
        } 

        else {
            return json_encode(['status' => 'fail', 'message' => 'Invalid request method.']);
        }
    }

    private function validateInput($data) {
        if (empty($data['name']) || !is_string($data['name'])) {
            return 'Name must be a non-empty string';
        } 

        elseif (!filter_var($data['email'], FILTER_VALIDATE_EMAIL)) {
            return 'Invalid email format.';
        } 

        elseif (strlen($data['password']) < 8) {
            return 'Password must be at least 8 characters long.';
        }
    }

    private function saveUser($name, $email, $password) {
        $userId = $this->db->createUser(['name' => $name, 'email' => $email, 'password' => password_hash($password, PASSWORD_BCRYPT)]);

        if (!$userId) {
            throw new Exception('Failed to create user.');
        }

        return $userId;
    }

    private function cacheUserData($userId) {
        $user = $this->db->fetchUserById($userId);

        // Remove sensitive information from the user data
        unset($user['password']);

        $this->cache->set('user_' . $userId, json_encode($user));
    }

    private function deleteUser($userId) {
        // Check user has no active sessions or transactions before deleting
        if ($hasActiveSessionsOrTransactions) {
            throw new Exception('Cannot delete user with active sessions or transactions.');
        }

        $this->db->deleteUser($userId);
        $this->cache->delete('user_' . $userId);
    }
}
```

Please note that this is a simplified version and you would need to implement more features based on your actual requirements. It does not cover some aspects like caching eviction strategy, handling concurrent access and deadlocks since these aspects are quite complex and depend on the specific use case. Also, remember to handle exceptions properly according to the error handling best practices of PHP.
