    private readonly ILogger<PageElementController> _logger;

    public PageElementController(IPageRepository pageRepository, ILogger<PageElementController> logger)
    {
        _pageRepository = pageRepository ?? throw new ArgumentNullException(nameof(pageRepository));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
