        {
            _logger.LogWarning("Invalid inputs");
            return BadRequest(); // Return bad request if the model is not valid or the inputs do not meet format requirements
        }

        var policy = Policy
          .Handle<Exception>()
          .RetryAsync(3, (exception, retryCount) => { _logger.LogWarning($"External service unavailability. Retrying... attempt: {retryCount}"); });

        try
        {
            var page = await policy.ExecuteAsync(() => _pageRepository.GetPageBySectionIdAsync(sectionId));

            if (page == null)
            {
                _logger.LogError("Page not found");
                return NotFound(); // Return not found if the page is not found
            }

            var element = await policy.ExecuteAsync(() => _pageRepository.GetElementByIdAsync(elementId));

            if (element == null)
