import java.io.*;
import android.graphics.Bitmap;
import android.graphics.BitmapFactory;

public MoSTState loadState(String filename) {
    FileInputStream fis = null;
    ObjectInputStream in = null;
    try {
        fis = new FileInputStream(filename);
        in = new ObjectInputStream(fis);
        Object object = in.readObject();

        if (object instanceof MoSTState) {
            // Check and manage theme bitmap recycling
            BitmapFactory.Options options = new BitmapFactory.Options();
            options.inPreferredConfig = Bitmap.Config.ARGB_8888;
            Bitmap bitmap = BitmapFactory.decodeFile(filename, options); // replace with actual file path and name

            if (bitmap != null && !bitmap.isRecycled()) {
                bitmap.recycle();
            }

            return (MoSTState) object;
        } else {
            return null;
        }
    } catch (Exception e) {
        // Handle exceptions
        e.printStackTrace();
        return null;
    } finally {
        try {
            if (in != null) {
                in.close();
            }
        } catch (IOException ex) {
            // ignore close exception
        }
        try {
            if (fis != null) {
                fis.close();
            }
        } catch (IOException ex) {
            // ignore close exception
        }
    }
}
