        this.instanceId = id;
    }

    public void start() throws InterruptedException {
        System.out.println("Starting service instance " + instanceId);
        Thread.sleep(random.nextInt(1000));  // Simulate delay for starting
    }

    public void stop() throws InterruptedException {
        System.out.println("Stopping service instance " + instanceId);
        Thread.sleep(random.nextInt(1000));  // Simulate delay for stopping
    }
}

class MessagingSystem {
    private int messageLimit;

    public MessagingSystem(int limit) {
        this.messageLimit = limit;
    }

    public void sendMessage() throws Exception {
        if (this.messageLimit <= 0) {
            throw new Exception("Daily throughput limit exceeded");
        }

        // Assume we're sending a message here
        this.messageLimit--;
    }
}

class LoadBalancer {
    private List<ServiceInstance> instances = new ArrayList<>();

    public void addInstance(ServiceInstance instance) {
        instances.add(instance);
    }

    // Simple load balancing algorithm - randomly select an instance
    public ServiceInstance getNextInstance() {
        Random random = new Random();
        return instances.get(random.nextInt(instances.size()));
    }
}

class Main {
    public static void main(String[] args) throws InterruptedException, Exception {
        LoadBalancer loadBalancer = new LoadBalancer();

        for (int i = 0; i < 10; i++) {
            ServiceInstance instance = new ServiceInstance(i);
            instance.start();
            loadBalancer.addInstance(instance);
        }

        MessagingSystem messagingSystem = new MessagingSystem(5000);  // Daily limit of 5000 messages

        int attempts = 0;
        while (true) {
            try {
                ServiceInstance instance = loadBalancer.getNextInstance();
                instance.start();

                messagingSystem.sendMessage();

                instance.stop();
