class Config {
    protected static $config = [];

    public static function load($name) {
        if (!isset(self::$config[$name])) {
            self::$config[$name] = include "config/{$name}.php"; // Load local configuration files

            $externalConfig = self::fetchExternalConfiguration($name); 
            if ($externalConfig && $externalConfig['updated_at'] > self::$config[$name]['updated_at']) {
                self::$config[$name] = $externalConfig; // Update local configuration with external config when outdated
                self::log("Updated {$name} configuration due to external changes.");
            }
        }

        return self::$config[$name];
    }

    protected static function fetchExternalConfiguration($name) {
        $externalApi = 'https://api.example.com/config'; // Assuming we have an API for fetching external configuration data
        $cacheKey = "external_{$name}_config"; 

        if (apcu_exists($cacheKey)) {
            return apcu_fetch($cacheKey); // Fetch from in-memory cache when available 
        } else {
            $response = file_get_contents("{$externalApi}/{$name}"); // Call external API for configuration data

            if ($response) {
                $configData = json_decode($response, true);
                apcu_store($cacheKey, $configData, 3600); // Cache the configuration data for 1 hour in-memory

