['Here is an example code block of how you might implement this task using Rust's `log` crate for logging hooks, the `env_logger` crate for managing these logs efficiently, `serde` and `serde-yaml` to deal with YAML configurations, `tokio` for async tasks, and `std::process` to interact with subprocesses.

```rust
use std::{fs::File, io::Read, path::Path};
use log::{info, warn};
use serde::Deserialize;
use std::process::Command;
use tokio::sync::Mutex;
use env_logger;

#[derive(Debug, Deserialize)]
struct Configuration {
    target: String,
    flags: Vec<String>,
}

pub struct Metrics {
    pub duration: std::time::Duration,
    pub rss: u64,
}

impl Default for Metrics {
    fn default() -> Self {
        Self {
            duration: std::time::Duration::from_secs(0),
            rss: 0,
        }
    }
}

pub async fn compile_with_logging_and_metrics(config_path: &Path) -> (i32, Metrics) {
    let mut log = Mutex::new(Metrics::default());
    env_logger::init();

    info_log(&format_args_1);

    let config_file = File::open(config_path).unwrap();
    let mut buffer = String::new();
    config_file.read_to_string(&mut buffer).unwrap();

    let config: Configuration = serde_yaml::from_str(&buffer).unwrap();

    let start_time = std::time::Instant::now();
    let mut command = Command::new("rustc");

    for flag in &config.flags {
        command.arg(flag);
    }

    info_log(&format_args_2, config.target);

    match command.status() {
        Ok(status) => {
            let duration = start_time.elapsed();
            if status.success() {
                info_log(&format_args_3, &config.target, duration.as_secs());
            } else {
                warn_log(&format_args_4, &config.target);
            }
            let metrics = Metrics { duration, rss: 0 }; // Calculate RSS
            (status.code(), metrics)
        }
        Err(e) => {
            error_log(&format_args_5, e);
            (255, Metrics::default())
        }
    }
}
```
This is a basic structure of the Rust function which includes reading configurations from YAML file. The `Mutex` object ensures that logging doesn't interfere with compilation process and logging operations are performed in a thread-safe manner. 

