["```javascript
const crypto = require('crypto');
const fs = require('fs');

function generateRandomStringAndHash(length, charset, defaultHashAlgorithm='sha256', password) {
    let generatedString = '';
    const charactersLength = charset.length;

    for (let i = 0; i < length; i++ ) {
        generatedString += charset.charAt(Math.floor(Math.random() * charactersLength));
    }

    const hashMethod = defaultHashAlgorithm || 'sha512'; // Fallback to sha512 if not provided
    const hasher = crypto.createHmac(hashMethod, password);
    const hash = hasher.digest('hex');

    return { generatedString: generatedString, hash: hash };
}

function readFileContentsSyncAdvanced(filePath, encoding='utf8') {
    try {
        fs.accessSync(filePath, fs.constants.R_OK); // Check if file is readable

        const data = fs.readFileSync(filePath, {encoding: encoding});

        return data;
    } catch (err) {
        if (err.code === 'ENOENT') {
            console.log('No such file or directory');
        } else if (err.code === 'EACCES') {
            console.log('Permission denied');
        } else if (err.code === 'EMFILE' || err.code === 'EBUSY') {
            console.log('Too many file descriptors in use, please try again later');
        } else {
            console.error(`Error reading the file: ${err}`);
        }

        return null;
    }
}
```
