    }

    readAndValidatePemFile(pemfilepath, callback) {
        fs.readFile(pemfilepath, 'utf8', (err, data) => {
            if (err) return callback(err);

            pem.verifySigningChain(data, undefined, function(err, verified) {
                if (err) return callback(err);

                // If PEM file is validated successfully, emit the data event
                this.emit('data', data);
                return callback();
            });
        });
    }
}

async function generatePEMCertificate(oauthRequest) {
    const certGenerator = new CertGenerator();
    // Validate OAuth Request and Extract paths to PEM files
    let pemfilepaths;
    try {
        certGenerator.validateOAuthRequest(oauthRequest);
        pemfilepaths = certGenerator.extractPEMFilesPaths(oauthRequest);
    } catch (error) {
        console.log('Error validating or extracting paths from OAuth request', error);
        return;
    }

    // Read and Validate PEM files using async retry logic to handle transient failures
    async.retry({ times: 3, interval: 1000 }, function(callback) {
        async.eachSeries(pemfilepaths, certGenerator.readAndValidatePemFile.bind(certGenerator), callback);
    });
}
