// You would replace this with an actual packet structure 
typedef struct {
    int size;
    double priorityScore;
    time_t timestamp;
} Packet;

typedef struct {
    Packet *packets;
    int capacity;
    int count;
    int startIndex;
    int endIndex;
} Window;

// You would replace this with an actual function to get packet metadata
Packet getMetadata(Packet pkt) {
    // simulate a network delay
    struct timespec tim, tim2;
    tim.tv_sec = 0;
    tim.tv_nsec = 50000000L;  // 50 ms
    nanosleep(&tim , &tim2);

    pkt.priorityScore = rand() % 10;  
    return pkt;
}

Packet processStream(Window *window) {
    Packet highestPrioPkt;
    memset(&highestPrioPkt, 0, sizeof(Packet));

    for (int i = 0; i < window->count; ++i) {
        int index = (window->startIndex + i) % window->capacity;
        Packet pkt = getMetadata(window->packets[index]);  // Simulate network delay and metadata service call

        if (pkt.priorityScore > highestPrioPkt.priorityScore || 
            (pkt.priorityScore == highestPrioPkt.priorityScore && pkt.timestamp < highestPrioPkt.timestamp)) {
            highestPrioPkt = pkt;
        }
    }

    return highestPrioPkt;
}

void addPacket(Window *window, Packet packet) {
    if (window->count == window->capacity) {  // Slide window forward if at capacity
        window->startIndex = (window->startIndex + 1) % window->capacity;
    } else {
        ++(window->count);
    }

    window->packets[window->endIndex] = packet;
    window->endIndex = (window->endIndex + 1) % window->capacity;
}

int main() {
    srand(time(0));  // seed the random number generator for priorityScore generation

    int windowSize = 50;  
    Window window = {.packets = malloc(windowSize * sizeof(Packet)), .capacity = windowSize, .startIndex = 0, .endIndex = 0, .count = 0};

    // Simulate packets
    for (int i=0; i < 100000; ++i) {
        Packet packet = {.size = rand() % 1024, .timestamp = time(0)};

        addPacket(&window, packet);

        Packet highestPrioPkt = processStream(&window);
        printf("Highest priority packet: size=%d, priorityScore=%.2f, timestamp=%ld\n", 
               highestPrioPkt.size, highestPrioPkt.priorityScore, highestPrioPkt.timestamp);
    }

    free(window.packets);
}
