public class DynamicValueGenerator<T> where T : IConvertible // this will be either 'int' or 'float', etc.
{
    private ConcurrentDictionary<Range, Random> _generators = new ConcurrentDictionary<Range, Random>();
    private Func<Task<List<ExternalData>>> _getData;

    public DynamicValueGenerator(Func<Task<List<ExternalData>>> getData) 
    {
        _getData = getData;
    }

    public async Task InitializeGenerators() 
    {
        var data = await _getData();

        foreach (var item in data) 
        {
            _generators[item.Range] = new Random(item.Seed);
        }
    }

    public T GetNextValue(Range range)
    {
        if (_generators.TryGetValue(range, out var generator)) 
        {
            lock (generator)
            {
                return (T)Convert.ChangeType(generator.NextDouble() * (range.Max - range.Min) + range.Min, typeof(T));
            }
        }

        throw new InvalidOperationException("No generator for specified range");
    }

    public string SerializeState() 
    {
        return JsonConvert.SerializeObject(_generators);
    }

    public void DeserializeState(string serialized) 
    {
        _generators = JsonConvert.DeserializeObject<ConcurrentDictionary<Range, Random>>(serialized);
    }
}
