['This is a complex task that involves multiple steps such as reading TIFF files, extracting metadata, computing MD5 hash of filename, error handling etc. 

In C programming language, this task can be accomplished by using libraries like `libtiff` for reading TIFF images and `OpenSSL` for calculating the MD5 hash of filenames. Here is a skeleton function that implements the core features:

```c
#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <openssl/md5.h>
#include <tiffio.h>

typedef struct TIFF_Metadata {
    uint16 bitsPerSample;
    uint16 samplePerPixel;
    uint32 extraSamples;
    char md5Hash[MD5_DIGEST_LENGTH*2+1];
} TIFF_Metadata;

void processTIFFs(const char *directory) {
    TIFF *tiff;
    DIR *dir;
    struct dirent *ent;

    if ((dir = opendir (directory)) != NULL) {
        while ((ent = readdir (dir)) != NULL) {
            if(strcmp(ent->d_name + strlen(ent->d_name) - 4, ".tif") == 0 || 
               strcmp(ent->d_name + strlen(ent->d_name) - 5, ".tiff") == 0){
                char filepath[1024];
                snprintf(filepath, sizeof(filepath), "%s/%s", directory, ent->d_name);

                tiff = TIFFOpen(filepath, "r");
                if (tiff) {
                    TIFF_Metadata metadata;

                    // Extract Metadata
                    uint16 bps, spp;
                    TIFFGetField(tiff, TIFFTAG_BITSPERSAMPLE, &bps);
                    TIFFGetField(tiff, TIFFTAG_SAMPLESPERPIXEL, &spp);

                    metadata.bitsPerSample = bps;
                    metadata.samplePerPixel = spp;
                    // Extract extra samples if needed

                    // Compute MD5 hash of filename and add to struct
                    unsigned char digest[MD5_DIGEST_LENGTH];
                    MD5((unsigned char*)filepath, strlen(filepath), digest);    
                    for(int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
                        sprintf(&metadata.md5Hash[i*2], "%02x", (unsigned int)digest[i]);
                    }

                    // Process metadata as needed
                    printf("Filename: %s\nMD5 Hash: %s\nBits per sample: %hu\nSample per pixel: %hu\nExtra Samples: %u\n", filepath, metadata.md5Hash, metadata.bitsPerSample, metadata.samplePerPixel, metadata.extraSamples);

                    TIFFClose(tiff);
                } else {
                   printf("Failed to open '%s'\n", filepath);
                }
            }
        }
        closedir (dir);
    } else {
        /* could not open directory */
        perror ("");
    }
}
```
Please note that this code is a simple demonstration of how you might implement such a function in C, and does not cover all error checking, edge cases or optimizations. You'd need to add appropriate error handling (including checks for memory allocation failures) and potentially optimize the solution for better performance or resource usage. 

