```c
#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <stdlib.h>

int renameFile(const char* originalFilename, char** newFilename) {
    if (originalFilename == NULL || strlen(originalFilename) == 0) {
        *newFilename = NULL;
        return -1; // Error code for empty filename
    }

    int upperCount = 0;
    int lowerCount = 0;
    char upperSequence[4] = "AAA";
    char lowerSequence[3] = "aa";

    size_t length = strlen(originalFilename);
    for (size_t i = 0; i < length && (upperCount < 3 || lowerCount < 2); ++i) {
        if (isupper(originalFilename[i])) {
            upperSequence[upperCount++] = originalFilename[i];
        } else if (islower(originalFilename[i])) {
            lowerSequence[lowerCount++] = originalFilename[i];
        }
    }

    char extension[32];
    sprintf(extension, "%s%c", lowerSequence, originalFilename[length-1]);

    *newFilename = malloc((strlen(upperSequence) + strlen(extension) + 1) * sizeof(char));
    if (*newFilename == NULL) {
        return -2; // Error code for memory allocation failure
    }

    sprintf(*newFilename, "%s%c", upperSequence, extension);

    return 0; // Success
}
```
This function renames a file by combining an alphanumeric sequence and the last character of the original filename. It checks each character in the original filename to construct the new name. The resulting string is dynamically allocated to avoid potential memory leaks, which would occur if the resultant string was stored on the stack.

Keep in mind that this implementation doesn't handle edge cases like filenames exceeding typical file system length constraints or filenames with special characters. It also assumes a standard ASCII character set and might need adjustments for different encodings. As always, thorough testing is required to verify its correctness.
']

