```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <string.h>

int run_multiple_commands(int count, char* commands[], char* envs[]) {
    int status;
    pid_t childPid;
    int success = 1;

    for (int i=0; i<count; ++i) {
        if ((childPid = fork()) == 0){ // Child process
            char *commandArgs[256]; 
            memset(commandArgs, 0, sizeof(char*)*256);
            int argCount = 0;
            char *token = strtok(commands[i], " ");
            while (token != NULL) {
                commandArgs[argCount++] = token;
                token = strtok(NULL, " ");
            }

            // Set environment variables for each command execution.
            char *envp[] = { envs[i], NULL };

            execve(commandArgs[0], commandArgs, envp); 
        } else if (childPid < 0){ // Fork failed
            perror("fork");
            success = 0;
        } else { // Parent process
            printf("Parent: Child's PID is %d\n", childPid);

            waitpid(childPid, &status, 0); 

            if (WIFEXITED(status)) {
                int exit_status = WEXITSTATUS(status);
                printf("Exit status of process %d was %d\n", childPid, exit_status);
                if (exit_status != 0) success = 0;  // If any command fails, set success to 0.
            } else {
                perror("execve");
                success = 0;
            }
        }
    }

    return success;
}
```

