using System;
using System.Diagnostics;
using System.IO;
using System.Threading;
using System.Configuration;

public class WebsiteManager {

    private static readonly object _lock = new object();

    public string AddAndStartWebsite(string directoryPath, string siteName) {

        if (!Directory.Exists(directoryPath)) return null;

        var webConfigPath = Path.Combine(directoryPath, "web.config");
        if(!File.Exists(webConfigPath)) return null;

        lock (_lock) {
            // Ensure directory path is valid and adheres to a predefined list of allowed paths
            var allowedPaths = ConfigurationManager.AppSettings["AllowedPaths"].Split(';');

            if (!allowedPaths.Contains(directoryPath)) throw new Exception("Invalid directory path");

            // Validate the site name to prevent the inclusion of invalid characters and to ensure it does not exceed a specified maximum length.
            var maxLength = Int32.Parse(ConfigurationManager.AppSettings["MaxSiteNameLength"]);
            if (siteName.Length > maxLength) throw new Exception("Invalid site name");

            // Implement logging
            Logger.LogInformation($"Adding website {siteName} at path {directoryPath}", "WebsiteManager");

            // Add and start the website
            var process = Process.Start(webConfigPath);

            if (process == null) throw new Exception("Failed to start process");
        }

        // Retrieve settings from external service
        try {
            var configurationServiceClient = new ConfigurationServiceClient();
            var siteSettings = configurationServiceClient.GetSiteSpecificSettings(siteName);

            // Apply settings
            // ...
        } catch (NetworkLatencyException e) {
            Logger.LogWarning("Failed to retrieve settings due to network latency", "WebsiteManager");
        } catch (ConfigurationServiceDownException e) {
            Logger.LogError("Configuration service is down", "WebsiteManager");

            return null;
        }

        // Gracefully stop the website
        process.CloseMainWindow();
        if (!process.WaitForExit(5000)) process.Kill();
    }

    public void StopWebsite() {
        var processes = Process.GetProcessesByName("iisexpress");

        foreach (var process in processes) {
            // Gracefully stop the website
            process.CloseMainWindow();
            if (!process.WaitForExit(5000)) process.Kill();
        }
    }
}
