    private final ExecutorService executor = Executors.newFixedThreadPool(10); // Adjust according to your needs
    private final Logger logger = Logger.getLogger("ImageConverter");

    public void processDirectory(Path dir) throws IOException {
        try (DirectoryStream<Path> stream = Files.newDirectoryStream(dir)) {
            for (Path entry : stream) {
                executor.submit(() -> {
                    if (Files.isRegularFile(entry)) {
                        processImage(entry);
                    } else if (Files.isDirectory(entry)) {
                        processDirectory(entry);
                    }
                });
            }
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error processing directory: " + dir, e);
        }
    }

    private void processImage(Path file) {
        if (!isSupportedFormat(file)) return;

        for (int i = 0; i < 3; i++) {
            try {
                ProcessBuilder pb = new ProcessBuilder("your-command", "args..."); // adjust with actual command and args
                Process process = pb.start();

                int exitCode = process.waitFor();
                if (exitCode == 0) return; // Success, break from loop
            } catch (Exception e) {
                logger.log(Level.WARNING, "Error processing file: " + file, e);
            }
        }

        logger.log(Level.SEVERE, "Failed to process file after 3 attempts: " + file);
    }

    private boolean isSupportedFormat(Path file) {
        String fileName = file.getFileName().toString();
        return fileName.endsWith(".jpg") || fileName.endsWith(".jpeg") || fileName.endsWith(".png");
    }
}
```
This code launches a separate thread for each image, which might lead to high memory usage for large directories. A more efficient approach would be to use an ExecutorService with a fixed number of threads and let it handle concurrency. 

