typedef struct {
    char* log_level;
    char* output_path;
    int max_file_size;
} LogConfig;

bool validate_config(const char *filename) {
    json_object *jobj = json_object_from_file(filename);

    // Check if jobj is NULL or not an object, return false in such case.
    if(!json_object_is_type(jobj, json_type_object)) {
        printf("Not a valid JSON object\n");
        return false;
    }

    struct json_object* log_levels;
    // Check if log levels are available and it is an array.
    if(!json_object_object_get_ex(jobj, "log_levels", &log_levels) || !json_object_is_type(log_levels, json_type_array)) {
        printf("No valid log levels in config file\n");
        return false;
    }

    // Check each log level and its output path.
    int len = json_object_array_length(log_levels);
    char** paths = malloc(len * sizeof(char*));
    for(int i = 0; i < len; i++) {
        json_object* log_config = json_object_array_get_idx(log_levels, i);

        // Validate the structure of each log config.
        if(!json_object_is_type(log_config, json_type_object)) {
            printf("Invalid log level configuration\n");
            return false;
        }

        struct json_object* output_path;
        // Check if output path exists and is a string.
        if(!json_object_object_get_ex(log_config, "output_path", &output_path) || !json_object_is_type(output_path, json_type_string)) {
            printf("Invalid output path\n");
            return false;
        }

        // Validate if the directory exists.
        struct stat st = {0};
        const char* dir = json_object_get_string(output_path);
        if (stat(dir, &st) == -1) {
            printf("Invalid directory\n");
            return false;
        }

        // Check for duplicate paths.
        for(int j = 0; j < i; j++) {
            if(strcmp(paths[j], dir) == 0) {
                printf("Duplicate output path\n");
                return false;
            }
        }

        paths[i] = strdup(dir);
    }

    free(paths);
    return true;
}
```
