bool isPNGValid(const string& filename) {
    // Open file
    ifstream pngFile(filename, ios::binary);

    // Check for valid PNG header (89 50 4E 47 0D 0A 1A 0A)
    char header[8];
    pngFile.read(header, 8);
    return !pngFile.fail() && memcmp(header, "\x89PNG\x0D\x0A\x1A\x0A", 8) == 0;
}
