```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using System.Net.Http;
using Newtonsoft.Json;

public class FileProcessor
{
    private readonly ILogger<FileProcessor> _logger;
    private readonly HttpClient _httpClient;
    private readonly IConfiguration _config;

    public FileProcessor(ILogger<FileProcessor> logger, HttpClient httpClient, IConfiguration config)
    {
        _logger = logger;
        _httpClient = httpClient;
        _config = config;
    }

    public async Task ProcessFilesAsync()
    {
        var paths = _config.GetSection("Paths").Get<string[]>();

        foreach (var path in paths)
        {
            try
            {
                if (!File.Exists(path))
                {
                    throw new FileNotFoundException("The file does not exist.", path);
                }

                var hash = ComputeHashAsync(path);

                _logger.LogInformation($"Successfully processed the file at {path}. Hash: {hash}");
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Failed to process the file at {path}.");

                var logData = new 
                {
                    Path = path,
                    ErrorMessage = ex.Message,
                    StackTrace = ex.StackTrace
                };

                await PostToCloudAsync(JsonConvert.SerializeObject(logData));
            }
        }
    }

    private string ComputeHashAsync(string filePath)
    {
        using var sha256 = SHA256.Create();
        using var stream = File.OpenRead(filePath);

        return BitConverter.ToString(sha256.ComputeHash(stream)).Replace("-", "").ToLowerInvariant();
    }

    private async Task PostToCloudAsync(string jsonData)
    {
        var content = new StringContent(jsonData, System.Text.Encoding.UTF8, "application/json");

        await _httpClient.PostAsync("cloud-api-url", content); // replace 'cloud-api-url' with your actual cloud API URL
    }
}
```
