use tokio::time::timeout;

struct Logger {
    log_sender: watch::Sender<String>,
}

impl Logger {
    fn new() -> Self {
        let (log_receiver, log_sender) = watch::channel(1024);
        spawn_blocking(move || {
            while let Err(e) = log_receiver.recv().await {
                println_snprintf("Log Error: %s", &e);
            }
        });
        Logger { log_sender }
    }

    fn log(&self, message: String) {
