```python
import json
from abc import ABC, abstractmethod
from collections import defaultdict
from threading import Lock

class DataObjectManager(ABC):
    registry = defaultdict(None)
    lock = Lock()

    @abstractmethod
    def to_json():
        pass

    @staticmethod
    def from_json():
        pass

    @classmethod
    def add_factory(cls, id, factory):
        with cls.lock:
            if id in cls.registry:
                raise ValueError("ID already exists")

            cls.registry[id] = factory

    @classmethod
    def create_instance(cls, id, json_data):
        with cls.lock:
            if id not in cls.registry:
                raise ValueError("ID does not exist")

            return cls.registry[id](json_data)

    def to_json(self):
        state = self.__dict__
        json_string = json.dumps(state, default=lambda o: '<not serializable>')
        return json_string
```
In the above code snippet, we have an abstract base class `DataObjectManager` that defines an interface for all subclasses of it to implement. This class has a registry of factory functions, a lock to ensure thread-safety and methods to add new factories and create instances using these factories.

