<?php
require_once 'vendor/autoload.php';
use Predis\Client as Redis; // Assuming you're using Predis as a Redis client for caching

class ClinicUpdater {
    private $db, $redis, $apiClient;

    public function __construct(PDO $pdo) {
        $this->db = $pdo;
        // Initialize a Predis client for Redis caching
        $this->redis = new Redis([
            'scheme' => 'tcp',
            'host'   => '127.0.0.1',
            'port'   => 6379,
        ]);
        // Initialize an API client with relevant configurations
        $this->apiClient = new APIClient(); 
    }

    public function updateClinics(array $clinicIds, string $status) {
        try {
            $this->db->beginTransaction();
            foreach ($clinicIds as $id) {
                // Check if clinic details are in cache or can be retrieved from database
                $cacheKey = "clinic_{$id}";
                $clinic = $this->redis->get($cacheKey);
                if (!$clinic) {
                    $query = 'SELECT * FROM clinics WHERE clinic_id=:clinicId';
                    $stmt = $this->db->prepare($query);
                    $stmt->execute(['clinicId' => $id]);
                    $clinic = $stmt->fetch();
                    // Cache clinic details for future use and set a TTL of 60 seconds to optimize memory usage
                    $this->redis->setex($cacheKey, 60, json_encode($clinic));
                } else {
                    $clinic = json_decode($clinic);
                }

                // If clinic details are not available via database or Redis, try retrieving from API
                if (!$clinic) {
                    try {
                        $clinic = $this->apiClient->getClinicDetails($id);
                    } catch (Exception $e) {
                        error_log("Error fetching clinic details for ID: {$id}. Error: " . $e->getMessage());
                        continue; // Skip to next clinic if API call fails
                    }
                }

                $query = 'UPDATE clinics SET status=:status, last_modified_date=NOW(), last_modified_ip=:ip WHERE clinic_id=:clinicId';
                $stmt = $this->db->prepare($query);
                $stmt->execute(['status' => $status, 'ip' => getUserIpAddr(), 'clinicId' => $id]);
            }
            $this->db->commit(); // Commit all changes if everything is successful
        } catch (Exception $e) {
            $this->db->rollBack(); // Rollback in case of any error to prevent data corruption
            throw new Exception("Failed to update clinics. Error: " . $e->getMessage());
        }
    }

    private function getUserIpAddr() {
        if (!empty($_SERVER['HTTP_CLIENT_IP'])) {
            $ip = $_SERVER['HTTP_CLIENT_IP'];
        } elseif (!empty($_SERVER['HTTP_X_FORWARDED_FOR'])) {
            $ip = $_SERVER['HTTP_X_FORWARDED_FOR'];
        } else {
            $ip = $_SERVER['REMOTE_ADDR'];
        }

        return $ip;
    }
}
```
