Here is the high-level C function to handle sensor data stream, calculate standard deviation and keep track of highest standard deviation:

```c
#include <stdlib.h>
#include <math.h>
#include "SensorData.h" // Include your SensorData structure here

typedef struct {
    int node_id;
    long timestamp; 
    float highest_standard_deviation;
} HighestStdDevNode;

HighestStdDevNode process_sensor_data(SensorData* data, size_t count) {
    HighestStdDevNode result = {0, 0, 0.0f};
    float sum = 0.0f;
    float sq_sum = 0.0f;

    for (size_t i = 0; i < count; ++i) {
        // Assuming that the data is sorted by timestamp and node_id, you might want to add checks here

        if (data[i].node_id != result.node_id || data[i].timestamp > result.timestamp + 15) {
            float mean = sum / count;
            float stddev = sqrtf(sq_sum/count - mean*mean);

            if (stddev > result.highest_standard_deviation) {
                result.node_id = data[i].node_id;
                result.timestamp = data[i].timestamp;
                result.highest_standard_deviation = stddev;
            }

            sum = 0.0f;
            sq_sum = 0.0f;
            count = 0;
        } 

        sum += data[i].signal_strength;
        sq_sum += data[i].signal_strength * data[i].signal_strength;
        ++count;
    }

    // Handle the last window separately if needed.

    return result;
}
```
This function processes sensor data in a single pass, efficiently calculating standard deviation for each 15 milliseconds window and keeping track of highest stddev across all nodes. Note that this is a simplified version. In a real-world scenario you would likely want to add error checking/handling code, potentially use more efficient data structures or algorithms, consider concurrency issues etc., which were not addressed in the scope of this question.
