['Here's an example of how this could be achieved. This program is not complete by any means but it provides a rough structure of what you might want to do. Note that in production code, error checking should be very thorough and the code would typically be much more complex with additional features and error handling.

```c
#include <openssl/evp.h>
#include <openssl/sha.h>
#include <unistd.h>
#include <sys/wait.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[32];  // AES-256 uses a 256 bit key (32 bytes)
    unsigned char iv[16];   // IV is always 128 bits (16 bytes)
} AesCipher;

AesCipher* init_cipher(const char *passphrase);
void cleanup_cipher(AesCipher *cipher);
int execute_command(const char *cmd);

// For simplicity, we will just use a SHA-256 hash of the passphrase as our key.
// In real code this would need to be done properly with a password-based KDF function.
AesCipher* init_cipher(const char *passphrase) {
    AesCipher *cipher = malloc(sizeof(AesCipher));
    if (cipher == NULL) {
        return NULL;  // Error handling omitted for simplicity
    }

    cipher->ctx = EVP_CIPHER_CTX_new();
    if (cipher->ctx == NULL) {
        free(cipher);
        return NULL;  // Error handling omitted for simplicity
    }

    SHA256((unsigned char*)passphrase, strlen(passphrase), cipher->key);

    RAND_bytes(cipher->iv, sizeof(cipher->iv));

    EVP_EncryptInit_ex(cipher->ctx, EVP_aes_256_cbc(), NULL, cipher->key, cipher->iv);

    return cipher;
}

void cleanup_cipher(AesCipher *cipher) {
    if (cipher != NULL) {
        EVP_CIPHER_CTX_free(cipher->ctx);
        free(cipher);
    }
}

int execute_command(const char *cmd) {
    pid_t pid = fork();

    if (pid == 0) {  // This is the child process
        execl("/bin/sh", "sh", "-c", cmd, NULL);
        _exit(EXIT_FAILURE);  // exec never returns
    } else if (pid < 0) {
        return -1;  // Error handling omitted for simplicity
    } else {  // This is the parent process
        int status;
        waitpid(pid, &status, 0);

        return WIFEXITED(status) ? WEXITSTATUS(status) : -1;
    }
}
```
In this code, `init_cipher` creates an AES-256-CBC cipher with a derived key from the given passphrase and returns a pointer to it. The `cleanup_cipher` function is used to safely free all resources associated with the cipher. 

The `execute_command` function forks a child process, which then executes the specified command in the background. It waits for the command to finish executing and returns its exit status. This program doesn't handle error conditions robustly and lacks many features you would typically find in a complete application like logging or error handling, but it gives you an idea of how these components might be structured.
