    std::string access_token;
    int expires_in;  // seconds until expiration
    TokenType token_type = TokenType::Bearer;
    std::optional<std::string> refresh_token;
};

class OAuth2Client {
public:
    explicit OAuth2Client(std::shared_ptr<HttpClient> httpClient) : m_httpClient(std::move(httpClient)) {}

    std::optional<OAuth2Token> getToken(const std::string& url, int maxRetries = 3) {
        for (int i = 0; i < maxRetries; ++i) {
            try {
                auto response = m_httpClient->get(url);

                // Parse the JSON response into an OAuth2Token object.
                OAuth2Token token = parseJsonResponse(response);

                if (token.token_type == TokenType::Bearer) {
                    cacheAccessToken(token, std::chrono::seconds{token.expires_in});

                    // Log metrics...
                    return token;
                } else {
                    throw std::runtime_error("Invalid token type: " + std::to_string(static_cast<int>(token.token_type)));
                }
            } catch (const std::exception& ex) {
                if (i == maxRetries - 1) {
                    // Log final failure...
                    return {};
                } else {
                    int delay = std::pow(2, i + 1);  // Exponential backoff

                    // Log retry attempt...
                    std::this_thread::sleep_for(std::chrono::seconds{delay});
                }
            }
        }

        return {};
    }

private:
    OAuth2Token parseJsonResponse(const std::string& json) { /* Implementation details go here... */ }
    void cacheAccessToken(const OAuth2Token& token, const std::chrono::seconds& expiration) { /* Implementation details go here... */ }

private:
    std::shared_ptr<HttpClient> m_httpClient;
};
```
