const ALLOWED_MIMETYPES = ['image/jpeg', 'application/pdf'];
const MAX_FILESIZE = 1024 * 1024 * 5; // 5MB

async function uploadFile(fileUrl, retries = 3) {
    const startTime = Date.now();
    try {
        logger.info(`Fetching file ${fileUrl}`);
        const response = await fetch(fileUrl);

        if (!response.ok) throw new Error('Failed to fetch file');

        const buffer = await response.buffer();

        validateFileSizeAndMimeType(buffer);

        logger.info(`Uploading file ${fileUrl}`);
        const storageLocation = await fileUploaderLibrary.uploadFile(buffer);

        generateMetadata({
            size: buffer.length,
            duration: Date.now() - startTime,
            location: storageLocation
        });
    } catch (error) {
        logger.error(`Failed to upload ${fileUrl}. Reason: ${error}`);
        if (retries > 0) {
            return uploadFile(fileUrl, retries - 1);
        } else {
            throw error;
        }
    }
}

function validateFileSizeAndMimeType(buffer) {
    const mimetype = getMimeType(buffer);
    if (!ALLOWED_MIMETYPES.includes(mimetype)) {
        throw new Error(`Invalid file type: ${mimetype}`);
    }

    if (buffer.length > MAX_FILESIZE) {
        throw new Error('File too large');
    }
}

function getMimeType(buffer) {
