['```c
#include <stdlib.h>
#include <semaphore.h>

typedef struct NFAPI_CRC_INDICATION_PDU {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct CRC_INDICATION_REL8_TAG* crc;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct CRC_INDICATION_REL8_TAG {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

sem_t semaphore;
NFAPI_CRC_INDICATION_PDU_T** list = NULL;
size_t size = 0;

void manageList(int permits) {
    if (sem_init(&semaphore, 0, permits)) {
        exit(EXIT_FAILURE);
    }

    while (1) {
        sem_wait(&semaphore);

        // Add new entry to list
        NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            exit(EXIT_FAILURE);
        }
        pdu->RX_UE_INFORMATION_TAG = 0; // set to default value
        pdu->RNTI = 0; // set to default value
        pdu->crc = malloc(sizeof(CRC_INDICATION_REL8_TAG));
        if (!pdu->crc) {
            free(pdu);
            exit(EXIT_FAILURE);
        }
        pdu->crc->CRCFLAG = rand() % 2; // set to random value

        NFAPI_CRC_INDICATION_PDU_T** newList = realloc(list, (size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (!newList) {
            free(pdu->crc);
            free(pdu);
            exit(EXIT_FAILURE);
        }
        list = newList;
        list[size++] = pdu;

        // Remove unused entries from list
        for (size_t i = 0; i < size; ++i) {
            if (!list[i]->crc->CRCFLAG) {
                free(list[i]->crc);
                free(list[i]);
                for (size_t j = i; j < size - 1; ++j) {
                    list[j] = list[j + 1];
                }
                --size;
            }
        }

        sem_post(&semaphore);
    }
}
```
