#include <openssl/ssl.h>
#include <openssl/err.h>

// Load certificate and private key
static int load_certificate(SSL_CTX *ctx, const char* certfile, const char* keyfile) {
    if (SSL_CTX_use_certificate_file(ctx, certfile, SSL_FILETYPE_PEM) <= 0) {
        return 0;
    }

    if (SSL_CTX_use_PrivateKey_file(ctx, keyfile, SSL_FILETYPE_PEM) <= 0 ) {
        return 0;
    }

    // Verify private key
    if (!SSL_CTX_check_private_key(ctx)) {
        return 0;
    }
    return 1;
}

// Initialize TLS connection with given certificate and private key
static SSL* initialize_tls_context(const char* certfile, const char* keyfile) {
    SSL_CTX *ctx = NULL;
    SSL *ssl = NULL;

    // Create new context
    ctx = SSL_CTX_new(TLSv1_3_method());
    if (ctx == NULL) {
        return NULL;
    }

    // Load certificate and private key
    if(!load_certificate(ctx, certfile, keyfile)) {
        goto err;
    }

    // Create new SSL structure
    ssl = SSL_new(ctx);
    if (ssl == NULL) {
        goto err;
    }

    return ssl;

err:
    if(ssl != NULL) SSL_free(ssl);
    if(ctx != NULL) SSL_CTX_free(ctx);

    return NULL;
}

// Clean up resources when the TLS context is no longer needed
void cleanup_tls_context(SSL *ssl) {
    SSL_CTX* ctx = SSL_get_SSL_CTX(ssl);

    // Free SSL structure
    SSL_free(ssl);

    // Free context
    SSL_CTX_free(ctx);
}
```
In above code, the `load_certificate` function handles loading a certificate and private key. It verifies that the private key matches the loaded certificate. The `initialize_tls_context` function creates a new TLS context using OpenSSL's high-level API (which abstracts away many of the details of setting up an SSL connection).

