#include <stdio.h>
#include <dirent.h>
#include <pthread.h>
#include <unistd.h>  // for usleep
#define MAX_THREADS 10

typedef struct {
    char file_path[256];
} thread_args;

void* process_file(void *arg) {
    // Cast argument to correct type
    thread_args* args = (thread_args*) arg;

    // Use read-write lock here if necessary
    usleep(10);  // Simulate some workload for concurrency testing
    return NULL;
}

void process_directory() {
    pthread_t threads[MAX_THREADS];
    thread_args args[MAX_THREADS];

    DIR *dir;
    struct dirent *ent;
    int i = 0, count = 0;

    if ((dir = opendir ("/path/to/your/directory")) != NULL) {
        while ((ent = readdir(dir)) != NULL) {
            snprintf(args[i].file_path, sizeof(args[i].file_path), "/path/to/your/directory/%s", ent->d_name);

            // Create thread if limit is not reached and sleep for a while to control concurrency
            if (count < MAX_THREADS) {
                pthread_create(&threads[i], NULL, process_file, &args[i]);
                count++;
                i = (i + 1) % MAX_THREADS;
            } else {
                // Wait for a thread to finish
                pthread_join(threads[i], NULL);

                // Replace the finished thread with a new one
                pthread_create(&threads[i], NULL, process_file, &args[i]);
            }
        }
        closedir (dir);
    } else {
        perror ("Error opening directory");
        return;
    }

    // Wait for all threads to finish
    for(int j = 0; j < count; ++j) {
        pthread_join(threads[j], NULL);
    }
}
``` 
