["Here's a basic outline of how you could implement this in C++17:

```cpp
#include <mutex>
#include <shared_mutex>
#include <atomic>
#include <thread>
#include <condition_variable>
#include <vector>
#include <algorithm>
#include <cstring>
#include <memory>

class NetworkEvent {
public:
    std::atomic<uint64_t> timestamp;
    uint32_t type, ifId, packetSize;
    char sourceIP[16]; // Assuming IPV4 only
};

using EventPtr = std::shared_ptr<NetworkEvent>;

class NetworkEvents {
private:
    struct Node {
        EventPtr event;
        Node* prev;
        Node* next;
        Node(const EventPtr& e) : event(e), prev(nullptr), next(nullptr) {}
    };

    std::shared_mutex mtx_;
    std::condition_variable cv_;
    Node* head_{nullptr};
    Node* tail_{nullptr};
    std::atomic<uint64_t> size_{0};

public:
    void pushFront(const EventPtr& event) {
        auto node = new Node(event);

        std::unique_lock lock(mtx_);
        if (head_) {
            head_->prev = node;
            node->next = head_;
            head_ = node;
        } else {
            tail_ = head_ = node;
        }
        size_.fetch_add(1);
    }

    void pushBack(const EventPtr& event) {
        auto node = new Node(event);

        std::unique_lock lock(mtx_);
        if (tail_) {
            tail_->next = node;
            node->prev = tail_;
            tail_ = node;
        } else {
            head_ = tail_ = node;
        }
        size_.fetch_add(1);
    }

    EventPtr popFront() {
        std::unique_lock lock(mtx_);

        if (!head_) return nullptr;

        auto event = head_->event;
        head_ = head_->next;
        delete head_->prev; // Delete node
        head_->prev = nullptr;
        size_.fetch_sub(1);

        cv_.notify_all();

        return event;
    }

    EventPtr popBack() {
        std::unique_lock lock(mtx_);

        if (!tail_) return nullptr;

        auto event = tail_->event;
        tail_ = tail_->prev;
        delete tail_->next; // Delete node
        tail_->next = nullptr;
        size_.fetch_sub(1);

        cv_.notify_all();

        return event;
    }

    uint64_t getSize() const {
        return size_;
    }

    void iterateEventsInOrder(std::function<void(const EventPtr&)> callback) const {
        std::shared_lock lock(mtx_);

        for (auto node = head_; node; node = node->next) {
            callback(node->event);
        }
    }

    void iterateEventsInReverseOrder(std::function<void(const EventPtr&)> callback) const {
        std::shared_lock lock(mtx_);

        for (auto node = tail_; node; node = node->prev) {
            callback(node->event);
        }
    }
};
```

