['Here is a skeleton code for managing dynamic list with thread safety:

```c
#include <stdlib.h>
#include <pthread.h>
#define MAX_SIZE 1000000 // Define maximum size limit here

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode* next;
} ListNode;

typedef struct HashTable {
    int size;
    pthread_mutex_t lock;
    ListNode** nodes;
} HashTable;

HashTable* createTable(int size) {
    HashTable* table = malloc(sizeof(HashTable));
    if (table == NULL) return NULL;

    table->nodes = calloc(size, sizeof(ListNode*));
    table->size = size;

    pthread_mutex_init(&table->lock, NULL); // Initialize lock here
}

// Hash function to get index for RNTI in the hash table
int hashFunction(int rnti, int size) {
    return (rnti % size);
}

void addElement(HashTable* table, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&table->lock); // Lock to ensure thread safety

    int index = hashFunction(data.RNTI, table->size);
    ListNode* node = malloc(sizeof(ListNode));
    node->data = data;
    node->next = table->nodes[index]; // Add new element at the beginning of the list for O(1) insertion

    if (node != NULL && table->nodes[index] == NULL) { 
        table->nodes[index] = node;
    } else {
        free(node); // If unable to allocate memory or duplicate RNTI found, free the allocated node
    }

    pthread_mutex_unlock(&table->lock); // Unlock after operation
}

void removeElement(HashTable* table, int rnti) {
    pthread_mutex_lock(&table->lock); // Lock to ensure thread safety

    int index = hashFunction(rnti, table->size);
    ListNode* prev = NULL;
    for (ListNode* node = table->nodes[index]; node != NULL; node = node->next) {
        if (node->data.RNTI == rnti) { // If RNTI found, remove the element
            if (prev != NULL) prev->next = node->next; 
            else table->nodes[index] = node->next; 
        }
        prev = node;
    }

    pthread_mutex_unlock(&table->lock); // Unlock after operation
}
```
Remember to implement more functionality such as updating existing elements, handling memory allocation/deallocation efficiently, automatic resizing when necessary and logging all operations for debug mode. The above code only demonstrates adding and removing elements with thread safety in consideration but does not handle the constraints like scalability and usability. You can extend it according to your needs.
