void* fetchSrsConfig() {
    // Fetch SRS configuration, might introduce latency or need to handle network failures
}

NFAPI_RX_FRAME_PDU_T* initializeNfaapiFrames(int batchSize) {
    assert(batchSize >= 0);
    if (batchSize < 0) {
        printf("Invalid batch size: %d\n", batchSize);
        return NULL;  // Gracefully handle invalid input
    }

    srand((unsigned int)time(NULL));  // Seed the random number generator
    NFAPI_RX_FRAME_PDU_T* frame = (NFAPI_RX_FRAME_PDU_T*) malloc(batchSize * sizeof(NFAPI_RX_FRAME_PDU_T));

    for (int i = 0; i < batchSize; ++i) {
        pthread_mutex_lock(&lock);  // Lock mutex before accessing shared data
        ++retryCount;
        if (retryCount > RETRIES_LEVEL) {
            printf("Failed to fetch SRS configuration after %d retries\n", retryCount);
            pthread_mutex_unlock(&lock);  // Unlock mutex before returning NULL
            return NULL;
        }
        void* srsConfig = fetchSrsConfig();
        if (srsConfig == NULL || *((int*)srsConfig) > MAX_SRS_CONFIG) {
            continue;  // Retry fetching SRS configuration
        }

        frame[i].NFAPI_RRC_RX_FRAME_IND_PDU_TAG = rand();  // Randomly generate NFAPI_RRC_RX_FRAME_IND_PDU_TAG

        if (strcmp(LOGGING_LEVEL, "DEBUG") == 0) {
            printf("Initialized frame %d with SRS configuration: %d\n", i, *((int*)srsConfig));
        }

        pthread_mutex_unlock(&lock);  // Unlock mutex after accessing shared data
    }

    retryCount = 0;  // Reset retry count for next call to initializeNfaapiFrames
    return frame;
}
