@lru_cache(maxsize=None)
def validate_token(token, url):
    for _ in range(VALIDATION_ATTEMPTS):
        try:
            response = requests.get(f'{url}/validate', headers={'Authorization': f'Bearer {token}'}, timeout=5)
            if response.status_code == 200:
                return True
        except Timeout:
            pass
    return False

def generateCRCIndicationsList(ue, externalDataSourceUrl):
    token = getTokenFromSomewhere() # Implement this function as needed

    if not validate_token(token, externalDataSourceUrl):
        print("Failed to validate token")
        return []

    indications = []

    for i in range(min(MAX_UE, len(ue))):
        try:
            response = requests.get(f'{externalDataSourceUrl}/data', headers={'Authorization': f'Bearer {token}'}, timeout=5)

            if response.status_code != 200:
                print("Invalid response from server")
                continue

            data = response.json()

            if 'crcIndication' not in data:
                print(f"Missing crcIndication for UE {i}")
                continue

            indications.append((ue[i], data['crcIndication']))
