NFAPI_CRC_INDICATION_PDU_T* populateStructArray(int n) {
    srand(time(NULL));  // Initialize random number generator.

    pthread_mutex_lock(&mutex);   // Lock the mutex for thread safety.

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(n, sizeof(NFAPI_CRC_INDICATION_PDU_T)); // Allocate memory for n structures.

    if (array == NULL) {
        fprintf(stderr, "Failed to allocate memory\n");
        pthread_mutex_unlock(&mutex);  // Unlock the mutex and return NULL in case of failure.
        return NULL;
    }

    int* RNTIs = (int*)calloc(n, sizeof(int));  // Create an array to store used RNTI.

    for (int i = 0; i < n; ++i) {
