        RNTIs[i] = rnti;    // Store the new RNTI in the used RNTI array.
    }

    free(RNTIs);   // Free the RNTI array as it's no longer needed.

    pthread_mutex_unlock(&mutex);  // Unlock the mutex after the operation is complete.
    return array;
}

int isRNTIExist(int rnti, int* RNTIs, int n) {
    for (int i = 0; i < n; ++i) {
        if (RNTIs[i] == rnti) return 1; // If the RNTI already exists in the array.
    }

    return 0;  
}
