```c
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *list = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int nextRNTI = 1; // Assuming RNTIs start from 1 and increment by 1 each time.

NFAPI_CRC_INDICATION_PDU_T *createNewNode() {
    NFAPI_CRC_INDICATION_PDU_T *newNode = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (newNode == NULL) {
        return NULL; // Indicate memory allocation failure.
    }

    newNode->RX_UE_INFORMATION_TAG = 0;
    newNode->CRC_INDICATION_REL8_TAG = 0;
    pthread_mutex_lock(&mutex);
    newNode->RNTI = nextRNTI++;
    pthread_mutex_unlock(&mutex);
    newNode->CRCFLAG = rand() % 2; // Assuming CRCFLAG is randomly set.

    return newNode;
}

void addToList(NFAPI_CRC_INDICATION_PDU_T *node) {
    if (node == NULL) {
        return;
    }

    pthread_mutex_lock(&mutex);

    node->next = list;
    list = node;

    pthread_mutex_unlock(&mutex);
}

void freeList() {
    NFAPI_CRC_INDICATION_PDU_T *currentNode = list, *nextNode;

    while (currentNode != NULL) {
        nextNode = currentNode->next;
        free(currentNode);
        currentNode = nextNode;
    }
}
```
This code creates a new node and adds it to the start of the list. It uses a mutex for thread safety, ensuring that only one thread can access the shared data structures at a time. The RNTI is incremented each time a new node is created, preventing duplicates across multiple executions. If memory allocation fails, NULL is returned and an error indication is provided. When done with the list, it should be freed to avoid leaks.
