    int tx_packets;
    int rx_bytes;
    char* iface_id;
} TCP_NODE_STATS;

typedef struct _doubly_linked_list {
    TCP_NODE_STATS data;
    pthread_mutex_t lock;
    struct _doubly_linked_list *next, *prev;
} DOUBLY_LINKED_LIST;

// Global list head.
DOUBLY_LINKED_LIST* node_head = NULL;
pthread_mutex_t head_lock = PTHREAD_MUTEX_INITIALIZER;

void insert(TCP_NODE_STATS stats) {
    // Create a new node.
    DOUBLY_LINKED_LIST* new_node = malloc(sizeof(*new_node));

    if (new_node == NULL) {
        // Handle memory allocation failure gracefully.
        return;
    }

    pthread_mutex_init(&new_node->lock, NULL);
    new_node->data = stats;

    // Lock the global list to prevent concurrent access by other threads.
    pthread_mutex_lock(&head_lock);

    if (node_head == NULL) {
        node_head = new_node;
        new_node->next = NULL;
        new_node->prev = NULL;
    } else {
        DOUBLY_LINKED_LIST* last = node_head;

        while (last->next != NULL) {
            pthread_mutex_lock(&(last->next->lock));
            if (last->data.tx_packets < stats.tx_packets) {
                // Log a warning message here or handle the node accordingly, e.g., free it and return.
                free(new_node);
                pthread_mutex_unlock(&head_lock);
                return;
            }

            last = last->next;
        }

        new_node->prev = last;
        last->next = new_node;
    }

    // Unlock the global list.
    pthread_mutex_unlock(&head_lock);
}
