```c
#include <pthread.h>
#include <sys/time.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>

typedef struct {
    int len; 
    char *payload;  
} Packet;

typedef struct {
    pthread_mutex_t mutex;
    Packet *packets[100000];
    size_t start, end, count;
} Buffer;

static inline uint64_t getTimeStamp() {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    return (uint64_t)tv.tv_sec * 1000000 + (uint64_t)tv.tv_usec;
}

static void logging_service(const char* message) {
    openlog("packetProcessing", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "%s", message);
    closelog();
}

void addPacket(Buffer *buffer, Packet *packet){
    pthread_mutex_lock(&buffer->mutex);
    if (buffer->count < 100000) {
        buffer->packets[buffer->end] = packet;
        buffer->end = (buffer->end + 1) % 100000;
        ++buffer->count;
    } else {
        logging_service("Packet dropped: Buffer is full");
        free(packet);
    }
    pthread_mutex_unlock(&buffer->mutex);
}

void processPackets(Buffer *buffer, void (*action)(const Packet*)){
    for (size_t i = 0; i < buffer->count; ++i) {
        action(buffer->packets[(buffer->start + i) % 100000]);
    }
}
```
