using Microsoft.EntityFrameworkCore;
using Newtonsoft.Json;
using System;
using System.Collections.Generic;
using System.Data;
using System.IO;
using System.Linq;
using System.Transactions;

public class SqlOperationConfig
{
    public string OperationType { get; set; } // SELECT, INSERT, UPDATE, DELETE
    public string Query { get; set; }
    public Dictionary<string, object> Parameters { get; set; }
}

public class DatabaseContext : DbContext
{
    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        var config = JsonConvert.DeserializeObject<Dictionary<string, string>>(File.ReadAllText("config.json"));
        optionsBuilder.UseSqlServer(config["DatabaseConnectionString"]);
    }
}

public class SqlOperationExecutor
{
    public void ExecuteOperationsFromConfig()
    {
        var config = JsonConvert.DeserializeObject<List<SqlOperationConfig>>(File.ReadAllText("operations_config.json"));
        using (var scope = new TransactionScope())
        {
            try
            {
                foreach (var operation in config)
                {
                    using (var context = new DatabaseContext())
                    {
                        switch (operation.OperationType)
                        {
                            case "SELECT":
                                var resultSet = context.Database.SqlQuery<dynamic>(operation.Query, operation.Parameters?.Select(kvp => new KeyValuePair<string, object>(kvp.Key, kvp.Value)).ToArray()).ToList();
                                Console.WriteLine("SELECT query executed successfully!");
                                break;
                            case "INSERT":
                            case "UPDATE":
                            case "DELETE":
                                context.Database.ExecuteSqlCommand(operation.Query, operation.Parameters?.Select(kvp => new KeyValuePair<string, object>(kvp.Key, kvp.Value)).ToArray());
                                Console.WriteLine($"{operation.OperationType} query executed successfully!");
                                break;
                            default:
                                throw new NotSupportedException("Unsupported operation type");
                        }
                    }
                }
                scope.Complete(); // Commit transaction
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Transaction rolled back due to error: {ex}");
            }
        }
    }
}
```

The `operations_config.json` file should contain an array of `SqlOperationConfig` objects, each representing a SQL command with its type and parameters.

