#include <algorithm>
#include <vector>

void insertAfterOrAppend(std::vector<int>& v, int target, int value) {
    auto it = std::find(v.begin(), v.end(), target);

    if (it != v.end()) {
        // If the target is found, insert value after target and maintain heap property
        bool done = false;
        while (!done && ++it != v.end()){
            if (*it > value) {
                v.insert(it, value);
                done = true;
            }
        }
        if(!done) v.push_back(value);
    } else {
        // If the target is not found, append value to end of vector and maintain heap property
        v.push_back(value);
        std::push_heap(v.begin(), v.end());
    }
}
```
This function works by using the `std::find` algorithm to search for the target integer in the vector. If it is found, it uses an iterator to insert the value after the target and maintains heap property. If the target is not found, it appends the value to the end of the vector and uses `std::push_heap` to maintain heap property.
