using System;
using System.IO;
using System.Xml;
using System.Xml.XPath;

public class XmlParser
{
    private static readonly object _lock = new object();

    public string Parse(string filePath, string elementName)
    {
        try
        {
            var doc = new XmlDocument();
            doc.Load(filePath);

            var navigator = doc.CreateNavigator();
            var iterator = navigator.Select($"//{elementName}");

            if (iterator.MoveNext())
            {
                var elementValue = iterator.Current?.Value;

                if (!string.IsNullOrEmpty(Environment.GetEnvironmentVariable("XML_DIR_PATH")))
                    return elementValue;

                lock (_lock)
                {
                    if (string.IsNullOrEmpty(Environment.GetEnvironmentVariable("XML_DIR_PATH")))
                    {
                        var dirName = Path.Combine(Path.GetTempPath(), elementValue);
                        Directory.CreateDirectory(dirName);

                        Environment.SetEnvironmentVariable("XML_DIR_PATH", dirName, EnvironmentVariableTarget.Process);
                    }
                }

                return elementValue;
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error parsing XML: {ex.Message}");
        }

        return string.Empty;
    }
}
```
