using System;
using System.Xml;
using System.Configuration;
using System.Net;
using Polly;

public class XmlParser
{
    private static readonly object cacheLock = new object();
    private static Dictionary<string, (DateTime, XmlElementInfo)> _cache = 
        new Dictionary<string, (DateTime, XmlElementInfo)>();

    public static void Main() {} // Your program logic here

    public async Task<XmlElementInfo> Parse(string pathOrUrl, string xPathExpression, 
                                          IDictionary<string, string> attributeFilters = null)
    {
        bool isRemote = Uri.TryCreate(pathOrUrl, UriKind.Absolute, out _);

        XmlDocument xmlDoc;
        if (isRemote)
        {
            var policy = Policy
                .Handle<WebException>()
                .WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));

            xmlDoc = await policy.ExecuteAsync(async () => 
            {
                using var webClient = new WebClient();
                byte[] data = await webClient.DownloadDataTaskAsync(new Uri(pathOrUrl));
                return ParseXmlFromBytes(data);
            });
        }
        else if (File.Exists(pathOrUrl))
        {
            xmlDoc = new XmlDocument();
            xmlDoc.Load(pathOrUrl);
        }
        else
        {
            byte[] data = Convert.FromBase64String(pathOrUrl);
            xmlDoc = ParseXmlFromBytes(data);
        }

        var cacheKey = $"{pathOrUrl}{xPathExpression}";
        lock (cacheLock)
        {
            if (_cache.TryGetValue(cacheKey, out var cached) && 
                DateTime.UtcNow - cached.Item1 < TimeSpan.FromMinutes(10))
            {
                return cached.Item2;
            }
        }

        XmlElementInfo element = ParseXmlDocument(xmlDoc, xPathExpression, attributeFilters);

        lock (cacheLock)
        {
            _cache[cacheKey] = (DateTime.UtcNow, element);
        }

        return element;
    }

    private XmlElementInfo ParseXmlDocument(XmlDocument xmlDoc, string xPathExpression, 
                                            IDictionary<string, string> attributeFilters)
    {
       // Your logic here
    }

    private static XmlDocument ParseXmlFromBytes(byte[] data)
    {
        try
        {
            var xmlDoc = new XmlDocument();
            xmlDoc.Load(new MemoryStream(data));
            return xmlDoc;
        }
        catch (Exception ex) when (ex is WebException || ex is IOException || ex is XmlException)
        {
           LogError($"Failed to parse XML document: {ex}");
           throw;
        }
    }

    private static void LogError(string message)
    {
       // Your logic here to log errors using centralized logging service.
    }

    public struct XmlElementInfo
    {
       // Your struct for XML element info here.
    }
}
```

The `XmlParser` class encapsulates the functionality of parsing and caching XML data from various sources. It uses Polly to handle retry logic for remote document fetches and locks when accessing the cache dictionary to ensure thread safety. 

However, please note that handling XML documents up to 50MB size in memory is not a recommended practice due to its high memory consumption. You should consider using SAX or StAX parsers instead if you are dealing with such large files.
