typedef struct Node{
    LTE_PHY_RX_BUFFER_INFO info;
    struct Node *next;
}Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

Node *head = NULL;

void add(LTE_PHY_RX_BUFFER_INFO data){
    pthread_mutex_lock(&lock);
    Node *newNode = (Node *) malloc(sizeof(Node));
    newNode->info = data;
    newNode->next = head;
    head = newNode;
    pthread_mutex_unlock(&lock);
}

LTE_PHY_RX_BUFFER_INFO* get(int CELL_ID, int SUBFRAMENO){
    Node *temp=head;
    while(temp != NULL){
        if(temp->info.CELL_ID == CELL_ID && temp->info.SUBFRAMENO==SUBFRAMENO) {
            return &(temp->info);
        }
        temp = temp->next;
    }
    return NULL;
}

void update(int CELL_ID, int SUBFRAMENO, LTE_PHY_RX_BUFFER_INFO data){
    pthread_mutex_lock(&lock);
    Node *temp=head;
    while(temp != NULL){
        if(temp->info.CELL_ID == CELL_ID && temp->info.SUBFRAMENO==SUBFRAMENO) {
            temp->info = data;
            break;
        }
        temp = temp->next;
    }
    pthread_mutex_unlock(&lock);
}

void delete(){
    Node *temp=head,*prev=NULL;
    while(temp != NULL){
        prev=temp;
        temp = temp->next;
        free(prev);
    }
    head=NULL;
}
