['Here's a simple C implementation of this task using POSIX threads for DNS resolution and Linux-specific APIs like `getaddrinfo` for IP address lookup. This code doesn't include all optimizations (like caching or bulk DNS lookups) but it serves as a starting point:

```c
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <netdb.h>
#include <arpa/inet.h>

typedef struct {
    char** hostnames;
    int num_hosts;
} ResolveParams;

void* resolve(void *params) {
    ResolveParams* rp = (ResolveParams*) params;
    for(int i = 0; i < rp->num_hosts; ++i) {
        printf("Resolving %s...\n", rp->hostnames[i]);

        struct addrinfo hints, *res, *p;
        int status;
        char ipstr[INET6_ADDRSTRLEN];

        memset(&hints, 0, sizeof(hints));
        hints.ai_family = AF_UNSPEC; // Use IPv4 or IPv6, whichever has a response first
        hints.ai_socktype = SOCK_STREAM;

        if((status = getaddrinfo(rp->hostnames[i], NULL, &hints, &res)) != 0) {
            fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
            continue; // Skip to next hostname on failure
        }

        int num_ips = 0;
        for(p = res; p != NULL && num_ips < 5; p = p->ai_next) {
            void *addr;
            char *ipver;

            // Get the pointer to the address, different fields in IPv4 and IPv6:
            if (p->ai_family == AF_INET) { // IPv4
                struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
                addr = &(ipv4->sin_addr);
                ipver = "IPv4";
            } else { // IPv6
                struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
                addr = &(ipv6->sin6_addr);
                ipver = "IPv6";
            }

            // Convert the IP to a string and print it:
            inet_ntop(p->ai_family, addr, ipstr, sizeof(ipstr));
            printf(" %s: %s\n", ipver, ipstr);
            ++num_ips;
        }

        freeaddrinfo(res); // Free the linked list
    }

    return NULL;
}
```

This function spawns a separate thread for each hostname resolution. It uses `getaddrinfo` to fetch IP addresses and prints them out in human-readable format. The maximum number of IPs per host is set to 5, but it can be easily adjusted by changing the condition in the loop that fetches and prints addresses.

Remember, this code only deals with DNS resolution and printing addresses to standard output - it doesn't return the results nor does it handle errors or edge cases such as network failures. You might want to add error handling and adjust other parts of the function according to your specific needs. Also, remember that real-world applications often need more complex solutions for performance optimization, like DNS caching, bulk lookups, etc.
']

