List* list_init(size_t initialCapacity) {
    List* list = (List*)malloc(sizeof(List));
    if (list == NULL) {
        return NULL; // handle memory allocation failure
    }

    list->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list->data == NULL) {
        free(list);
        return NULL; // handle memory allocation failure
    }

    list->capacity = initialCapacity;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL); // initialize the mutex

    return list;
}

void list_append(List* list, NFAPI_CRC_INDICATION_PDU_T item) {
    if (list == NULL) {
        return;  // handle invalid input
    }

    pthread_mutex_lock(&list->mutex);  // lock the mutex to ensure thread safety

    if (list->size >= list->capacity) {
        size_t newCapacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* newData = realloc(list->data, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (newData == NULL) {
            pthread_mutex_unlock(&list->mutex);  // unlock the mutex before returning
            return; // handle memory allocation failure
        }

        list->data = newData;
        list->capacity = newCapacity;
    }

    list->data[list->size++] = item;  // add the item to the end of the list
    pthread_mutex_unlock(&list->mutex);  // unlock the mutex after modifying data
}
