['Here is an example of how you could implement such a system in C. Note, this code does not handle network communication or concurrent access from multiple nodes, but it provides the basic framework for managing logging and log rotation. 

```c
#include <stdio.h>
#include <string.h>
#include <stdarg.h>
#include <pthread.h>
#include <sys/stat.h>

#define MAX_FILESIZE (10 * 1024 * 1024) // 10MB in bytes

typedef void (*log_callback)(void);

enum loglevel {
    DEBUG,
    INFO,
    WARNING,
    ERROR
};

static enum loglevel current_level = WARNING;
static log_callback callback = NULL;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void set_log_level(enum loglevel level) {
    current_level = level;
}

void set_log_callback(log_callback cb) {
    callback = cb;
}

int log_message(const char *filename, enum loglevel level, const char *format, ...) {
    if (level < current_level) return 0; // ignore log messages below the current level

    pthread_mutex_lock(&mutex);

    FILE *fp = fopen(filename, "a");
    if (!fp) {
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    char buffer[4096]; // Maximum message size (adjust as needed)

    va_list args;
    va_start(args, format);
    vsnprintf(buffer, sizeof(buffer), format, args);
    va_end(args);

    struct stat st;
    if (!stat(filename, &st)) {
        // Check file size and rotate if needed (90% of MAX_FILESIZE)
        if (st.st_size > MAX_FILESIZE * 0.9) {
            fclose(fp);
            rename(filename, "old.log");

            // Notify via callback function
            if (callback != NULL) callback();

            fp = fopen(filename, "a");
        }
    }

    if (!fp) {
        pthread_mutex_unlock(&mutex);
        return -1; // Unable to open file for writing
    }

    fprintf(fp, "%s\n", buffer);
    fclose(fp);

    pthread_mutex_unlock(&mutex);

    return 0;
}
```

In a distributed system you would need to implement network communication and handle concurrent access. You could use a central server that manages the log files, or each node could have its own local server managing logging and rotation.
