["Here is a Python code block that implements this functionality using concurrent futures to control parallelism, asyncio for handling I/O operations, and hashlib to calculate SHA-256 hashes. This solution assumes the files are readable and can be opened without issues. A custom exception `FileAccessException` is raised when a file access issue occurs.

```python
import os
import hashlib
from concurrent import futures
import asyncio

class FileAccessException(Exception): pass

def calculate_sha256(filepath, block_size=8192):
    with open(filepath, 'rb') as f:
        hasher = hashlib.sha256()
        for chunk in iter(lambda: f.read(block_size), b''):
            hasher.update(chunk)
    return hasher.hexdigest()

async def process_file(executor, filepath):
    loop = asyncio.get_running_loop()
    try:
        return await loop.run_in_executor(executor, calculate_sha256, filepath)
    except Exception as e:
        raise FileAccessException(f'Error accessing {filepath}: {str(e)}') from e

async def process_directory(executor, directory, max_workers):
    hashes = {}
    with futures.ThreadPoolExecutor(max_workers=max_workers) as pool:
        tasks = []
        for root, _, files in os.walk(directory):
            for file in files:
                filepath = os.path.join(root, file)
                if not os.path.islink(filepath):  # exclude symbolic links
                    task = asyncio.create_task(process_file(pool, filepath))
                    tasks.append((filepath, task))
        for filepath, task in tasks:
            try:
                hashes[filepath] = await task
            except FileAccessException as e:
                print(str(e))
    return hashes

def process_directory_structure(directory, max_workers=None):
    loop = asyncio.get_event_loop()
    try:
        return loop.run_until_complete(process_directory(None, directory, max_workers or os.cpu_count()))
    finally:
        loop.close()
```

This code can be used by calling `process_directory_structure` with a path to the root of your directory structure and an optional maximum number of threads (defaulting to the number returned by `os.cpu_count()`). The result is a dictionary containing file paths as keys and their SHA-256 hashes as values.
"]

