['Here is a code snippet using Jackson for JSON parsing. The caching system used here is `Google's Guava` library which provides powerful in-memory caching capabilities such as size based eviction and time based expiration. 

```java
import com.fasterxml.jackson.databind.ObjectMapper;
import com.google.common.cache.CacheBuilder;
import com.google.common.cache.CacheLoader;
import com.google.common.cache.LoadingCache;
import java.io.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class StateLoader {

    private static final Logger logger = LoggerFactory.getLogger(StateLoader.class);

    private LoadingCache<String, MoSTState> cache;
    private ObjectMapper objectMapper = new ObjectMapper();

    public StateLoader(int maxSize) {
        this.cache = CacheBuilder.newBuilder()
                .maximumSize(maxSize) 
                .build(new CacheLoader<String, MoSTState>() {
                    @Override
                    public MoSTState load(String filePath) throws Exception {
                        return deserializeFromFile(filePath);
                    }
                });
    }

    public MoSTState getState(String filePath, FileFormat format) {
        try {
            if (format == FileFormat.JSON) 
                return objectMapper.readValue(new File(filePath), MoSTState.class);
             else if (format == FileFormat.SERIALIZED)
                return deserializeFromFile(filePath);
            else
                throw new IllegalArgumentException("Unsupported format: " + format);
        } catch (IOException e) {
            logger.error("Error while deserializing file: {}", filePath, e);
            return null;
        }
    }

    private MoSTState deserializeFromFile(String fileName) throws IOException, ClassNotFoundException {
        FileInputStream fis = new FileInputStream(fileName);
        ObjectInputStream ois = new ObjectInputStream(fis);
        MoSTState state = (MoSTState) ois.readObject();
        ois.close();
        return state;
    }

    public enum FileFormat { JSON, SERIALIZED }
}
```

Note: The `deserializeFromFile` method is designed to handle exceptions by returning null when an error occurs and logging the error for debugging purposes. It's important to note that this code only supports two file formats (JSON and Serialized Java Object), but it can be easily extended to support more formats as needed. 

For example, if you were to add XML format:
