```cpp
#include <boost/regex.hpp>
#include <forward_list>
#include <string>
#include <stdexcept>

void insertBookAfterOccurrence(std::forward_list<std::string>& text, 
                               const std::string& chapterNameRegexPattern, 
                               const std::string& textToInsert) {
    boost::regex regex;

    try {
        // Configure regex pattern from user input
        regex = boost::regex(chapterNameRegexPattern);
    } catch (const boost::bad_expression& e) {
        throw std::runtime_error("Invalid regular expression: " + chapterNameRegexPattern);
    }

    // Locate the first occurrence of a specified chapter name in the forward list
    bool found = false;
    for (auto it = text.begin(); it != text.end(); ++it) {
        if (boost::regex_match(*it, regex)) {
            // Insert the text after the match
            text.insert_after(it, textToInsert);
            found = true;
            break;
        }
    }

    if (!found) {
        // If no match is found, insert at the end of the list
        text.push_front(textToInsert);
    }
}
```

Note: The above code has to be adapted according to your specific requirements including handling punctuation, special characters and counting occurrences, error handling and system dependencies (like external data sources). Moreover, it doesn't take into account any performance optimization as that can vary depending on the use case. This is a basic implementation just to illustrate how you might structure such a function in C++ based on your requirements.
