import java.util.*;
import java.time.Duration;
import java.time.Instant;
import java.lang.Thread;
import java.lang.Runnable;
import java.util.concurrent.*;

class Pair {
    int first, second;

    public Pair(int first, int second) {
        this.first = first;
        this.second = second;
    }
}

public class DistributedArrayProcessor {
    private final ConcurrentHashMap<Pair, Boolean> cache = new ConcurrentHashMap<>();
    ExecutorService executor = Executors.newFixedThreadPool(10); // Adjust this according to system capacity 

    public void processArray(int[] array) throws InterruptedException {
        List<Future<?>> futures = new ArrayList<>();
        for (int i = 0; i < array.length - 1; ++i) {
            for (int j = i + 1; j < array.length; ++j) {
                int firstElement = array[i];
                int secondElement = array[j];
                Pair pair = new Pair(firstElement, secondElement);

                futures.add(executor.submit(() -> {
                    Instant startTime = Instant.now();

                    if (!cache.containsKey(pair)) {
                        // Replace with actual union-find disjointness check operation here
                        boolean areDisjoint = !(firstElement == secondElement);

                        cache.put(pair, areDisjoint);
                        System.out.println("Checked pair (" + firstElement + ", " + secondElement + ") in: " 
                                        + Duration.between(startTime, Instant.now()).toMillis() + " ms");
                    }
                }));
            }
        }

        for (Future<?> future : futures) {
            try {
                future.get(); // Waits until the associated computation is done
            } catch (ExecutionException ee) {
                System.out.println("Exception encountered while processing pair: " + ee);
            }
        }

        executor.shutdown();
    }
}
```

**Note: The above code assumes a simple disjointness check where elements are equal, you would need to replace the `areDisjoint` computation with your own actual union-find disjointness check operation. Also note that the system-specific configurations like thread pool size and cache policy would vary based on the specifics of the distributed system in which this function is used.**
