}

impl Default for HttpClient {
    fn default() -> Self {
        Self {
            client: Mutex::new(reqwest::ClientBuilder::new().build().unwrap()),
        }
    }
}

impl HttpClient {
    pub fn new_client(&self, disable_certificate_validation: bool) -> reqwest::RequestBuilder {
        let mut client = self.client.lock().unwrap();

