```java
import java.io.*;
import java.sql.*;
import java.util.*;
import org.apache.commons.dbcp2.*;

public class EmployeeService {
    // Assume there is a configuration file where we store driver and URL
    private static final String DB_CONFIG = "databaseConfig.properties";

    public List<Employee> retrieveEmployeeDetails(int supervisorID, String connectionString, String filePath) throws SQLException {
        BasicDataSource dataSource = new BasicDataSource();

        try (InputStream inputStream = new FileInputStream(DB_CONFIG)) {
            Properties properties = new Properties();
            properties.load(inputStream);

            dataSource.setDriverClassName(properties.getProperty("driver"));
            dataSource.setUrl(String.format(properties.getProperty("url"), connectionString));
        } catch (IOException e) {
            throw new SQLException("Failed to load database configuration", e);
        }

        List<Employee> employees = new ArrayList<>();

        try (Connection conn = dataSource.getConnection()) {
            String query = "SELECT name, city, address FROM Employees WHERE supervisor_id = ?";

            try (PreparedStatement ps = conn.prepareStatement(query)) {
                ps.setInt(1, supervisorID);

                try (ResultSet rs = ps.executeQuery()) {
                    while (rs.next()) {
                        Employee employee = new Employee();

                        employee.setName(rs.getString("name"));
                        employee.setCity(rs.getString("city"));
                        employee.setAddress(rs.getString("address"));

                        employees.add(employee);
                    }
                }
            } catch (SQLException e) {
                throw new SQLException("Failed to retrieve employee details", e);
            }
        } catch (SQLException e) {
            throw new SQLException("Failed to establish database connection", e);
        }

        return employees;
    }

