typedef struct State {
    int value;
    bool visited;
    pthread_mutex_t lock;
    struct State* next;
} State;

typedef struct FSA {
    // Define your FSA structure here
} FSA;

State** buildLinkedList(int *states, int numStates, FSA *fsa, int lastState, bool isFinalState) {
    if (!states || !numStates || !fsa) return NULL;

    State **head = malloc(sizeof(State*) * numStates);
    if (!head) return NULL;

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);

    for (int i = 0; i < numStates; ++i) {
        State *state = malloc(sizeof(State));

        if (!state || pthread_mutex_init(&state->lock, &attr)) {
            free(state);
            return NULL;
        }

        state->value = states[i];
        state->visited = false;
        state->next = NULL;

        head[i] = state;
    }

    pthread_mutexattr_destroy(&attr);

    for (int i = 0; i < numStates; ++i) {
        State *lastState = head[i];
        int depth = 3;

        while (depth-- > 0) {
            // implement your FSA transition and state exploration logic here
            // update the next pointer of the last state in the current list 

            pthread_mutex_lock(&lastState->lock);
            if (!lastState->visited) {
                lastState->visited = true;

                // Implement your FSA transition and exploration logic here
                // Use a cycle detection algorithm to avoid creating cycles in the linked list.

                pthread_mutex_unlock(&lastState->lock);
            } else {
                pthread_mutex_unlock(&lastState->lock);
                break;
            }
        }
    }

    return head;
}
