std::unordered_map<std::string, std::shared_ptr<Octree>> cache; 
std::mutex mtx; 

void initializeOctree(const std::string& path, int featureSize, int numLeafNodes, int dataCapacity, bool async = false) {
    try {
        if (cache.count(path)) return; // Already in cache

        std::shared_ptr<Octree> octree; 

        if (async) {
            std::thread t([&]() {
                octree = std::make_shared<Octree>();
                octree->init(featureSize, numLeafNodes, dataCapacity);
            });

            t.detach(); // Run in background
        } else {
            octree = std::make_shared<Octree>();
            octree->init(featureSize, numLeafNodes, dataCapacity);
        }

        if (octree == nullptr) throw std::runtime_error("Failed to initialize Octree");

        std::lock_guard<std::mutex> lock(mtx); 
        cache.emplace(path, octree); // Add to cache
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << "\n";
    }
}

