char** processStrings(const char* strings[], int sizes[], bool strictFlags[], int num, int* newNum) {
    *newNum = 0;
    char** result = malloc(num * sizeof(char*));  // Dynamically allocate memory for the result array.
    if (!result) return NULL;

    for (int i = 0; i < num; ++i) {
        int len = strlen(strings[i]);

        if ((strictFlags[i] && len <= sizes[i]) || (!strictFlags[i] && len < sizes[i])) {  // Check whether the string needs to be appended.
            result[*newNum] = malloc(len + 2);  // Dynamically allocate memory for each new string (add two for the slash and null-terminator).

            if (!result[*newNum]) {  // If allocation fails, clean up already allocated memory.
                for (int j = 0; j < *newNum; ++j) free(result[j]);
                free(result);
                return NULL;
            }

            strcpy(result[*newNum], strings[i]);  // Copy the original string to the new memory.
            result[*newNum][len] = '/';  // Append a slash at the end of each string that needs to be appended.
            result[(*newNum)++][len + 1] = '\0';  // Null-terminate the string and increment the counter.
        }
    }

    return result;
}
