// The hash map will be an array of linked lists
#define SIZE 1000
Node* hashMap[SIZE];

unsigned long hash(char *str) {
    unsigned long hash = 5381;
    int c;

    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash % SIZE; // we use modulo to limit the size of our array
}

