    *N = info.samplesPerPixel; // Assuming one PDU per sample

    *array = (NFAPI_CRC_INDICATION_PDU_T *) malloc(*N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(-1);
    }

    srand(time(NULL)); // seed the random number generator

    for (int i = 0; i < *N; i++) {
        (*array)[i].RX_UE_INFORMATION_TAG = ((uint64_t) rand() <<32 ) | rand(); // random 128 bit number

