Here is a basic implementation of your requirement:

```csharp
using System;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;

public class ServiceRegistrar<TService, TImplementation> where TImplementation : TService
{
    private readonly ILogger<ServiceRegistrar<TService, TImplementation>> _logger;

    public ServiceRegistrar(ILogger<ServiceRegistrar<TService, TImplementation>> logger)
    {
        _logger = logger;
    }

    public void RegisterService(IServiceCollection services, IConfiguration configuration)
    {
        try
        {
            // Here we will validate the settings for our service. 
            ValidateSettings<TImplementation>(configuration);

            // If the validation succeeds, we register the service.
            services.AddScoped<TService, TImplementation>();
        }
        catch (Exception ex)
        {
