```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Configuration;

public class AesDecrypter
{
    private readonly ILogger<AesDecrypter> _logger;
    private readonly string _key;
    private readonly Encoding _encoding;
    private readonly PaddingMode _paddingMode;

    public AesDecrypter(ILogger<AesDecrypter> logger, IConfiguration config)
    {
        this._logger = logger;
        this._key = config["Key"]; // Get the encryption key from configuration

        // Determine encoding based on a file extension or header information
        string encodingString = config["Encoding"]; 
        switch (encodingString)
        {
            case "hex": 
                _encoding = Encoding.GetEncoding("HEX");
                break;
            case "base64": 
                _encoding = Encoding.UTF8; // You need to use UTF-8 for Base64 encoding
                break;
            default: 
                throw new ArgumentException($"Unsupported encoding {encodingString}");
        }

        string paddingModeString = config["PaddingMode"];
        switch (paddingModeString)
        {
            case "PKCS7":
                _paddingMode = PaddingMode.PKCS7;
                break;
            case "Zeros": 
                _paddingMode = PaddingMode.Zeros;
                break;
            default: 
                throw new ArgumentException($"Unsupported padding mode {paddingModeString}");
        }
    }

    public byte[] Decrypt(string cipherText, string iv)
    {
        // Validate the IV length
        if (iv.Length != 16 && this._encoding == Encoding.UTF8)
            throw new ArgumentException("Invalid IV length");

        // Convert the IV to byte array
        byte[] ivBytes = this._encoding.GetBytes(iv);

        using var aesAlg = Aes.Create();
        aesAlg.Key = Encoding.UTF8.GetBytes(_key); 
        aesAlg.IV = ivBytes;
        aesAlg.Padding = _paddingMode;

        ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

        using var msDecrypt = new MemoryStream();
        using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Write))
        {
            try 
            {   
                // Convert the ciphertext to byte array and write it into crypto stream
                var cipherTextBytes = this._encoding.GetBytes(cipherText);
                csDecrypt.Write(cipherTextBytes, 0, cipherTextBytes.Length);
            }
            catch (Exception ex)
            {
               // Log detailed error information for debugging purposes
               _logger.LogError("Failed to decrypt data", ex);
               throw;
            }
        }

        return msDecrypt.ToArray(); // Return the decrypted plaintext as a byte array
    }
}
```
