```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>
#define TABLE_SIZE 100 // You can adjust the table size based on your system requirements
typedef struct item {
    long identifier;
    int value;
} Item;

typedef struct node {
    Item* item;
    struct node *next;
} Node;

Node* hashTable[TABLE_SIZE];  // Our primary data structure
pthread_mutex_t locks[TABLE_SIZE]; 
int cleanupFrequency = 60;   // In seconds, you can change it based on your requirement.

// Initialize the hash table and locks
void initialize() {
    for (int i = 0; i < TABLE_SIZE; ++i) {
        hashTable[i] = NULL;
        pthread_mutex_init(&locks[i], NULL);
    }
}

// Hash function to map the identifier into an index in our hash table
unsigned long hash(long identifier) {
    return identifier % TABLE_SIZE;
}

void addItem(Item* item){
    if (item == NULL) {
        printf("Invalid Item\n");
        return;
    }
    unsigned long index = hash(item->identifier);

    pthread_mutex_lock(&locks[index]); // Locking for thread safety
    Node* newNode = malloc(sizeof(Node)); 
    if (newNode == NULL) {
        printf("Memory Allocation Failure\n");
        return;
    }
    newNode->item = item;
    newNode->next = hashTable[index]; 
    hashTable[index] = newNode;

    pthread_mutex_unlock(&locks[index]); // Unlocking after modifying
}

void updateItem(long identifier, int value) {
    unsigned long index = hash(identifier);

    pthread_mutex_lock(&locks[index]); 
    Node* node;
    for (node = hashTable[index]; node != NULL; node = node->next) {
        if (node->item != NULL && node->item->identifier == identifier) {
            node->item->value = value; 
            break;
        }
    }

    pthread_mutex_unlock(&locks[index]); // Unlocking after modifying
}

Item* getItem(long identifier){
    unsigned long index = hash(identifier);

    pthread_mutex_lock(&locks[index]); 
    Node* node;
    for (node = hashTable[index]; node != NULL; node = node->next) {
        if (node->item != NULL && node->item->identifier == identifier) {
            pthread_mutex_unlock(&locks[index]); 
            return node->item;
        }
    }

    pthread_mutex_unlock(&locks[index]); 
    printf("No Item Found\n");
    return NULL;
}

void* cleanup(void* param) {
    while (1) {
        sleep(cleanupFrequency); // Sleep for the frequency duration before starting cleanup

        pthread_mutex_lock(&locks[0]); 
        /* Clean up code goes here. You may need to implement this depending on your specific use case */
        pthread_mutex_unlock(&locks[0]);
    }
}
```
