['The task is quite complex and requires a good understanding of C language and its features such as dynamic memory allocation and threads safety. Here is an implementation that uses linked lists to manage the `NFAPI_CRC_INDICATION_PDU_T` entries. The list resizes dynamically when more space is needed, ensuring optimal cache performance by avoiding frequent reallocations. 

```c
#include <stdlib.h>
#include <pthread.h>
#define MAX_ENTRIES 1024

typedef struct RX_UE_INFORMATION_TAG {
    uint16_t ue_id;
} RX_UE_INFORMATION_TAG;

typedef struct CRC_INDICATION_REL8_TAG {
    uint16_t crcFlag;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rxUeInfoTag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode* next;
} ListNode;

typedef struct List {
    pthread_mutex_t mutex;
    int size;
    ListNode *head, *tail;
} List;

void initList(List* list) {
    list->size = 0;
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

void addToList(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);

    ListNode *node = (ListNode*)malloc(sizeof(ListNode));
    node->data = data;
    node->next = NULL;

    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        list->tail = node;
    }
    ++(list->size);

    pthread_mutex_unlock(&list->mutex);
}

void clearList(List* list) {
    pthread_mutex_lock(&list->mutex);

    ListNode *node = list->head;
    while (node != NULL) {
        ListNode *next = node->next;
        free(node);
        node = next;
    }

    list->size = 0;
    list->head = NULL;
    list->tail = NULL;

    pthread_mutex_unlock(&list->mutex);
}
```
This code uses a linked list data structure to manage the entries, and provides functions to initialize and clear it. The `addToList` function is thread safe as it locks a mutex before modifying the list. It allocates memory for each new entry dynamically which ensures efficient use of memory but may lead to fragmentation if many small allocations are made.
']

