#include <stdlib.h>
#include <pthread.h>

typedef struct UEContext {
    int RNTI;
    // Other configuration parameters here...
} UEContext;

typedef struct UEContextList {
    pthread_mutex_t lock;
    UEContext *contexts;
    size_t count;
    size_t activeCount;
} UEContextList;

UEContextList* createUEContextList(size_t initialSize) {
    UEContextList *list = malloc(sizeof(*list));
    pthread_mutex_init(&list->lock, NULL);
    list->contexts = calloc(initialSize, sizeof(*(list->contexts)));
    list->count = 0;
    list->activeCount = 0;
    return list;
}

void addContext(UEContextList *list, UEContext context) {
    pthread_mutex_lock(&list->lock);

    if (list->count == list->activeCount) {
        size_t newSize = list->count ? 2 * list->count : 1;
        list->contexts = realloc(list->contexts, newSize * sizeof(*list->contexts));
    }

    list->contexts[list->activeCount] = context;
    list->activeCount++;

    pthread_mutex_unlock(&list->lock);
}

void iterateContextList(UEContextList *list, void (*fn)(UEContext*, void*), void *data) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->activeCount; ++i) {
        fn(&list->contexts[i], data);
    }

    pthread_mutex_unlock(&list->lock);
}
```

