NFAPI_L1_API_PDU_T* initializeFrames(size_t max_frames, size_t max_buffer) {
    srand(time(0));  // Random seed
    NFAPI_L1_API_PDU_T* frames = NULL;
    size_t total_allocated = 0;
    for (size_t i = 0; i < max_frames; ++i) {
        size_t buffer_size = rand() % max_buffer + 1;  // Random buffer size within limit
        if (total_allocated + sizeof(NFAPI_L1_API_PDU_T) + buffer_size > max_buffer * 0.5) {
            break;  // If adding this frame would exceed the 50% limit, stop allocating frames
        }

        frames = realloc(frames, (i + 1) * sizeof(NFAPI_L1_API_PDU_T));
        if (frames == NULL) {
            break;  // If allocation failed, stop adding more frames
        }

        // Initialize the new frame
        frames[i].frame.sequence_number = i + 1;
        frames[i].buffer.data = malloc(buffer_size);
        if (frames[i].buffer.data == NULL) {
            break;  // If buffer allocation failed, stop adding more frames
        }

        // Populate with random data
        for (size_t j = 0; j < buffer_size; ++j) {
            frames[i].buffer.data[j] = rand() % 256;
        }
        frames[i].buffer.size = buffer_size;

        total_allocated += sizeof(NFAPI_L1_API_PDU_T) + buffer_size;
    }

    return frames;
}
