['Below is a sample implementation for your task. This solution uses `pthreads` to handle thread-safe allocation and deallocation of memory. Please note that this code does not include error checking for simplicity. In production environment, you must ensure to check for errors after every operation which can fail.

```c
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int value;
} Record;

typedef struct DataSet {
    long* offsets;
    int* keys;
    Record** records;
} DataSet;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

DataSet* allocateDataSet(size_t n, int minValue, int maxValue) {
    // Lock the mutex to ensure thread-safety
    pthread_mutex_lock(&mutex);

    DataSet *data = malloc(sizeof(DataSet));
    if (!data) goto error;

    data->offsets = calloc(n, sizeof(long));
    if (!data->offsets) goto error;

    data->keys = calloc(n, sizeof(int));
    if (!data->keys) goto error;

    data->records = malloc(sizeof(Record*) * n);
    if (!data->records) goto error;

    for (size_t i = 0; i < n; ++i) {
        data->keys[i] = minValue + rand() % (maxValue - minValue + 1); // Initialize keys with a random value in the specified range

        data->records[i] = malloc(sizeof(Record));
        if (!data->records[i]) goto error;

        data->records[i]->value = 0; // Initialize record values with zero
    }

    pthread_mutex_unlock(&mutex); // Unlock the mutex before returning
    return data;

error: // Clean up and handle errors
    if (data) {
        free(data->offsets);
        free(data->keys);

        if (data->records) {
            for (size_t i = 0; i < n; ++i) {
                free(data->records[i]);
            }

            free(data->records);
        }
    }

    pthread_mutex_unlock(&mutex); // Unlock the mutex before exiting
    return NULL;
}

void deallocateDataSet(DataSet* data) {
    if (data) {
        free(data->offsets);
        free(data->keys);

        for (size_t i = 0; i < n; ++i) {
            free(data->records[i]);
        }

        free(data->records);
    }
}
``` 

