static long* offsets = NULL;
static int* keys = NULL;
static Record** records = NULL;
static size_t numRecords = 0;

void initMemory(size_t range, size_t count) {
    assert(range > 0 && count > 0);

    pthread_mutex_lock(&mutex);
    if (offsets == NULL) {
        offsets = malloc(range * sizeof(*offsets));
        for (size_t i = 0; i < range; ++i) 
            offsets[i] = rand() % INT32_MAX;
    }

    if (keys == NULL) {
        keys = malloc(range * sizeof(*keys));
        for (size_t i = 0; i < range; ++i)
            keys[i] = rand();
    }

    if (records == NULL) {
        records = malloc(count * sizeof(*records));
        for (size_t i = 0; i < count; ++i) {
            Record* record = malloc(sizeof(*record));
            record->value = rand() % INT32_MAX;
            records[i] = record;
            ++numRecords;
        }
    } else {
        for (size_t i = 0; i < count && i < numRecords; ++i) 
            records[i]->value = rand() % INT32_MAX;
    }

    pthread_mutex_unlock(&mutex);
}

void destroyMemory() {
    pthread_mutex_lock(&mutex);

    free(offsets);
    offsets = NULL;

    free(keys);
    keys = NULL;

    for (size_t i = 0; i < numRecords; ++i) {
        free(records[i]);
        records[i] = NULL;
    }
    free(records);
    records = NULL;

    pthread_mutex_unlock(&mutex);
}
