    *head_ref    = new_node;
}

void* deleteList(Node** head_ref){
   Node* current = *head_ref;
   Node* next;

   while (current != NULL){
       next = current->next;
       free(current);
       current = next;
    }

   *head_ref = NULL;
}

void* manageList(){
