['Here is a basic outline of how you could implement this in C with POSIX threads (pthreads):

```c
#include <stdio.h>
#include <unistd.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pthread.h>
#include <errno.h>
#include <string.h>

typedef struct {
    int value;
} record;

// read-write lock for file operations
pthread_rwlock_t rwlock = PTHREAD_RWLOCK_INITIALIZER;
FILE *output_file;
int range = 1000; // default range

void* process_directory(void *arg) {
    DIR *dir = opendir((char*) arg);
    if (!dir) {
        printf("Failed to open directory: %s\n", strerror(errno));
        return NULL;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        pthread_rwlock_rdlock(&rwlock); // acquire read lock

        if (entry->d_type == DT_REG) { // only process regular files
            char filepath[256];
            sprintf(filepath, "%s/%s", (char*) arg, entry->d_name);

            int fd = open(filepath, O_RDONLY);
            if (fd == -1) {
                printf("Failed to open file %s: %s\n", entry->d_name, strerror(errno));
                continue;
            }

            struct stat sb;
            if (fstat(fd, &sb) == -1) {
                printf("Failed to get metadata for file %s: %s\n", entry->d_name, strerror(errno));
                close(fd);
                continue;
            }

            // Compute a unique identifier based on file metadata and range
            unsigned long id = (unsigned long) sb.st_ino * range + rand() % range;

            pthread_rwlock_unlock(&rwlock); // release read lock

            pthread_rwlock_wrlock(&rwlock); // acquire write lock

            // Rename file with appended unique identifier
            char newpath[256];
            sprintf(newpath, "%s/%lu", (char*) arg, id);
            if (rename(filepath, newpath) == -1) {
                printf("Failed to rename file %s: %s\n", entry->d_name, strerror(errno));
            } else {
                fprintf(output_file, "Renamed file %s to %lu\n", entry->d_name, id);
            }

            pthread_rwlock_unlock(&rwlock); // release write lock
        }
    }

    closedir(dir);
    return NULL;
}

int main(int argc, char **argv) {
    if (argc < 2 || strcmp(argv[1], "--help") == 0) {
        printf("Usage: %s [-c range] [-o output_file] directory\n", argv[0]);
        return 1;
    }

    // Parse command line arguments
    for (int i = 1; i < argc - 1; ++i) {
        if (strcmp(argv[i], "-c") == 0 && i + 1 < argc) {
            range = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            output_file = fopen(argv[++i], "w");
            if (!output_file) {
                printf("Failed to open output file: %s\n", strerror(errno));
                return 1;
            }
        }
    }

    pthread_t thread;
    if (pthread_create(&thread, NULL, process_directory, argv[argc - 1]) != 0) {
        printf("Failed to create thread: %s\n", strerror(errno));
        return 1;
    }

    pthread_join(thread, NULL); // wait for thread to finish

    if (output_file) fclose(output_file);

    return 0;
}
```
This code provides a basic framework for processing files in a directory concurrently and safely renaming them with a unique identifier. However, it doesn't include handling for cases where the same file name is chosen twice (which could occur if two threads are creating files at the exact same time), or optimizing performance under heavy load. Improving these aspects would require more complex code and a deeper understanding of your specific use case.
