typedef struct DynamicArray {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T* array;
    int capacity;
    int size;
} DynamicArray;

DynamicArray* createDynamicArray(int initialCapacity) {
    DynamicArray* da = malloc(sizeof(DynamicArray));
    if (da == NULL) return NULL;

    da->array = calloc(initialCapacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (da->array == NULL) {
        free(da);
        return NULL;
    }

    pthread_mutex_init(&(da->lock), NULL);
    da->capacity = initialCapacity;
    da->size = 0;

    return da;
}

void resizeArrayIfNeeded(DynamicArray* da) {
    if (da->size == da->capacity) {
        pthread_mutex_lock(&(da->lock));

        // Check again to prevent race conditions
        if (da->size == da->capacity) {
            int newCapacity = da->capacity * 2;
            NFAPI_CRC_INDICATION_PDU_T* newArray = 
                realloc(da->array, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

            if (newArray != NULL) {
                da->capacity = newCapacity;
                da->array = newArray;
            }
        }

        pthread_mutex_unlock(&(da->lock));
    }
}

void addElement(DynamicArray* da, NFAPI_CRC_INDICATION_PDU_T element) {
    resizeArrayIfNeeded(da);

    pthread_mutex_lock(&(da->lock));
    da->array[da->size++] = element;
    pthread_mutex_unlock(&(da->lock));
}
