DynamicArray* initArray(size_t initialSize) {
    srand(time(0)); 
    DynamicArray *a = malloc(sizeof *a);

    if (a == NULL) {
        return NULL;
    }

    a->array = malloc(initialSize * sizeof *(a->array));
    a->used = 0;
    a->size = initialSize;
    pthread_mutex_init(&a->mutex, NULL);

    return a;
}

void insertArray(DynamicArray *a, NFAPI_CRC_INDICATION_PDU_T element) {
    if (a->used == a->size) {
        a->size *= 2;
        a->array = realloc(a->array, a->size * sizeof *(a->array));
    }

    pthread_mutex_lock(&a->mutex);

    NFAPI_CRC_INDICATION_PDU_T* newElement = malloc(sizeof(*newElement));
    newElement->RX_UE_INFORMATION_TAG = element.RX_UE_INFORMATION_TAG;
    newElement->RNTI = element.RNTI;
    newElement->CRC_INDICATION_REL8_TAG = element.CRC_INDICATION_REL8_TAG;
    newElement->CRCFLAG = rand() % 2; // Set CRCFLAG randomly

    a->array[a->used++] = newElement;

    pthread_mutex_unlock(&a->mutex);
}

void freeArray(DynamicArray *a) {
    for (size_t i = 0; i < a->used; i++) {
