```php
<?php
use GuzzleHttp\Client;
use Predis\Client as Redis;

class OauthUser {
    private $providerUrl;
    private $redis;

    function __construct($url) {
        $this->providerUrl = $url;
        $this->redis = new Redis();
    }

    public function authenticate($credentials) {
        $httpClient = new Client(['base_uri' => $this->providerUrl]);
        try {
            $response = $httpClient->request('POST', '/token', [
                'form_params' => [
                    'client_id'     => $credentials['client_id'],
                    'client_secret' => $credentials['client_secret'],
                    'grant_type'    => $credentials['grant_type']
                ]
            ]);
            $data = json_decode($response->getBody(), true);
            if (isset($data['access_token']) && isset($data['expires_in'])) {
                $this->redis->set('access_token', $data['access_token']);
                $this->redis->expire('access_token', $data['expires_in']);
                return true;
            } else {
                error_log("Failed to retrieve access token");
                return false;
            }
        } catch (Exception $e) {
            error_log($e->getMessage());
            return false;
        }
    }

    public function getUserInfo() {
        $accessToken = $this->redis->get('access_token');
        if (!$accessToken) {
            $accessToken = authenticate(); // retry mechanism can be added here
            if(!$accessToken){
                return false;
            }
        }

        try{
            $response = $httpClient->request('GET', '/userinfo', [
                'headers' => ['Authorization' => "Bearer $accessToken"]
            ]);
            $data = json_decode($response->getBody(), true);

            $this->redis->set('userInfo', serialize($data)); // caching user data for 1 hour as an example
            $this->redis->expire('userInfo', 3600);
        } catch (Exception $e) {
            error_log($e->getMessage());
            return false;
        }
    }
}
```
Please note, this is a simplified example and does not cover all the points mentioned in your request. It might need to be adjusted based on the exact requirements of your application, including specifics about how tokens are refreshed and rate limits are handled by the OAuth provider. Additionally, implementing retry logic for network failures, logging, service dependencies etc. should be done according to your own requirements.
