void* allocateFrameBuffer(int size) {
    void *frameBuf = malloc(size);
    if (frameBuf == NULL) {
        // Handle allocation failure
        return NULL;
    }

    // Populate frame buffer with random test data 
    char *data = (char *)frameBuf;
    srand((unsigned int) time(NULL));
    for(int i = 0; i < size; i++) {
        data[i] = rand() % 256; // Generate a random byte
    }
    return frameBuf;
}

void handleCleanup() {
    if(difftime(endTime, startTime) > 300.0) { 
        pthread_mutex_lock(&lock);

        // Periodically clean up unused structures
        for (int i = 0; i < arraySize; i++) {
            if(array[i].size == 0 && array[i].rxFrame.frameBuffer != NULL) { 
                free(array[i].rxFrame.frameBuffer); // Free frame buffer
                array[i].rxFrame.frameBuffer = NULL;
                arraySize--;
            }
        }
        pthread_mutex_unlock(&lock);
    }
}

void addStructToArray(int size) {
    pthread_mutex_lock(&lock);

    // Allocate memory for new structure
    array = realloc(array, sizeof(NFAPI_L1_API_PDU_T) * (arraySize + 1));
    if (array == NULL) {
        // Handle allocation failure
        pthread_mutex_unlock(&lock);
        return;
