typedef enum {
    ACTIVE, ERROR
} StatusType;

typedef struct NetworkInterfaceStatus{
   StatusType status;
   int errorCode;
} NetworkInterfaceStatus;

void logNetworkInfo(NetworkInterfaceStatus *interfaces, int numInterfaces){
  time_t t = time(NULL);
  struct tm *tm = localtime(&t);
  char date[20];
  strftime(date, sizeof(date), "%Y-%m-%d %H:%M:%S", tm);

  for(int i = 0; i < numInterfaces; ++i){
    fprintf(logFile,"%s | Interface %d : status = %s , errorCode = %d\n"
          , date, i+1, interfaces[i].status ? "ERROR" : "ACTIVE", interfaces[i].errorCode);
  }
}

void initInterfaces(NetworkInterfaceStatus **interfaces, int numInterfaces){
   *interfaces = malloc(numInterfaces * sizeof(NetworkInterfaceStatus));
    if(*interfaces == NULL){
       perror("Memory Allocation Error");
       exit(EXIT_FAILURE);
    }
}

void populateInterfaces(NetworkInterfaceStatus *interfaces, int numInterfaces, unsigned int seed){
   srand(seed ? seed : time(0)); // if seed is provided use it else use current time as seed
   for (int i = 0; i < numInterfaces; ++i) {
       interfaces[i].status = rand() % 2 ? ACTIVE : ERROR;
       if(interfaces[i].status == ERROR){
           interfaces[i].errorCode = rand()%MAX_ERROR_CODE + 1;
       }else{
           interfaces[i].errorCode = 0;
       }
   }
}

void generateNetworkInterfaces(NetworkInterfaceStatus **interfaces, int numInterfaces, unsigned int seed){
  logFile = fopen("logs.txt", "a"); // use append mode so we do not overwrite previous logs
  if (logFile == NULL) {
    perror ("Error opening file");
    exit(EXIT_FAILURE);
  }

  initInterfaces(interfaces, numInterfaces);
  populateInterfaces(*interfaces, numInterfaces, seed);

  logNetworkInfo(*interfaces, numInterfaces); // logging after population to get timestamps for each creation process

  fclose(logFile); // don't forget to close the file when you are done with it
}
