["This task involves implementing a complex data structure which can be achieved by writing several functions. Here is an example implementation of such a linked list with resizing, hash table indexing and thread-safe operations. Please note that this code does not handle all edge cases or potential memory fragmentation issues, as it's just a basic example to give you the idea on how it can be done. A full implementation would require more sophisticated error handling, concurrency control mechanisms, etc.

```C
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int value;
    void* metadata;  // replace with actual structure if needed
} Record;

typedef struct Node {
    Record record;
    struct Node *next, *prev;
} Node;

typedef struct LinkedList {
    Node *head, *tail;
    size_t size;
    pthread_mutex_t lock;  // for thread safety
} LinkedList;

#define HASH_TABLE_SIZE 1024  // example size
typedef struct HashTable {
    int keys[HASH_TABLE_SIZE];
    Node* pointers[HASH_TABLE_SIZE];
} HashTable;

LinkedList list = {NULL, NULL, 0, PTHREAD_MUTEX_INITIALIZER};
HashTable hashTable;

Node* newNode(Record record) {
    Node *node = malloc(sizeof(Node));
    node->record = record;
    node->next = NULL;
    return node;
}

void addToList(LinkedList *list, Record record) {
    pthread_mutex_lock(&list->lock);  // lock to avoid concurrent modifications
    Node* node = newNode(record);

    if (list->tail != NULL) list->tail->next = node;
    else list->head = node;

    list->tail = node;
    hashTable.keys[node->record.value % HASH_TABLE_SIZE] = 1;  // update hash table
    hashTable.pointers[node->record.value % HASH_TABLE_SIZE] = node;
    list->size++;

    pthread_mutex_unlock(&list->lock);  // unlock after modifications are done
}

Node* getFromList(LinkedList *list, int value) {
    return hashTable.pointers[value % HASH_TABLE_SIZE];
}

void removeFromList(LinkedList *list, Node *nodeToRemove) {
    pthread_mutex_lock(&list->lock);  // lock to avoid concurrent modifications

    if (nodeToRemove == list->head) {  // node is the head of the list
        list->head = nodeToRemove->next;
    } else {  // node is in the middle or at the end, update previous node's next pointer
        Node* currentNode = list->head;
        while (currentNode != NULL) {
            if (currentNode->next == nodeToRemove) {
                currentNode->next = nodeToRemove->next;
                break;
            }
            currentNode = currentNode->next;
        }
    }

    free(nodeToRemove);  // deallocate memory
    list->size--;
    hashTable.keys[nodeToRemove->record.value % HASH_TABLE_SIZE] = 0;  // update hash table

    pthread_mutex_unlock(&list->lock);  // unlock after modifications are done
}
```

This code snippet creates a thread-safe linked list with a hash table for quick access of records. It also provides functions to add, get and remove nodes from the list. The resize strategy is not implemented here due to its complexity and can significantly impact on the system's latency and throughput. Therefore it depends on the specific requirements of your use case.
