    enum LogSeverity severity;
    time_t timestamp;
    char* log_message;
};

typedef struct {
    size_t count;
    size_t capacity;
    struct LogEntry** entries;
} LogList;

LogList* create_loglist(void) {
    LogList* list = malloc(sizeof(*list));
    if (!list) return NULL;

    list->count = 0;
    list->capacity = 16;
    list->entries = malloc(sizeof(struct LogEntry*) * list->capacity);
    if (!list->entries) {
        free(list);
        return NULL;
    }

    return list;
}

void add_logentry(LogList* list, struct LogEntry* entry) {
    // Check UserSessionID is unique
    for (size_t i = 0; i < list->count; ++i) {
        if (list->entries[i]->user_session_id == entry->user_session_id) return;
    }

    // Resize if necessary
    if (list->count == list->capacity) {
        list->capacity *= 2;
        list->entries = realloc(list->entries, sizeof(struct LogEntry*) * list->capacity);
    }

    // Add entry
    list->entries[list->count++] = entry;
}
