#include <stdlib.h>
#include <pthread.h>
#include <limits.h>

typedef struct StackNode {
    int value;
    struct StackNode* next;
} StackNode_t;

StackNode_t *top = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void push(int value) {
    pthread_mutex_lock(&lock);
    StackNode_t* node = (StackNode_t*) malloc(sizeof(StackNode_t));
    node->value = value;
    node->next = top;
    top = node;
    pthread_mutex_unlock(&lock);
}

int pop() {
    pthread_mutex_lock(&lock);
    if(top == NULL) return INT_MIN;  // or some other error code, indicating stack is empty
    StackNode_t* node = top;
    int result = node->value;
    top = node->next;
    free(node);
    pthread_mutex_unlock(&lock);
    return result;
}

int peek() {
    pthread_mutex_lock(&lock);
    if(top == NULL) return INT_MIN;  // or some other error code, indicating stack is empty
    int result = top->value;
    pthread_mutex_unlock(&lock);
    return result;
}
```
This function reads integers from standard input and manipulates a stack with these values. It uses mutex locking to ensure thread safety, so that multiple threads can safely push and pop values simultaneously without interfering with each other's operations. It also frees all dynamically allocated memory when it's done, preventing leaks. 

