["```c
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct {
    long timestamp;
    int eventType;
    char* metadata;  // Can be replaced with appropriate type and size based on expected usage
} Event;

typedef struct {
    _Atomic(size_t) count;
    _Atomic(size_t) capacity;
    pthread_mutex_t lock;
    Event* events;
} EventArray;

EventArray* createEventArray() {
    EventArray* arr = malloc(sizeof(EventArray));
    if (!arr) return NULL;

    atomic_init(&arr->count, 0);
    atomic_init(&arr->capacity, 16);
    pthread_mutex_init(&arr->lock, NULL);
    arr->events = malloc(sizeof(Event) * arr->capacity);

    return arr;
}

void resizeEventArray(EventArray* arr, size_t newCapacity) {
    pthread_mutex_lock(&arr->lock);
    arr->events = realloc(arr->events, sizeof(Event) * newCapacity);
    atomic_store(&arr->capacity, newCapacity);
    pthread_mutex_unlock(&arr->lock);
}

void addEvent(EventArray* arr, Event event) {
    size_t index = atomic_fetch_add(&arr->count, 1);

    if (index >= atomic_load(&arr->capacity)) {
        resizeEventArray(arr, atomic_load(&arr->capacity) * 2); // Doubling for amortized linear time complexity
    }

    pthread_mutex_lock(&arr->lock);
    arr->events[index] = event;
    pthread_mutex_unlock(&arr->lock);
}

Event* getEventsByRange(EventArray* arr, long startTime, long endTime) {
    Event* result = malloc(sizeof(Event) * atomic_load(&arr->count));
    size_t count = 0;

    for (size_t i = 0; i < atomic_load(&arr->count); ++i) {
        if (arr->events[i].timestamp >= startTime && arr->events[i].timestamp <= endTime) {
            result[count++] = arr->events[i];
        }
    }

    return result;  // Remember to free this memory after use
}

void clearEventArray(EventArray* arr) {
    pthread_mutex_lock(&arr->lock);
    atomic_store(&arr->count, 0);
    resizeEventArray(arr, 16);
    pthread_mutex_unlock(&arr->lock);
}
```
For concurrent access from multiple threads, this uses a pthread mutex to protect the critical sections where shared data is accessed or modified. The `atomic` functions are used to ensure atomic operations on the shared count and capacity variables.

This implementation preallocates an array of a fixed size, but when the array becomes full, it doubles its size with each new addition, ensuring amortized linear time complexity for n additions. This avoids frequent resizing operations which can be costly in terms of performance.

For asynchronous logging of events, you would typically use an asynchronous logging library that supports sending log messages to a remote server or service without blocking the main thread. You'd then call this from within your `addEvent` function so that it happens asynchronously after the event is added, but before the mutex is unlocked.

