using System;
using UnityEngine;

public class RandomValueGenerator {
    private float minFloat;
    private float maxFloat;

    public RandomValueGenerator(float min, float max) {
        if (min >= max) 
            throw new ArgumentException("Minimum value must be less than maximum.");

        this.minFloat = min;
        this.maxFloat = max;
    }

    public float GetRandomFloat() {
        return UnityEngine.Random.Range(this.minFloat, this.maxFloat);
    }

    public int GetRandomInt() {
        if (this.maxFloat > int.MaxValue || this.minFloat < int.MinValue)
            throw new InvalidOperationException("The range is too large to generate a random integer.");

        return UnityEngine.Random.Range(Mathf.CeilToInt(this.minFloat), Mathf.FloorToInt(this.maxFloat));
    }

    public override string ToString() {
        return $"Min: {minFloat}, Max: {maxFloat}";
    }
}
