        array->capacity = newCapacity;
        array->events = newEvents;
    } else {
        // Handle error.
    }
}

void addEvent(Array* array, Event* event) {
    if (array->size >= array->capacity) {
        resizeArray(array, array->capacity * 2);
    }
    array->events[array->size] = event;
    array->size++;
}

