```c
#include <pthread.h>
#include <stdlib.h>
#define MAX_SIZE 1024 // Define your maximum size M here

// Your data structure 
typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct List {
    pthread_mutex_t mutex;
    size_t count;
    NFAPI_CRC_INDICATION_PDU_T *data;
} List;

List* create_list() {
    List* list = malloc(sizeof(List));
    pthread_mutex_init(&list->mutex, NULL);
    list->count = 0;
    list->data = malloc(MAX_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    return list;
}

void add_to_list(List* list, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&list->mutex);
    if (list->count < MAX_SIZE) {
        list->data[list->count++] = item; // Add the item to the list
    } else {
        for(size_t i = 0; i < list->count - 1; ++i) { // Discard the least recently added items
            list->data[i] = list->data[i + 1];
        }
        list->data[MAX_SIZE - 1] = item; // Add new item to maintain integrity of list
    }
    pthread_mutex_unlock(&list->mutex);
}

void destroy_list(List* list) {
    pthread_mutex_destroy(&list->mutex);
    free(list->data);
    free(list);
}
```

The above code provides a simple implementation of the list with thread safety. It ensures that only one thread can add an item to the list at a time, thus avoiding any race conditions. 

