    sanitizeFilename(oldFilename); // Sanitize filename to prevent runtime errors

    char newFilename[256];
    snprintf(newFilename, sizeof(newFilename), "%s%d%s", oldFilename, sequentialNumber, fileType);

    if (rename(oldFilename, newFilename) != 0) { // Attempt to rename file
        perror("Failed to rename file");
    } else {
        printf("Renamed '%s' to '%s'\n", oldFilename, newFilename);
    }

