```C
#include <pthread.h>
#include <stdlib.h>
#include <assert.h>

// This is just a placeholder for actual NR_UE_CONTEXT structure
typedef struct {
    int pci;
} NR_UE_CONTEXT;

typedef struct {
    pthread_mutex_t lock;
    size_t count;
    size_t capacity;
    NR_UE_CONTEXT* contexts;
} ContextArray;

ContextArray* createContextArray(size_t initialCapacity) {
    ContextArray* array = (ContextArray*) malloc(sizeof(ContextArray));
    if (!array) return NULL;

    pthread_mutex_init(&array->lock, NULL);
    array->count = 0;
    array->capacity = initialCapacity;
    array->contexts = (NR_UE_CONTEXT*) malloc(sizeof(NR_UE_CONTEXT) * initialCapacity);

    return array;
}

int isUniquePci(ContextArray* array, int pci) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->contexts[i].pci == pci) return 0;
    }

    return 1;
}

int addContext(ContextArray* array, NR_UE_CONTEXT context) {
    pthread_mutex_lock(&array->lock);

    if (!isUniquePci(array, context.pci)) {
        pthread_mutex_unlock(&array->lock);
        return 0; // PCI is not unique, adding failed
    }

    if (array->count == array->capacity) {
        size_t newCapacity = array->capacity * 2;
        NR_UE_CONTEXT* newContexts = realloc(array->contexts, sizeof(NR_UE_CONTEXT) * newCapacity);

        if (!newContexts) {
            pthread_mutex_unlock(&array->lock);
            return 0; // Reallocation failed, adding failed
        }

        array->capacity = newCapacity;
        array->contexts = newContexts;
    }

    array->contexts[array->count++] = context;

    pthread_mutex_unlock(&array->lock);

    return 1; // Adding succeeded
}
```

