["Below is an example implementation of your task using Node.js's built-in file system, stream, and promises modules. Please note that this is a simplified version for demonstration purposes and does not contain all edge cases and error handling strategies you might need in a production environment.

```javascript
const fs = require('fs');
const path = require('path');
const readline = require('readline');
const stream = require('stream');
const {promisify} = require('util');

// Wraps readdir and readFile with promises for easier usage.
const readDirAsync = promisify(fs.readdir);
const readFileAsync = promisify(fs.readFile);
const writeFileAsync = promisify(fs.writeFile);

async function processFilesInDirectory({directoryPath, sourceSubstring, targetSubstring, errorLogFile}) {
    const files = await readDirAsync(directoryPath);
    let promises = [];

    for (let file of files) {
        // Add a promise to the array.
        promises.push(processSingleFile({fileName: path.join(directoryPath, file), sourceSubstring, targetSubstring}));

        if (promises.length >= 50) {
            await Promise.all(promises);
            promises = []; // Reset the array for next batch of files.
        }
    }

    // Wait for remaining files to finish processing.
    await Promise.all(promises);
}

async function processSingleFile({fileName, sourceSubstring, targetSubstring}) {
    try {
      let data = await readFileAsync(fileName, 'utf8');

      // Replace all occurrences of the substring.
      let newData = data.replace(new RegExp(sourceSubstring, 'g'), targetSubstring);

      if (data !== newData) {
        await writeFileAsync(fileName, newData);
      }
    } catch (error) {
      // Log the error and re-throw it.
      let logStream = fs.createWriteStream(errorLogFile, {flags: 'a'});
      logStream.write(`Error processing file ${fileName}:\n${error.stack}\n\n`);

      throw error;
    }
}
```
To run the function with command-line arguments use Node's process.argv:

```javascript
