['Here is a simplified version of how you might implement this using modern JavaScript features such as Promises for asynchronous loading and error handling:

```js
class Module {
  constructor(name, deps) {
    this.name = name;
    this.deps = deps;
    this.loaded = false;
    this.failed = false;
    this.executed = false;
    this.module = null;
  }
}

class ModuleLoader {
  constructor() {
    this.modules = {};
  }

  addModule(name, deps) {
    if (this.modules[name]) {
      throw new Error(`A module with the name ${name} already exists`);
    }
    const module = new Module(name, deps);
    this.modules[name] = module;
  }

  loadModule(name) {
    if (!this.modules[name]) {
      throw new Error(`No module with the name ${name} exists`);
    }

    const module = this.modules[name];

    if (module.loaded || module.executed) return Promise.resolve(module.module);
    if (module.failed) {
      return Promise.reject(new Error(`Failed to load ${name}`));
    }

    console.log(`Loading ${name}...`);

    const depsPromises = module.deps.map((depName) => this.loadModule(depName));

    return Promise.all(depsPromises).then(() => {
      return import(/* webpackChunkName: "[request]" */ `./modules/${name}.js`)
        .then((module) => {
          console.log(`Successfully loaded ${name}`);
          module.loaded = true;
          return module;
        })
        .catch((error) => {
          console.log(`Failed to load ${name} with error: ${error}`);
          module.failed = true;
          throw new Error(`Failed to load ${name}: ${error}`);
        });
    });
  }

  executeModule(name) {
    return this.loadModule(name).then((module) => {
      if (!module.executed) {
        module();
        module.executed = true;
      } else {
        console.log(`${name} has already been executed`);
      }
    });
  }
}
```

This code assumes that all modules are located in a `./modules/` directory and that they export a function, which it then executes. It also uses the dynamic import syntax supported by modern browsers (with webpack's require.ensure) to load each module only when needed.

