['Here's a basic implementation of `generateSortedSequenceAndPduList` using Python:

```python
import time
import threading
import random
from typing import List

class PDU(object):
    def __init__(self, ue_info_tag: str, rnti: int, crc_ind: bool) -> None:
        self.ue_info_tag = ue_info_tag
        self.rnti = rnti
        self.crc_ind = crc_ind

class ConfigReader(object):
    def __init__(self, filePath: str) -> None:
        self._filePath = filePath

    def readConfigAndSort(self) -> List[str]:
        try:
            with open(self._filePath, 'r') as f:
                lines = f.readlines()
                lines.sort()
                return lines
        except IOError:
            print("Cannot read file")
            return []

class PDUGenerator(object):
    def __init__(self, dataSource: object, timeout: int) -> None:
        self._dataSource = dataSource
        self._timeout = timeout
        self._pduList = []
        self._nextCreationTime = 0

    def _createPDUStructure(self, ue_info_tag: str, rnti: int) -> PDU:
        crc_ind = bool(random.getrandbits(1)) # set CRC indication randomly
        pdu = PDU(ue_info_tag, rnti, crc_ind)
        return pdu

    def _waitForCreationTime(self):
        currentTime = time.time()
        if currentTime < self._nextCreationTime:
            time.sleep(self._nextCreationTime - currentTime)

    def _updateNextCreationTime(self):
        self._nextCreationTime = time.time() + 10 # set cooldown period as 10 seconds

    def _getRNTIListFromDataSource(self, timeout: int) -> List[int]:
        try:
            return self._dataSource.getRNTIList(timeout)
        except Exception:
            print("Failed to get RNTI list from data source")
            return [1234567890, 2345678901] # default RNTI values

    def generatePDUStructures(self, n: int) -> List[PDU]:
        lock = threading.Lock()
        threads = []

        for _ in range(n):
            ue_info_tag = "UE_" + str(_ + 1) # set UE information tag sequentially

            with lock:
                self._waitForCreationTime()
                rntiList = self._getRNTIListFromDataSource(self._timeout)

            thread = threading.Thread(target=self._generatePDUStructure, args=(ue_info_tag, rntiList, lock))
            threads.append(thread)
            thread.start()

        for t in threads:
            t.join()

        self._updateNextCreationTime()
        return self._pduList[:n] # return pointers to the first N elements of list

    def _generatePDUStructure(self, ue_info_tag: str, rntiList: List[int], lock: threading.Lock) -> None:
        with lock:
            for rnti in rntiList:
                pdu = self._createPDUStructure(ue_info_tag, rnti)
                self._pduList.append(pdu)
```
Please note that the code above is a simple simulation and does not include many of the features mentioned in the problem statement such as reading configuration files, error handling, thread safety, etc. Also, please replace `self._dataSource.getRNTIList` with actual implementation if it's available. This skeleton provides only basic structure of how solution could be implemented and may require adjustments according to specific project requirements.
']

