#include <stdlib.h>
#include <pthread.h>
#define THRESHOLD 10000

typedef struct State {
    int stateNum;
    struct State* nextState;
} State;

int totalStatesProcessed = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* checkResourceLimits(void* vargp) {
    while (1) {
        sleep(5); // Check every 5 seconds
        if (totalStatesProcessed > THRESHOLD) {
            pthread_exit(NULL);
        }
    }
}

State* createLinkedListFSA(State* fsa, int numStates, int lastState) {
    State* current = NULL;
    State* head = NULL;

    for (int i = 0; i < numStates && totalStatesProcessed <= THRESHOLD; ++i) {
        pthread_mutex_lock(&lock);
        ++totalStatesProcessed;
        pthread_mutex_unlock(&lock);

        State* newState = (State*)malloc(sizeof(State)); // Allocate memory
        if (newState == NULL) {
            exit(-1); // Gracefully degrade when out of memory
        }

        newState->stateNum = fsa[i].stateNum; // Copy the state number

        if (current != NULL) {
            current->nextState = newState; 
            current = newState; 
        } else {
            current = head = newState; 
        }
    }

    return head;
}
```
This code implements a function that creates a linked list from an array representing the FSA. It also has functionality to periodically check if resources are being exhausted and terminates early if the threshold is exceeded. The function ensures thread safety by using a mutex, which allows only one thread to execute the critical section at a time. Memory is allocated for each state in the linked list and then freed once it's no longer needed.
