    int len = strlen(str);
    if (len > limit) {
        return NULL;
    }

    // allocate memory for new string with one extra byte for the slash and null terminator.
    char* resultStr = malloc((len + 2) * sizeof(char));
    if (resultStr == NULL) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    strcpy(resultStr, str); // copy the original string.
    resultStr[len] = '/';  // append slash.
    resultStr[len + 1] = '\0';  // add null terminator.

    return resultStr;
}
