['Here is a basic code outline in C that meets most of the requirements described above, but doesn't cover all details due to complexity. It uses libtiff library which can handle TIFF image files. The function parses through the tags in the file and extracts necessary information. It checks if bits per sample are supported (1, 2, 4, 8, or 16) and returns an error code otherwise.

```c
#include <stdlib.h>
#include <tiffio.h>

#define SUPPORTED_BPS {1, 2, 4, 8, 16}

enum BPSErrorCodes {
    BPS_NOT_SUPPORTED = 0xF0FF,
};

typedef struct {
    uint16 bitsPerSample;
    uint16 samplePerPixel;
    char* compressionMethod;
} TIFFInfo;

TIFFInfo parseTiff(const char *filename) {
    TIFF* tif = TIFFOpen(filename, "r");
    if (tif == NULL) {
        fprintf(stderr, "Failed to open TIFF file %s\n", filename);
        exit(1);
    }

    uint32 width, height;
    uint16 samplesPerPixel;
    uint16* bps = malloc(sizeof(uint16)); // Allocate memory for BPS array
    uint16* spp = malloc(sizeof(uint16)); // Allocate memory for SPP array
    TIFFGetField(tif, TIFFTAG_IMAGEWIDTH, &width);
    TIFFGetField(tif, TIFFTAG_IMAGELENGTH, &height);
    TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, spp);
    TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, bps);

    // Check if bits per sample is supported and throw error otherwise
    for (int i = 0; i < sizeof(SUPPORTED_BPS)/sizeof(uint16); i++) {
        if (*bps != SUPPORTED_BPS[i]) {
            fprintf(stderr, "Unsupported bits per sample: %u\n", *bps);
            TIFFClose(tif);
            free(bps); // Free the allocated memory
            exit(BPS_NOT_SUPPORTED);
        }
    }

    uint16 compression = COMPRESSION_NONE;
    TIFFGetField(tif, TIFFTAG_COMPRESSION, &compression);

    // Here you would normally get the compression method name using libtiff's TIFFGetField or a custom function.

    TIFFInfo info = {*bps, *spp, "Some Compression Method Name"};
    TIFFClose(tif);
    free(bps); // Free the allocated memory
    return info;
}
```
Note: This is a basic outline and may not cover all aspects of your requirements. It's a complex task to parse a TIFF file thoroughly in C, as it involves handling numerous tags and potential edge cases in different formats. Always consult with domain experts or refer to the official TIFF specification for accurate information.
']

