['```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class AESDecryptionService
{
    private const int MaxRetries = 5;
    private readonly byte[] key;
    private readonly ILoggingService loggingService;

    public AESDecryptionService(byte[] key, ILoggingService loggingService)
    {
        this.key = key;
        this.loggingService = loggingService;
    }

    public bool DecryptSegments(List<CiphertextSegment> segments)
    {
        var success = true;

        foreach (var segment in segments)
        {
            for (int i = 0; i < MaxRetries; i++)
            {
                try
                {
                    using (var aes = new AesCryptoServiceProvider())
                    {
                        aes.Key = key;
                        aes.IV = segment.IV;

                        var decryptor = aes.CreateDecryptor(aes.Key, aes.IV);

                        using (var memoryStream = new MemoryStream(segment.Ciphertext))
                        {
                            using (var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read))
                            {
                                var decryptedBytes = new byte[segment.Ciphertext.Length];
                                int decryptedByteCount = cryptoStream.Read(decryptedBytes, 0, decryptedBytes.Length);

                                using (var hmacsha256 = new HMACSHA256(key))
                                {
                                    var computedHash = hmacsha256.ComputeHash(decryptedBytes, 0, decryptedByteCount);

                                    if (!CompareHashes(computedHash, segment.HMAC))
                                    {
                                        throw new Exception("Data integrity check failed.");
                                    }
                                }

                                segment.Plaintext = Encoding.UTF8.GetString(decryptedBytes, 0, decryptedByteCount);
                            }
                        }
                    }

                    loggingService?.LogSuccessfulDecryption();
                    break;
                }
                catch (Exception ex)
                {
                    if (i == MaxRetries - 1)
                    {
                        success = false;
                        loggingService?.LogFailedDecryption(ex);
                        Console.WriteLine("Error decrypting segment: " + ex.Message);
                    }
                }
            }
        }

        return success;
    }

    private bool CompareHashes(byte[] hash1, byte[] hash2)
    {
        if (hash1.Length != hash2.Length) return false;

        for (int i = 0; i < hash1.Length; i++)
            if (hash1[i] != hash2[i]) return false;

        return true;
    }
}
```

