```javascript
class DOMTraverser {
    constructor(options = {}) {
        this.options = Object.assign({
            depthLimit: Infinity, // Traverse only to a certain depth.
            asyncMode: false, // Use async traversal.
            ignoreVisibility: true, // Ignore visibility states of elements.
            handlePartialLoad: true, // Handle partially loaded data sources.
        }, options);
    }

    traverse(selector) {
        return new Promise((resolve, reject) => {
            const results = [];

            function recurse(element, depth = 0) {
                if (depth >= this.options.depthLimit) return; // Stop condition for recursion.

                Array.from(element.children).forEach(child => {
                    if (this.options.ignoreVisibility || window.getComputedStyle(child).display !== 'none') {
                        if (child.matches(selector)) results.push(child); // Add to results if matches selector.
                        recurse.call(this, child, depth + 1); // Recursive call for children.
                    }
                });
            }

            try {
                recurse.call(this, document.documentElement);

                resolve(results);
            } catch (error) {
                reject(error);
            }
        });
    }
}
