["This is a complex task which involves multiple layers of programming. It involves understanding low-level socket programming, concurrent programming and managing resources effectively. A full implementation would take weeks to months, but here's an example of how you could start implementing this using POSIX threads (pthread) in C. 

Please note that this is a simplified version of what you're asking for, it doesn't include all the constraints and requirements mentioned such as handling failures and extending for future features. Further optimization may be needed to satisfy all given constraints.

```c
#include <pthread.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Connection {
    int sockfd;  // socket descriptor
    char ip[INET_ADDRSTRLEN];  // remote IP address
    uint16_t port;  // port number
    time_t lastActiveTime;  // last activity timestamp
} Connection;

typedef struct ConnPool {
    Connection **conns;  
    size_t len, cap;
    pthread_mutex_t lock;
} ConnPool;

// Initialize connection pool.
ConnPool *init_pool() {
    ConnPool *pool = malloc(sizeof(*pool));
    if (pool == NULL) return NULL;

    pool->conns = calloc(1, sizeof(Connection*));  // initial capacity is 1.
    if (pool->conns == NULL) {
        free(pool);
        return NULL;
    }

    pool->cap = 1;
    pool->len = 0;
    pthread_mutex_init(&pool->lock, NULL);  // initialize mutex.
    return pool;
}

// Add connection to the pool.
int add_conn(ConnPool *pool, int sockfd, char *ip, uint16_t port) {
    pthread_mutex_lock(&pool->lock);  // lock for thread safety.

    if (pool->len == pool->cap) {  // reallocate if full.
        size_t newCap = pool->cap * 2;
        Connection **newConns = realloc(pool->conns, newCap * sizeof(*newConns));

        if (newConns == NULL) {
            pthread_mutex_unlock(&pool->lock);
            return -1;  // allocation failed.
        }

        pool->cap = newCap;
        pool->conns = newConns;
    }

    Connection *conn = malloc(sizeof(*conn));  // create a connection record.
    if (conn == NULL) {
        pthread_mutex_unlock(&pool->lock);
        return -1;
    }

    conn->sockfd = sockfd;
    strncpy(conn->ip, ip, sizeof(conn->ip));
    conn->port = port;
    time(&conn->lastActiveTime);  // record the connection time.

    pool->conns[pool->len++] = conn;
    pthread_mutex_unlock(&pool->lock);
    return 0;
}

// Get a connection from its socket descriptor.
Connection *get_conn(ConnPool *pool, int sockfd) {
    for (size_t i = 0; i < pool->len; ++i) {
        if (pool->conns[i]->sockfd == sockfd) return pool->conns[i];
    }

    return NULL;  // no such connection found.
}

// Remove a connection from the pool and close the socket.
void remove_conn(ConnPool *pool, int sockfd) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->len; ++i) {
        if (pool->conns[i]->sockfd == sockfd) {
            close(sockfd);  // close the socket.

            free(pool->conns[i]);
            memmove(&pool->conns[i], &pool->conns[i + 1], (pool->len - i - 1) * sizeof(*pool->conns));  // shift elements left.
            --pool->len;

            if (pool->cap > 1 && pool->len <= pool->cap / 2) {  // reallocate if too much space is wasted.
                Connection **newConns = realloc(pool->conns, (pool->cap /= 2) * sizeof(*newConns));

                if (newConns != NULL) pool->conns = newConns;
            }

            break;
        }
    }

    pthread_mutex_unlock(&pool->lock);
}
```
To handle inactive connections, you would need to periodically call a function similar to this (this one simply removes any connection that hasn't been active for 10 seconds):

```c
void remove_inactive_conns(ConnPool *pool) {
    pthread_mutex_lock(&pool->lock);

    time_t now;
    time(&now);

    for (size_t i = 0; i < pool->len;) {
        if (difftime(now, pool->conns[i]->lastActiveTime) > 10) {  // connection has been inactive for more than 10 seconds.
            remove_conn(pool, pool->conns[i]->sockfd);
        } else {
            ++i;
        }
    }

    pthread_mutex_unlock(&pool->lock);
}
```
The full implementation would require error handling and additional features. Please consider all the constraints when implementing this solution.
