#define MAX_RNTI 10000
int used[MAX_RNTI] = {0}; // bitmap to check if RNTI is used or not
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* head = NULL;

int findAvailableRNTI() {
    int i = 0;
    pthread_mutex_lock(&lock);
    for(i=0; i<MAX_RNTI; i++) {
        if(!used[i]) {
            used[i] = 1;
            break;
        }
    }
    pthread_mutex_unlock(&lock);

    return (i == MAX_RNTI) ? -1 : i; // Return -1 if no RNTI is available
}

void insertNode(int RX_UE_INFORMATION_TAG, int CRC_INDICATION_REL8_TAG, int CRCFLAG) {
    int RNTI = findAvailableRNTI(); 

    // If all RNTIs are used, return error.
    if (RNTI == -1) {
        printf("Error: No available RNTI\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T* newNode = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    newNode->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newNode->RNTI = RNTI;
    newNode->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    newNode->CRCFLAG = CRCFLAG;

    pthread_mutex_lock(&lock);
    newNode->next = head;
    head = newNode;
    pthread_mutex_unlock(&lock);
}
