#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Session {
    int sessionID;
    char* userIP;
    time_t loginTime;
    double duration;
    struct Session *next;
}Session;

// Global pointer to the head of linked list 
Session *head = NULL;

void addSession(int id, const char *ip, double dur) {
    Session* newNode = (Session*) malloc(sizeof(Session));

    if(!newNode) {
        printf("Unable to allocate memory for session\n");
        return;
    }

    // Duplicate the IP string
    newNode->userIP = strdup(ip);
    if(!newNode->userIP) {
        printf("Failed to duplicate user ip string\n");
        free(newNode);
        return;
    }

    // Initialize session data 
    newNode->sessionID = id;
    newNode->duration = dur;
    time(&newNode->loginTime);

    // Add the new node at the beginning of linked list 
    newNode->next = head;
    head = newNode;
}

void removeSession(int id) {
    Session *temp = head, *prev = NULL;

    while (temp != NULL && temp->sessionID != id) {
        prev = temp;
        temp = temp->next;
    }

    // Unlink the node from linked list 
    if(temp == NULL) return; // Session not found 

    if(prev != NULL)
        prev->next = temp->next;

    if(head == temp)
        head = head->next;

    // Free the memory of user ip and node itself 
    free(temp->userIP);
    free(temp);
}

void clearSessions() {
    Session *current = head;
    while (current != NULL) {
        Session* nextNode = current->next;
        free(current->userIP);
        free(current);
        current = nextNode;
    }

    // Reset the head pointer 
    head = NULL;
}

void iterateSessions(double startTime, double endTime) {
    Session *temp = head;
    while (temp != NULL) {
        if (difftime(temp->loginTime, startTime) >= 0 && difftime(endTime, temp->loginTime) > 0) {
            printf("Session ID: %d\n", temp->sessionID);
            printf("User IP: %s\n", temp->userIP);
            printf("Login Time: %s", ctime(&temp->loginTime));
            printf("Duration: %f seconds\n", temp->duration);
        }

        temp = temp->next;
    }
}
```
This is a starting point and does not include any logging mechanism or memory pooling. You would need to implement your own logging function, use mempool library for efficient memory management, and add more checks for error cases.
