typedef struct nfapi_rrc_msg {
    int pdu_ie; //PDU IE tag
    void *data; //associated data
    struct nfapi_rrc_msg *prev; 
    struct nfapi_rrc_msg *next; 
} NFAPI_RRC_MSG;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

NFAPI_RRC_MSG* create_node(int pdu_ie, void *data) {
    NFAPI_RRC_MSG *newNode = (NFAPI_RRC_MSG *)malloc(sizeof(NFAPI_RRC_MSG)); 
    if(newNode == NULL){
        printf("Memory allocation failed!\n");
        exit(1); // Exit program due to error
    }

    newNode->pdu_ie = pdu_ie;
    newNode->data = data;
    newNode->prev = NULL;
    newNode->next = NULL;
    return newNode;
}

void add_node(NFAPI_RRC_MSG **head, int pdu_ie, void *data) {
    NFAPI_RRC_MSG *newNode = create_node(pdu_ie, data);

    pthread_mutex_lock(&lock); // Lock to handle concurrency
    if(*head == NULL){
        *head = newNode;
    } else {
        NFAPI_RRC_MSG *lastNode = *head;

        while(lastNode->next != NULL) lastNode = lastNode->next; // Go to the end of list

        lastNode->next = newNode;
        newNode->prev = lastNode;
    }

    pthread_mutex_unlock(&lock); // Unlock
}

void remove_node(NFAPI_RRC_MSG **head, int pdu_ie) {
    pthread_mutex_lock(&lock); // Lock to handle concurrency
    NFAPI_RRC_MSG *tempNode = *head;

    while (tempNode != NULL && tempNode->pdu_ie != pdu_ie){ 
        tempNode = tempNode->next;
    }

    if(tempNode == NULL){ // Tag not found, error handling
        printf("Tag not found in list!\n");
        return;
    }

    if (tempNode->prev != NULL) tempNode->prev->next = tempNode->next; 

    if (tempNode->next != NULL) tempNode->next->prev = tempNode->prev; 

    if (*head == tempNode){ // If head is the node to be deleted, move head ahead
        *head = tempNode->next;
    }

    free(tempNode); // Free memory
    pthread_mutex_unlock(&lock); // Unlock
}

void update_node(NFAPI_RRC_MSG **head, int pdu_ie, void *data) {
    pthread_mutex_lock(&lock); // Lock to handle concurrency
    NFAPI_RRC_MSG *tempNode = *head;

    while (tempNode != NULL && tempNode->pdu_ie != pdu_ie){ 
        tempNode = tempNode->next;
    }

    if(tempNode == NULL) { // Tag not found, error handling
        printf("Tag not found in list!\n");
        return;
    }

    tempNode->data = data; // Update data

    pthread_mutex_unlock(&lock); // Unlock
}
```
