int populate_network_events(NetworkEvent *events) {
    int i, j, k, retryCount = 0;
    DeviceIdentifier deviceIDs[MAX_EVENTS];

    for (i = 0; i < MAX_EVENTS; ++i) {
        /* Generate a unique Device ID */
        do {
            if (retryCount >= MAX_RETRIES) {
                fprintf(stderr, "Max retries reached. Unable to generate unique device identifier for event %d\n", i);
                return -1;
            }

            deviceIDs[i].deviceID = rand();
            for (j = 0; j < i; ++j) {
                if (deviceIDs[j].deviceID == deviceIDs[i].deviceID) {
                    fprintf(stderr, "Duplicate device identifier generated. Retrying...\n");
                    ++retryCount;
                    break;  /* Break out of inner loop */
                }
            }
        } while (j < i);

        events[i].deviceIdentifier = deviceIDs[i];

        /* Generate a random timestamp */
        events[i].timestamp.timestamp = time(NULL);

        /* Allocate memory for data payload */
        if ((events[i].dataPayload.dataPayload = 
             (char *) malloc(MAX_PAYLOAD_SIZE * sizeof(char))) == NULL) {
            fprintf(stderr, "Memory allocation failure\n");
            return -1;  /* Return error code */
        }

        /* Populate data payload with random characters */
        for (k = 0; k < MAX_PAYLOAD_SIZE; ++k) {
            events[i].dataPayload.dataPayload[k] = rand() % 256;
        }
    }

    return 0;
}
