#define MAX_CONNECTIONS 100
#define TIMEOUT 60

typedef struct {
    int socket;
    char ip[INET_ADDRSTRLEN];
    unsigned short port;
    time_t lastActivity;
} Connection;

Connection* connections[MAX_CONNECTIONS] = {NULL};
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
size_t connectionCount = 0;

void addConnection(int socket, const char* ip, unsigned short port) {
    pthread_mutex_lock(&lock);
    if (connectionCount < MAX_CONNECTIONS) {
        Connection* conn = malloc(sizeof(Connection));
        conn->socket = socket;
        strcpy(conn->ip, ip);
        conn->port = port;
        conn->lastActivity = time(NULL);
        connections[connectionCount++] = conn;
    } else {
        // Handle error: max connections exceeded
    }
    pthread_mutex_unlock(&lock);
}

void removeConnection(int socket) {
    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < connectionCount; ++i) {
        if (connections[i]->socket == socket) {
            free(connections[i]);
            connections[i] = connections[--connectionCount];
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

Connection* getConnection(int socket) {
    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < connectionCount; ++i) {
        if (connections[i]->socket == socket) {
            Connection* conn = connections[i];
            conn->lastActivity = time(NULL);
            pthread_mutex_unlock(&lock);
            return conn;
        }
    }
    pthread_mutex_unlock(&lock);
    // Handle error: connection not found
    return NULL;
}

void* checkInactivity(void* arg) {
    while (1) {
        sleep(TIMEOUT);
        time_t now = time(NULL);
        pthread_mutex_lock(&lock);
        for (size_t i = 0; i < connectionCount; ++i) {
            if (now - connections[i]->lastActivity > TIMEOUT) {
                free(connections[i]);
                connections[i] = connections[--connectionCount];
            }
        }
        pthread_mutex_unlock(&lock);
    }
    return NULL;
}

int main() {
    // Start inactivity check thread
    pthread_t tid;
    pthread_create(&tid, NULL, &checkInactivity, NULL);

    // Add and get connections...
    Connection* conn = getConnection(12345);
    if (conn != NULL) {
        printf("Found connection with socket %d\n", conn->socket);
    } else {
        addConnection(12345, "192.0.2.1", 80);
    }

    pthread_join(tid, NULL);
    return 0;
}
```
