pthread_mutex_t lock;  // Lock for thread-safety.

void appendToList(int RNTI, int CRCFLAG) {
    pthread_mutex_lock(&lock);   // Aquire the lock.

    if (count == size) {   // If list is full, double its size.
        if (!size) size = 1;  // First allocation.
        else size *= 2;

        list = realloc(list, sizeof(*list) * size);
        if (!list) {
            printf("Allocation error!\n");
            pthread_mutex_unlock(&lock);   // Unlock in case of failure.
            return;
        }
    }

    for (size_t i = 0; i < count; ++i) 
        if (list[i].RNTI == RNTI) {
            printf("Duplicate RNTI detected!\n");
            pthread_mutex_unlock(&lock);   // Unlock before return.
            return;
        }

    list[count].RNTI = RNTI;
    list[count].CRCFLAG = CRCFLAG;
    ++count;

    pthread_mutex_unlock(&lock);   // Always remember to unlock.
}
