NFAPI_CRC_INDICATION_PDU_T* generate_structures(int n, int min, int max) {
    srand(time(0));  // seed the random number generator
    NFAPI_CRC_INDICATION_PDU_T *arr = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (arr == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;  // handle error
    }

    int lastRNTI = 0;  // track the last RNTI value to ensure no duplicates
    for (int i = 0; i < n; ++i) {
        arr[i].RX_UE_INFORMATION_TAG = i + 1;  // set some unique tag

        int retryCount = 5;  // set max retry count
        do {
            arr[i].RNTI = lastRNTI + rand() % 10 + 1;  // generate a new RNTI that differs from the last one by at least 1

            if (arr[i].RNTI > max || arr[i].RNTI < min) {
                printf("Invalid range for RNTI. Retrying...\n");

                // Implementing exponential backoff
                double sleepTime = pow(2, 5 - retryCount);
                sleep(sleepTime);
            } else {
                break;
            }

        } while (--retryCount > 0);

        if (retryCount == 0) {
            printf("Failed to generate valid RNTI after multiple attempts. Skipping...\n");
            continue;
        }
        lastRNTI = arr[i].RNTI;  // update the last generated RNTI value

        arr[i].CRC_INDICATION_REL8_TAG = 0;  // some default tag
        arr[i].CRCFLAG = rand() % (max - min + 1) + min;  // set a random CRCFLAG within the specified range
    }

    return arr;
}
```
