#include <vector>
#include <algorithm>
#include <stdexcept>

void processValues(std::vector<int>& values, int inc_value, int base_value, int* result_ptr) {
    if (result_ptr == nullptr) {
        throw std::invalid_argument("Pointer must not be null");
    }

    *result_ptr += inc_value;  // increment the pointed value

    auto it = find(values.begin(), values.end(), base_value);

    if (it != values.end()) {
        values.insert(++it, *result_ptr);  // insert after first occurrence of base value
    } else {
        values.push_back(*result_ptr);  // append incremented value to the end if not found
    }
}
