} NFAPI_CRC_INDICATION_PDU_T;

// Define a node in the linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct Node *next;
} Node;

Node* head = NULL; // Head of the linked list
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; // Mutex for thread safety
int size = 0; // Current size of the list

// Function to add a new node to the list
void push(NFAPI_CRC_INDICATION_PDU_T *data) {
    pthread_mutex_lock(&mutex); // Lock the mutex before accessing shared resource

    Node* temp = (Node*) malloc(sizeof(Node));
    temp->data = data;
    temp->next = head;
    head = temp;
    size++;

    pthread_mutex_unlock(&mutex); // Unlock the mutex after accessing shared resource
}

// Function to remove a node from the list based on RNTI
void pop(int rnti) {
    if (size == 0 || head == NULL) {
        return; // If list is empty, return immediately
    }

    pthread_mutex_lock(&mutex); // Lock the mutex before accessing shared resource

    Node* temp = head;
    Node* prev = NULL;

    while (temp != NULL && temp->data->RNTI != rnti) { // Find the node with matching RNTI
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) return; // If not found, return immediately

    if (prev != NULL) { // Remove the node from the list
        prev->next = temp->next;
    } else {
        head = temp->next;
    }

    free(temp); // Free memory occupied by the removed node
    size--;

    pthread_mutex_unlock(&mutex); // Unlock the mutex after accessing shared resource
}
```
