        addNode(&list,node);
    }

    qsort(set+1, size, sizeof(int), compareDescending);  
    int max = set[1];  // maximum value is the first element after sorting in descending order

    pthread_mutex_lock(&lock);
    for (Node* node = list.head; node != NULL; node = node->next) {
        fprintf(logFile, "%d ", node->value);
    }
    fprintf(logFile, " - Max: %d\n", max);
    pthread_mutex_unlock(&lock);

    freeLinkedList(&list);  // release memory
}

int compareDescending(const void* a, const void* b) {
    int x = *((int*)a);
    int y = *((int*)b);
    return (x > y) - (x < y);
}

void freeLinkedList(LinkedList* list){
    Node* node = list->head;
    while(node != NULL){
        Node* nextNode = node->next;
        free(node);
        node = nextNode;
    }
}

