typedef struct dynamicArray {
    pthread_mutex_t lock; // Mutex for thread safety.
    NFAPI_CRC_INDICATION_PDU_T *array;
    int capacity;
    int size;
} dynamicArray;

void init(dynamicArray *arr, int initialCapacity) {
    arr->lock = (pthread_mutex_t) PTHREAD_MUTEX_INITIALIZER;
    arr->array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * initialCapacity);
    arr->capacity = initialCapacity;
    arr->size = 0;
}

void insert(dynamicArray *arr, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&(arr->lock)); // Acquire the lock.

    if (arr->size == arr->capacity) { 
        resize(arr);
    }

    arr->array[arr->size++] = element;

    pthread_mutex_unlock(&(arr->lock)); // Release the lock.
}

void resize(dynamicArray *arr) {
    pthread_mutex_lock(&(arr->lock)); // Acquire the lock.

    arr->capacity *= 2; 
    arr->array = realloc(arr->array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * arr->capacity);

    pthread_mutex_unlock(&(arr->lock)); // Release the lock.
}

void clear(dynamicArray *arr) {
    pthread_mutex_lock(&(arr->lock)); // Acquire the lock.

    free(arr->array);
    arr->size = 0;
    arr->capacity = 10;
    arr->array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * arr->capacity);

    pthread_mutex_unlock(&(arr->lock)); // Release the lock.
}
