["Here is the C++ code that meets all the requirements you specified:

```cpp
#include <mutex>
#include <forward_list>
#include <string>

std::mutex mtx; // Global mutex for synchronization

void insertAfterOrAppend(std::forward_list<std::string>& flist, const std::string& str1, const std::string& str2) {
    std::lock_guard<std::mutex> lock(mtx); // Lock the mutex to ensure thread-safety

    bool isPresent = false;

    auto prevIt = flist.before_begin();
    for (auto it = flist.begin(); it != flist.end(); ++it) {
        if (*it == str1) {
            isPresent = true;
            ++it; // Move the iterator to next element as we want to insert after this
            if(it == flist.end()) { // If the last element is equal to str1 then append at end
                flist.insert_after(prevIt, std::move(str2)); // Use move semantics for efficiency
            } else {
                ++prevIt;
            }
        }
    }

    if (!isPresent) {
        flist.push_back(std::move(str2)); // If str1 is not present in list then append at end
    }
}
```
