typedef struct {
    header hdr;
    size_t payload_size;
    char* data;
} packet;

typedef struct {
    pthread_mutex_t lock;
    packet** packets;
    int capacity;
    int size;
} packet_array;

void init_packet(packet* pkt, const header hdr, const char* data) {
    pkt->hdr = hdr;
    pkt->payload_size = strlen(data);
    if (pkt->payload_size > 0) {
        pkt->data = malloc(pkt->payload_size * sizeof(char));
        if (!pkt->data) {
            return;
        }
        memcpy(pkt->data, data, pkt->payload_size);
    } else {
        pkt->data = NULL;
    }
}

packet_array* init_packet_array() {
    packet_array* arr = malloc(sizeof(packet_array));
    if (!arr) {
        return NULL;
    }

    pthread_mutex_init(&arr->lock, NULL);
    arr->capacity = 1024;  // Initial allocation size
    arr->size = 0;
    arr->packets = malloc(arr->capacity * sizeof(packet*));
    if (!arr->packets) {
        free(arr);
        return NULL;
    }

    return arr;
}

void add_packet(packet_array* arr, const packet pkt) {
    pthread_mutex_lock(&arr->lock);
    if (arr->size == arr->capacity) {  // Resize strategy
        arr->capacity *= 2;
        packet** new_packets = realloc(arr->packets, arr->capacity * sizeof(packet*));
        if (!new_packets) {
            pthread_mutex_unlock(&arr->lock);
            return;
        }
        arr->packets = new_packets;
    }

    packet* new_pkt = malloc(sizeof(packet));
    if (!new_pkt) {
        pthread_mutex_unlock(&arr->lock);
        return;
    }
    *new_pkt = pkt;
    arr->packets[arr->size++] = new_pkt;

    pthread_mutex_unlock(&arr->lock);
}
```
