2. DNS resolution:
```c
#include <stdio.h>
#include <netdb.h>
#include <arpa/inet.h>

int resolve_hostname(const char* hostname, char** ip) {
    struct addrinfo hints, *res;
    int errcode;
    char addrstr[100];
    void *ptr;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = PF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_flags |= AI_CANONNAME;

    errcode = getaddrinfo(hostname, NULL, &hints, &res);
    if (errcode != 0) {
        perror("getaddrinfo");
        return -1;  // Return error code for network failure
    }

    while (res) {
        inet_ntop(res->ai_family, res->ai_addr->sa_data, addrstr, 100);

        switch (res->ai_family) {
            case AF_INET:
                ptr = &((struct sockaddr_in *) res->ai_addr)->sin_addr;
                break;
            case AF_INET6:
                ptr = &((struct sockaddr_in6 *) res->ai_addr)->sin6_addr;
                break;
        }

        inet_ntop(res->ai_family, ptr, addrstr, 100);
        printf("%s\n", addrstr);

        *ip = strdup(addrstr);  // Allocate memory for IP string and copy it

        res = res->ai_next;
    }

    freeaddrinfo(res);  // Remember to free the linked list returned by getaddrinfo()

    return 0;  // Return success code if no errors encountered
}
```
This function retrieves the IP address of a given hostname. It also handles network failures and temporary DNS server unavailability, returning appropriate error codes. The function is thread-safe due to the use of `getaddrinfo()` which is reentrant, but proper synchronization would be needed for multiple threads calling it simultaneously.
