        if (sessionList[i].ue_id == ue_id) {
            sessionList[i].connection_state = state;
            sessionList[i].network_data_source = data_source;

            if(state == ESTABLISHED) activeSessionCount++;
            else if (state == DISCONNECTED && sessionList[i].connection_state == ESTABLISHED) activeSessionCount--;

