typedef struct {
    int PacketID;
    time_t Timestamp;
    char* Payload;
} CellularDataPacket;

// Simple hash function to map packet ids to array indices
unsigned long hash(int key, unsigned int size) {
    return (key * 2654435761) % size;
}

CellularDataPacket* initializeAndConfigure() {
    // Initialize a dynamic array of CellularDataPacket structures
    int size = 10000;
    CellularDataPacket* packets = malloc(sizeof(CellularDataPacket) * size);

    for (int i = 0; i < size; i++) {
        // Initialize each packet with unique ID, timestamp and payload
        packets[i].PacketID = rand() % 10000 + 1;   // Generate random PacketID between 1-10000 for simplicity. Replace this with a more sophisticated logic in production code.
        packets[i].Timestamp = time(NULL);
        packets[i].Payload = NULL;
    }

    return packets;
}

void handlePacketUpdate(CellularDataPacket* packets, int size) {
    // Initialize zeroMQ context and socket for communication with message broker
    void *context = zmq_ctx_new ();
    void *requester = zmq_socket (context, ZMQ_REQ);
    zmq_connect (requester, "tcp://localhost:5555");  // Connect to the message broker address

    for(int i = 0; i < size; i++) {
        // Check for updated packets and update the hash table accordingly

        // Send a request to the message broker for any new packet updates for this PacketID
        zmq_send (requester, &packets[i].PacketID, sizeof(int), 0);
    }

    char buffer [256];
    zmq_recv (requester, buffer, 256, 0);

    // Update the payload of each packet in packets array with new data received from broker
    for(int i = 0; i < size; i++) {
        packets[i].Payload = malloc(strlen(buffer));
        strcpy(packets[i].Payload, buffer);
    }

    zmq_close (requester);
    zmq_ctx_destroy (context);
}
