```c
#include <stdio.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int id; // unique ID
    time_t initTime; // session initiation timestamp
    char *state; // connection state (established, disconnected, pending)
    time_t lastActivity; // last activity timestamp
} UEsession;

UEsession sessions[10000000]; // maximum number of sessions is 10 million
int sessionCount = 0; // current number of active sessions
pthread_mutex_t lock;

// Adding new session
void addSession(int id, char *state) {
    pthread_mutex_lock(&lock);
    if (sessionCount < 10000000) { // ensure we have space to add new sessions
        sessions[sessionCount].id = id;
        time(&sessions[sessionCount].initTime);
        sessions[sessionCount].state = state;
        sessionCount++;
    } else {
        printf("Maximum limit of 10 million sessions reached\n");
    }
    pthread_mutex_unlock(&lock);
}

// Updating existing session
void updateSession(int id, char *state) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < sessionCount; ++i) {
        if (sessions[i].id == id) {
            sessions[i].lastActivity = time(NULL); // update last activity timestamp
            sessions[i].state = state; // update connection state
        }
    }
    pthread_mutex_unlock(&lock);
}

// Retrieving the total number of active sessions
int getSessionCount() {
    return sessionCount;
}

// Automatic removal process for inactive sessions
void removeInactiveSessions(time_t idleTimeout) {
    pthread_mutex_lock(&lock);
    time_t currentTime = time(NULL);

    for (int i = 0; i < sessionCount; ++i) {
        if ((currentTime - sessions[i].lastActivity) > idleTimeout) { // check inactivity period
            // remove session logic goes here
            sessionCount--; // decrease the total count of active sessions
        }
    }

    pthread_mutex_unlock(&lock);
}
```

