} PHY_TASK_REQUEST_T;

typedef struct {
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    PHY_TASK_REQUEST_T *requests;
} RequestManager;

RequestManager manager;

void initManager() {
    srand(time(NULL));
    manager.count = 0;
    manager.capacity = 1024;  // initial capacity
    manager.requests = (PHY_TASK_REQUEST_T *)malloc(manager.capacity * sizeof(PHY_TASK_REQUEST_T));
    pthread_mutex_init(&manager.lock, NULL);
}

void addRequest(PHY_TASK_REQUEST_T request) {
    // You need to handle potential memory allocation failure here (realloc or something similar)
    pthread_mutex_lock(&manager.lock);  // thread-safe lock

    if (manager.count == manager.capacity) {
        manager.requests = realloc(manager.requests, manager.capacity * 2 * sizeof(PHY_TASK_REQUEST_T));
        manager.capacity *= 2;
    }

    // Initialize request fields
    request.POWER_LEVEL = rand() % MAX_POWER_LEVEL + 1;  // assuming MAX_POWER_LEVEL is defined somewhere
    manager.requests[manager.count++] = request;

    pthread_mutex_unlock(&manager.lock);  // unlock after modification
}

void cleanUp() {
    pthread_mutex_lock(&manager.lock);  // thread-safe lock

    if (manager.capacity > manager.count * 2) {
        manager.requests = realloc(manager.requests, manager.count * sizeof(PHY_TASK_REQUEST_T));
        manager.capacity = manager.count;
    }

    pthread_mutex_unlock(&manager.lock);  // unlock after modification
}
```
The `cleanUp` function will need to be invoked periodically, perhaps using a separate thread for periodic cleanup. The frequency of the cleanup should be determined based on your specific needs and requirements (e.g., it may be that you want to keep memory usage low but don't mind a higher potential latency in case of spikes).

