['Here's a basic code snippet that implements these requirements in C. Note this does not include all of your constraints but provides an idea of how you might structure such function.

```c
#include <stdlib.h>
#include <string.h>
#include <assert.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RNTI;
    // Other fields go here...
} NFAPI_CRC_INDICATION_PDU_T;

// Define the node structure for our linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node *list = NULL; // The start of our linked list
int size = 0;  // Current number of entries in the list.

void addEntry(NFAPI_CRC_INDICATION_PDU_T data) {
    assert(size < 10000);

    Node *temp = (Node*)malloc(sizeof(Node)); // Allocate new node

    if (!temp) { 
        printf("Memory allocation failed. Exiting.");
        exit(-1);
    }

    temp->data = data;
    temp->next = NULL;

    Node *lastNode = list;
    while (lastNode && lastNode->next) { // Check for duplicates
        if (lastNode->data.RNTI == data.RNTI) {
            printf("Error: Duplicate RNTI found.\n");
            return;
        }
        lastNode = lastNode->next;
    }

    if (!list) list = temp; // Add the node to our linked list
    else lastNode->next = temp;

    size++;  // Increment the number of entries in the list.
}

void removeEntry(int RNTI) {
    Node *temp = list, *prev = NULL;

    if (temp != NULL && temp->data.RNTI == RNTI) { // If RNTI is at head of list
        list = temp->next;
        free(temp); 
        return;
    }

    while (temp != NULL && temp->data.RNTI != RNTI) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) return; // If RNTI not found in list, do nothing

    prev->next = temp->next; // Unlink the node from linked list

    free(temp); // Free memory allocated for node
}

void retrieveAllEntries() {
    Node *temp = list;
    while (temp) {
        printf("RNTI: %d\n", temp->data.RNTI); 
        temp = temp->next;
    }
}

void clearList() {
    Node* current = list;
    Node* next;

    while (current != NULL) {
       next = current->next;
       free(current); // Free each node in the list
       current = next;
    }

    list = NULL; 
    size = 0;
}
```

This code uses a basic linked list structure to hold our entries. Each entry is checked for duplicates when added and removed on RNTI basis. For each operation, time complexity is O(n), where n is the number of elements in the list. This may not be efficient depending upon use cases but serves as a starting point. 

