```c
#include <pthread.h>
#include <stdatomic.h>
#include <stdlib.h>
#include <time.h>
#define MAX_SESSIONS 10000000

typedef enum {NORMAL, DEGRADED, UNSTABLE} networkStatus;
typedef enum {ESTABLISHED, DISCONNECTED, PENDING} connectionState;

typedef struct Session {
    int UE_identifier; // Should be unique
    time_t timestamp;
    connectionState state;
    networkStatus* networkDataSource; // Pointer to provider's data source
    atomic_int refCount; 
    pthread_mutex_t mutex;  
} Session;

Session *sessions[MAX_SESSIONS] = {NULL};
pthread_mutex_t sessionMutex = PTHREAD_MUTEX_INITIALIZER;
atomic_int activeSessionsCount = 0;

// Function for adding new sessions
void addSession(int UE_identifier, connectionState state, networkStatus* networkDataSource) {
    pthread_mutex_lock(&sessionMutex); 

    Session *newSession = (Session*) malloc(sizeof(Session));
    newSession->UE_identifier = UE_identifier;
    time(&newSession->timestamp);
    newSession->state = state;
    newSession->networkDataSource = networkDataSource;

    atomic_init(&newSession->refCount, 1); 
    pthread_mutex_init(&newSession->mutex, NULL);

    sessions[UE_identifier] = newSession;
    activeSessionsCount++;

    pthread_mutex_unlock(&sessionMutex); 
}

// Function for updating existing sessions
void updateSession(int UE_identifier, connectionState state) {
    pthread_mutex_lock(&sessionMutex);

    Session *session = sessions[UE_identifier];
    if (session != NULL){
        session->state = state;
        time(&session->timestamp); 
    }

    pthread_mutex_unlock(&sessionMutex);
}

// Function for retrieving the total number of active sessions.
int getActiveSessions() {
    return atomic_load(&activeSessionsCount);
}

void *checkNetworkStatus(void* arg) {
    int UE_identifier = *((int*)arg);

    while (1){
        pthread_mutex_lock(&sessionMutex); 
        Session *session = sessions[UE_identifier];
        if(session == NULL || atomic_load(&session->refCount) == 0){ 
            pthread_mutex_unlock(&sessionMutex);
            continue;
        }
        atomic_fetch_add(&session->refCount, 1);
        pthread_mutex_lock(&session->mutex); // Lock before checking status.

        networkStatus *dataSource = session->networkDataSource;
        if(/* check for intermittent failures */){
            /* Implement your retry logic here with exponential backoff*/
        } else {
           switch (session->state) {
                case NORMAL:  // Handle normal state.
                    break;
                case DEGRADED: // Handle degraded state.
                    break;
                case UNSTABLE:// Handle unstable state.
                    break;
            }
        }

        pthread_mutex_unlock(&session->mutex);
        atomic_fetch_sub(&session->refCount, 1);
    }

    pthread_exit(0);  
}
