// Add a PDU to the list. Resize if necessary.
void add(PduList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    // Check if we need to resize...
    if (list->count == list->capacity) {
        size_t newCapacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* newArray = realloc(list->pdus, sizeof(NFAPI_CRC_INDICATION_PDU_T) * newCapacity);
        if (newArray == NULL) {
            pthread_mutex_unlock(&list->lock); // Handle error here...
        } else {
            list->capacity = newCapacity;
            list->pdus = newArray;
        }
    }

    // Add the PDU to the array.
    list->pdus[list->count] = pdu;
    list->count++;

    pthread_mutex_unlock(&list->lock);
}

// Clean up resources when done with the list.
void cleanup(PduList* list) {
    pthread_mutex_destroy(&list->lock);
    free(list->pdus);
}
```

