  while (temp != NULL && temp->data->RNTI != rnti) {
    temp = temp->next;
  }

  if (temp == NULL) return NULL; // No PDU found with given RNTI

  return temp->data;
}

int length() {
  int count = 0;
  Node *current = head;

  while(current != NULL) {
    count++;
