} NetworkEvent;

NetworkEvent* generateRandomEvent(int maxSize) {
    NetworkEvent* event = malloc(sizeof(NetworkEvent));

    if (event == NULL) return NULL;

    /* Assumes external data sources provide DeviceIdentifier and DataPayload */
    event->DeviceIdentifier = getUniqueDeviceIdentifier();
    event->Timestamp = time(NULL);  // Use current system time as timestamp
    char* payload = getRandomDataPayload();

    if (strlen(payload) > maxSize) {
        free(event);
        return NULL;
    } else {
        event->DataPayload = malloc(maxSize + 1);  // Allocate space for the payload and a null terminator
        strncpy(event->DataPayload, payload, maxSize);  // Copy up to maxSize characters from payload
    }

    return event;
}

// Thread safe function to initialize array of NetworkEvents
NetworkEvent** initAndPopulateArray(int size, int maxPayloadSize) {
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;  // Declare a global mutex for thread safety

    NetworkEvent** array = malloc(sizeof(NetworkEvent*) * size);

    if (array == NULL) return NULL;

    pthread_mutex_lock(&lock);  // Lock mutex to ensure exclusive access during population

    for (int i = 0; i < size; ++i) {
        array[i] = generateRandomEvent(maxPayloadSize);

        if (array[i] == NULL) {
            /* Handle memory allocation failure gracefully */
            for (int j = 0; j < i; ++j) free(array[j]);  // Free any previously allocated events
            free(array);
            pthread_mutex_unlock(&lock);  // Unlock mutex before returning NULL
            return NULL;
        }
    }

    pthread_mutex_unlock(&lock);  // Unlock mutex after successful population

    return array;
}
```
