    int identity; // Representation of NRCellIdentity
} NRCellIdentity;

typedef struct {
    NRBand band;
    NRCellIdentity identity;
} NRCellConfig;

// A node in the linked list.
struct Node {
    NRCellConfig data;
    struct Node* next;
};

struct LinkedList {
    struct Node *head;
};

struct LinkedList* createLinkedList() {
    struct LinkedList* list = (struct LinkedList*) malloc(sizeof(struct LinkedList));
    if (!list) {
        printf("Memory error\n");
        return NULL;
    }
    list->head = NULL;
    return list;
}

void addToList(struct LinkedList *list, NRCellConfig data) {
    struct Node *node = (struct Node*) malloc(sizeof(struct Node));
    if (!node) {
        printf("Memory error\n");
        return;
    }
    node->data = data;
    node->next = list->head;
    list->head = node;
}

void removeFromList(struct LinkedList *list, NRCellConfig data) {
    struct Node *temp = list->head, *prev = NULL;

    while (temp != NULL && (temp->data.identity.identity != data.identity.identity)) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) return; // Element not found.

    if (prev != NULL)
        prev->next = temp->next;

    if (temp == list->head) 
        list->head = temp->next;

    free(temp);
}

void iterateList(struct LinkedList *list, void (*func)(NRCellConfig)) {
    struct Node* ptr = list->head;
    while (ptr != NULL) {
        func(ptr->data);
        ptr = ptr->next;
    }
}

// Serialization and deserialization functions can use fread/fwrite or other similar I/O operations. 
void serializeList(struct LinkedList *list, FILE* file) {
    struct Node* node = list->head;
    while (node != NULL) {
        fwrite(&node->data, sizeof(NRCellConfig), 1, file);
        node = node->next;
    }
}

void deserializeList(struct LinkedList *list, FILE* file) {
    NRCellConfig data;
    while (fread(&data, sizeof(NRCellConfig), 1, file)) {
        addToList(list, data);
    }
}
```
