['Here is a basic implementation of `LoadAndInitializeData` method in C# using LINQ to XML for parsing, XDocument for validating against schema and ConcurrentDictionary for efficient random initialization and update operations. This code does not cover the points regarding performance optimization, error handling or resource management as these are complex areas that need careful consideration based on actual requirements.

```csharp
using System;
using System.Linq;
using System.Xml.Schema;
using System.IO;
using System.Collections.Concurrent;
using System.Xml.Linq;

public class DataLoader
{
    public (ConcurrentDictionary<string, int> dataStructure, string errorMessage) LoadAndInitializeData(string xmlFilePath, string xpathQuery, XmlSchemaSet schemaSet, int minValue = 0, int maxValue = Int32.MaxValue)
    {
        ConcurrentDictionary<string, int> dataStructure;
        var document = new XDocument();
        try
        {
            document = XDocument.Load(xmlFilePath);

            // Validation against schema
            bool isValid = true;
            document.Validate(schemaSet, (o, e) => { isValid = false; });
            if (!isValid)
                return (null, $"The XML file at '{xmlFilePath}' does not validate against the provided schema.");
        }
        catch (Exception ex) when (ex is FileNotFoundException || ex is DirectoryNotFoundException)
        {
            // Log error
            return (null, $"Couldn't find the XML file at '{xmlFilePath}'. Error: {ex.Message}");
        }
        catch (XmlSchemaException xmlEx)
        {
            // Log error
            return (null, $"The XML document does not validate against the schema. Error: {xmlEx.Message}");
        }

        var rootElements = document.XPathSelectElements(xpathQuery);

        if (!rootElements.Any())
            return (new ConcurrentDictionary<string, int>(), string.Empty); // Return empty data structure

        if (rootElements.Count() > 1)
            return (null, "The XML document contains multiple root elements, which is not supported."); 

        Random rnd = new Random();
        var randomValues = rootElements.First().DescendantsAndSelf() // Assuming all nodes are to be loaded
            .ToDictionary(e => e.ToString(), _ => rnd.Next(minValue, maxValue)); // Generate a dictionary of random values 

        dataStructure = new ConcurrentDictionary<string, int>(randomValues);
        return (dataStructure, string.Empty);
    }
}
```

The method returns a tuple containing the initialized data structure and an error message if any errors occurred during execution. It also requires a predefined `XmlSchemaSet` to validate against in addition to XML file path and XPath query. 

Note: This code doesn't cover handling very large datasets or multiple threads accessing this data, which would require additional considerations and possibly a more complex solution. You may want to consider using more sophisticated data structures or database solutions for larger data volumes or concurrent access.
']

