Node* addDeviceEvent(Node** head, DeviceEvent *newEvent) {
    Node* new_node = (Node*) malloc(sizeof(Node));

    if (!new_node) return NULL;

    new_node->event = newEvent;
    new_node->next = *head;
    *head = new_node;

    return *head;
}

void removeOlderDeviceEvents(Node** head, time_t duration) {
    Node* temp = *head;
    Node* prev = NULL;

    while (temp != NULL && (temp->event->timestamp < (time(NULL) - duration))) {
        *head = temp->next;  // Removing the node

        free(temp->event);  // Freeing event memory
        free(temp);         // Freeing node memory

        temp = *head;
    }

    while (temp != NULL) {
        if ((temp->event->timestamp < (time(NULL) - duration))) {
            prev->next = temp->next;  // Removing the node

            free(temp->event);  // Freeing event memory
            free(temp);         // Freeing node memory
        }

        prev = temp;
        if (temp != NULL) {
            temp = temp->next;
        }
    }
}

DeviceEvent* getEventsByType(Node* head, int eventType, int* size) {
    DeviceEvent *filteredArray = NULL;
    Node* current = head;
    *size = 0;

    while (current != NULL) {
        if (current->event->eventType == eventType) {
            filteredArray = realloc(filteredArray, (*size + 1) * sizeof(DeviceEvent));
            filteredArray[*size] = *(current->event);  // Copying event struct
            ++(*size);
        }

        current = current->next;
    }

