int addConfig(NRCellConfig newConfig) {
   pthread_mutex_lock(&lock);
   // Check if NRCellIdentity is already in the array
   for (size_t i = 0; i < arraySize; ++i) {
      if (configArray[i].cellIdentity == newConfig.cellIdentity) {
         pthread_mutex_unlock(&lock);
         return -1; // Cell Identity already exists
      }
