   configArray = realloc(configArray, (arraySize + 1) * sizeof(*configArray));
   configArray[arraySize] = newConfig;
   ++arraySize;
   pthread_mutex_unlock(&lock);
   return 0; // Successfully added
}

int removeConfig(int NRCellIdentity) {
   pthread_mutex_lock(&lock);
   for (size_t i = 0; i < arraySize; ++i) {
      if (configArray[i].cellIdentity == NRCellIdentity) {
         // Shift all elements down, overwriting the removed one
         for(size_t j = i; j < arraySize - 1; ++j){
            configArray[j] = configArray[j + 1];
         }
         --arraySize;
         configArray = realloc(configArray, arraySize * sizeof(*configArray));
         pthread_mutex_unlock(&lock);
         return 0; // Successfully removed
      }
   }
   pthread_mutex_unlock(&lock);
   return -1; // Cell Identity not found
}
