#include <stdlib.h>
#include <string.h>

#define MAX_CAPACITY 50000

typedef struct PHY_STATISTICS_RECORD {
    int PHY_LAYER_IDENTIFIER;
    float TX_POWER_LEVEL;
    float SINR_MEASUREMENT;
} PHY_STATISTICS_RECORD;

typedef struct DynamicList {
    PHY_STATISTICS_RECORD* array;
    int size;
} DynamicList;

DynamicList* createDynamicList() {
    DynamicList* list = malloc(sizeof(DynamicList));
    if (list == NULL) exit(-1); // Handle allocation error 
    list->array = calloc(MAX_CAPACITY, sizeof(PHY_STATISTICS_RECORD));
    if (list->array == NULL) exit(-1); // Handle allocation error
    list->size = 0;
    return list;
}

void addElement(DynamicList* list, PHY_STATISTICS_RECORD element) {
    if (list->size >= MAX_CAPACITY) {
        printf("Error: Maximum capacity reached.\n");
        return;
    }
    memcpy(&list->array[list->size], &element, sizeof(PHY_STATISTICS_RECORD));
    list->size++;
}

void updateElementByID(DynamicList* list, int id, PHY_STATISTICS_RECORD newValue) {
    for (int i = 0; i < list->size; ++i) {
        if (list->array[i].PHY_LAYER_IDENTIFIER == id) {
            memcpy(&list->array[i], &newValue, sizeof(PHY_STATISTICS_RECORD));
            return;
        }
    }
    printf("Error: No element with provided ID found.\n");
}

void removeElementByCondition(DynamicList* list, int (*condition)(PHY_STATISTICS_RECORD)) {
    for (int i = 0; i < list->size; ++i) {
        if (condition(list->array[i])) {
            // Remove element by shifting all subsequent elements back one index.
            memmove(&list->array[i], &list->array[i + 1], (list->size - i - 1) * sizeof(PHY_STATISTICS_RECORD));
            list->size--;
            return;
        }
    }
}
