typedef struct {
    long timestamp;
    char eventType[30];  // assuming event type is a string
    void *metadata;      // this could be anything depending on the specific requirements
} Event;

typedef struct {
    Event **events;
    size_t capacity;
    size_t length;
    pthread_mutex_t lock;
} EventArray;

EventArray* createEventArray(size_t initialSize) {
    EventArray *array = (EventArray*) malloc(sizeof(EventArray));
    if (!array) return NULL;

    array->events = (Event**) calloc(initialSize, sizeof(Event*));
    array->capacity = initialSize;
    array->length = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void destroyEventArray(EventArray *array) {
    for (size_t i = 0; i < array->capacity; ++i)
        free(array->events[i]);

    free(array->events);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

void addEvent(EventArray *array, Event *event) {
    pthread_mutex_lock(&array->lock);

    if (array->length == array->capacity) {
        // double the capacity to amortize the cost of resizing.
        size_t newCapacity = array->capacity * 2;
        Event **newEvents = (Event**) realloc(array->events, newCapacity * sizeof(Event*));

        if (!newEvents) {
            pthread_mutex_unlock(&array->lock);
            return;
        }

        array->capacity = newCapacity;
        array->events = newEvents;
    }

    Event *copy = (Event*) malloc(sizeof(Event));
    memcpy(copy, event, sizeof(Event));
    array->events[array->length++] = copy;

    pthread_mutex_unlock(&array->lock);
}
```

This is a basic implementation of the dynamically resizing EventArray. Note that in a real-world application, you'd need to handle concurrency issues more carefully (for instance by using thread-safe data structures and locks), error handling, logging, and testing. Also, this example does not consider disk storage or asynchronous event processing.
