```csharp
using System;
using System.IO;
using System.Linq;
using System.Xml.Serialization;

public class GameConfiguration
{
    public int TileSize { get; set; }
    public int WorldDimension { get; set; }
    public double CameraSpeed { get; set; }
}

[XmlRoot("GameEnvironment")]
public class GameEnvironment
{
    private static readonly Lazy<GameEnvironment> instance = new Lazy<GameEnvironment>(() => new GameEnvironment());

    public static GameEnvironment Instance => instance.Value;

    [XmlArrayItem(typeof(GameConfiguration))]
    public GameConfiguration[] Configurations { get; set; }

    private FileSystemWatcher fileWatcher;
    private string configFilePath = "path_to_your_xml_file";

    private GameEnvironment()
    {
        LoadConfigurations();

        fileWatcher = new FileSystemWatcher(Path.GetDirectoryName(configFilePath), Path.GetFileName(configFilePath));
        fileWatcher.Changed += OnConfigurationChanged;
        fileWatcher.EnableRaisingEvents = true;
    }

    public GameConfiguration GetConfigForLevel(string levelId) => Configurations.FirstOrDefault(c => c.LevelId == levelId);

    private void LoadConfigurations()
    {
        var xmlSerializer = new XmlSerializer(typeof(GameEnvironment));

        using (var fileStream = new FileStream(configFilePath, FileMode.Open))
        {
            Configurations = ((GameEnvironment)xmlSerializer.Deserialize(fileStream)).Configurations;
        }
    }

    private void OnConfigurationChanged(object source, FileSystemEventArgs e) => LoadConfigurations();
}
```

