void addToArray(NFAPI_RX_MESSAGE_T element) {
    pthread_mutex_lock(&lock);

    // Reallocate memory for the new element. 
    NFAPI_RX_MESSAGE_T* temp = realloc(array, (currSize + 1) * sizeof(*array));
    if (temp == NULL) {
        handleAllocationFailure();
    }

    array = temp;
    array[currSize++] = element; // Copy the new element.

    pthread_mutex_unlock(&lock);
}

NFAPI_RX_MESSAGE_T getFromArray(int index) {
    NFAPI_RX_MESSAGE_T value;

    pthread_mutex_lock(&lock);

    if (index >= 0 && index < currSize) {
        value = array[index]; // Copy the element.
    } else {
        fprintf(stderr, "Index out of bounds.\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_unlock(&lock);

    return value;
}
