typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    size_t count;
    size_t capacity;
    NFAPI_CRC_INDICATION_PDU_T *array;
} ArrayManager;

ArrayManager arrayManager;

int initialize(size_t initialCapacity) {
    arrayManager.count = 0;
    arrayManager.capacity = initialCapacity;
    arrayManager.array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (arrayManager.array == NULL) {
        return -1; // allocation failed
    }
    return 0; // successful initialization
}

int addElement(NFAPI_CRC_INDICATION_PDU_T element) {
    if (element.RNTI > MAX_RNTI) {
        return -1; // RNTI out of range
    }
    if (arrayManager.count >= arrayManager.capacity) {
        size_t newCapacity = arrayManager.capacity * 2; // doubling capacity each time we run out
        NFAPI_CRC_INDICATION_PDU_T *newArray = (NFAPI_CRC_INDICATION_PDU_T *)realloc(arrayManager.array, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (newArray == NULL) {
            return -2; // reallocation failed
        }
        arrayManager.capacity = newCapacity;
        arrayManager.array = newArray;
    }
    for(int i = 0; i < arrayManager.count; ++i){
        if (arrayManager.array[i].RNTI == element.RNTI) {
            arrayManager.array[i] = element; // update existing element
            return 1; // updated an existing element
        }
    }
    arrayManager.array[arrayManager.count++] = element;
    return 0; // added a new element
}

NFAPI_CRC_INDICATION_PDU_T* getElementByRNTI(unsigned short RNTI) {
    for (size_t i = 0; i < arrayManager.count; ++i) {
        if (arrayManager.array[i].RNTI == RNTI) {
            return &arrayManager.array[i]; // found the element
        }
    }
    return NULL; // no such element exists
}
