['Below is a sample code snippet using Java's NIO.2 API (Files, Paths classes) to access the file paths in remote server configuration and calculate MD5 hash of each accessible file storing results in HashMap. Error handling is done by logging error messages and continuing with remaining entries. 

```java
import java.io.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import org.apache.commons.codec.digest.*;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

public class RemoteFileHashCalculator {
    private static final Logger logger = LogManager.getLogger(RemoteFileHashCalculator.class);

    // Assuming the remote server configuration file is accessible via a shared network path
    private static final String SERVER_CONFIG_FILEPATH = "\\\\remoteServer\\sharedPath\\serverConfig.txt";

    public Map<String, String> calculateFileHashes() throws IOException {
        HashMap<String, String> hashMap = new HashMap<>();

        List<String> filePaths = Files.readAllLines(Paths.get(SERVER_CONFIG_FILEPATH));

        for (String path : filePaths) {
            if (path == null || path.isEmpty()) continue;

            Path p = Paths.get(path);

            // Ignore directories and symbolic links
            if (!Files.isRegularFile(p)) continue;

            try {
                MessageDigest md5 = MessageDigest.getInstance("MD5");
                InputStream is = Files.newInputStream(p);
                DigestInputStream dis = new DigestInputStream(is, md5);
                while (dis.read() != -1) ; // Consume all bytes from the stream to calculate hash
                byte[] digest = md5.digest();
                String hexHash = Hex.encodeHexString(digest);

                hashMap.put(p.getFileName().toString(), hexHash);
            } catch (NoSuchFileException | AccessDeniedException e) {
                logger.error("Failed to access file: " + p, e);
            } catch (IOException | NoSuchAlgorithmException e) {
                logger.error(e);
            } 
        }

        return hashMap;
    }
}
```
Please note that this is a simple solution and you may need to adjust it based on your specific requirements, including error handling strategies, I/O performance optimization techniques, network latency handling, extensibility considerations etc. Also make sure to include the necessary dependencies in your project (for instance Apache Commons Codec for hex encoding, Log4j for logging).
