['Here is a basic implementation in C using the `wchar_t` type for wide characters and UTF-8 encoded strings, which makes it compatible with internationalized text handling:

```c
#include <stdlib.h>
#include <string.h>
#include <assert.h>

typedef struct {
    // add metadata fields here...
} StringMetadata;

// Function pointer typedef for external data source integration
typedef const StringMetadata* (*GetStringMetadataFunc)(const wchar_t* str);

wchar_t* processUTF8String(const char *src, size_t srcSizeLimit, int allowTruncateEllipsis, GetStringMetadataFunc getMetadata) {
    if (src == NULL || getMetadata == NULL) {
        return NULL;
    }

    // Convert the source string to wide characters for better international support
    size_t srcSize = strlen(src);
    wchar_t *wcsStr = malloc((srcSize + 1) * sizeof(wchar_t));  // +1 for null terminator
    if (wcsStr == NULL) {
        return NULL;  // Failed to allocate memory
    }
    size_t numConverted = 0;
    mbstowcs_s(&numConverted, wcsStr, srcSize + 1, src, _TRUNCATE);

    const StringMetadata *metadata = getMetadata(wcsStr);
    assert(metadata != NULL);  // Ensure metadata retrieval was successful

    // Process the string according to the given limit and additional logic based on metadata
    wchar_t *result;
    size_t resultSizeLimit = allowTruncateEllipsis ? srcSizeLimit - 3 : srcSizeLimit;
    if (srcSize > resultSizeLimit) {
        // Truncate the string with an ellipsis if allowed and necessary
        result = malloc((resultSizeLimit + 4) * sizeof(wchar_t));  // +1 for null terminator, +3 for "..."
        wcsncpy_s(result, resultSizeLimit + 1, wcsStr, resultSizeLimit);
        if (allowTruncateEllipsis) {
            wcscat_s(result, resultSizeLimit + 4, L"...");
        }
    } else {
        // No truncation needed - just copy the string
        result = malloc((srcSize + 1) * sizeof(wchar_t));  // +1 for null terminator
        wcscpy_s(result, srcSize + 1, wcsStr);
    }

    free(wcsStr);
    return result;
}
```

Please note that this is a basic example and does not take into account many real-world considerations for performance optimization, memory usage, error handling, etc. Also, the code above assumes UTF-8 encoding and wide characters are encoded in the platform's native byte order (endianness). For correct handling of multi-byte character encodings, such as UTF-16 or UTF-32, a more complex implementation would be required.
