["Here is a simple implementation in C using OpenSSL library:

```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/sha.h>
#include <string.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
} CipherContext;

void cleanup(CipherContext *cipher) {
    if (cipher->ctx != NULL) EVP_CIPHER_CTX_free(cipher->ctx);
    OPENSSL_cleanse(cipher->key, sizeof(cipher->key));
    OPENSSL_cleanse(cipher->iv, sizeof(cipher->iv));
}

int initializeCipherContext(CipherContext *cipher, const char* password, int iterations) {
    cipher->ctx = EVP_CIPHER_CTX_new();

    if (RAND_bytes(cipher->iv, sizeof(cipher->iv)) != 1) return 0; // error generating IV

    int keyLen = EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), NULL, (unsigned char*)password, strlen(password), iterations, cipher->key, cipher->iv);
    if (keyLen != SHA256_DIGEST_LENGTH) return 0; // error deriving key

    EVP_EncryptInit_ex(cipher->ctx, EVP_aes_256_cbc(), NULL, cipher->key, cipher->iv);

    return 1;
}
```
Note: The above code snippet is a simple demonstration of how to implement an AES-256-CBC encryption using PBKDF2-HMAC-SHA256 for key derivation, and it does not contain any logging or error handling mechanisms. Developers should add these features in a real application. 

It's also important to note that the EVP_BytesToKey function is deprecated since OpenSSL 3.0.0. A more secure alternative would be to use PKCS5_PBKDF2_HMAC instead. However, using this method requires additional libraries or code to perform SHA-256 hashing, which can add complexity and may impact performance for some applications.
