const axios = require('axios');
const fs = require('fs').promises;
const Busboy = require('busboy');
const md5File = require('md5-file/promise');
const urlMetadata = require('url-metadata');

const MAX_CONCURRENT = 200;
const ALLOWED_FILETYPES = ['jpg', 'png'];
const MAX_SIZE = 10 * 1024 * 1024; // 10MB in bytes

async function uploadFiles(urls) {
    const results = [];
    let running = 0;

    async function processUrl(url) {
        try {
            const fileName = url.split('/').pop();
            const ext = fileName.split('.').pop().toLowerCase();

            if (!ALLOWED_FILETYPES.includes(ext)) throw new Error('Invalid file type');

            const response = await axios({ url, method: 'GET', responseType: 'stream' });
            const fileSize = parseInt(response.headers['content-length'], 10);

            if (fileSize > MAX_SIZE) throw new Error('File size exceeds limit');

            await fs.writeFile('/tmp/' + fileName, response.data); // write to temp location
            const hash = await md5File('/tmp/' + fileName); // calculate hash for metadata extraction
            const metadata = await urlMetadata(url);

            console.log('Uploading:', fileName);
            // Assume remoteStorageService is an instance of a class with an upload method
            const result = await remoteStorageService.upload('/tmp/' + fileName, { hash, metadata });
            results.push({ url, status: 'success', log: 'File uploaded successfully' });
        } catch (err) {
            console.error('Upload failed:', err);
            results.push({ url, status: 'failure', log: err.toString() });
        } finally {
            running--;
            startNext();
        }
    }

    function startNext() {
        while (running < MAX_CONCURRENT && urls.length) {
            const url = urls.shift();
            running++;
            processUrl(url);
        }
    }

    await startNext();
    return results;
}
```
