    if (numEntries > ((size_t)-1 / sizeof(entry_t))) {
        fprintf(stderr, "Too many entries. Exceeds memory limit.\n");
        return NULL;
    }

    entry_t* entries = malloc(numEntries * sizeof(*entries));
    if (!entries) {
        fprintf(stderr, "Memory allocation failed. Exiting...\n");
        exit(-1);
    }

    // Allocate memory for data and initialize each entry
    for (size_t i = 0; i < numEntries; ++i) {
        size_t len = strlen(predefinedWords[i]);

        if (len > 1024) {
            fprintf(stderr, "Word length exceeds limit. Exiting...\n");
            exit(-1);
        }

        // Allocate memory for data
        entries[i].data = malloc(sizeof(*entries[i].data));
        if (!entries[i].data) {
            fprintf(stderr, "Memory allocation failed. Exiting...\n");
            exit(-1);
        }

        // Initialize data and key
        entries[i].key.key = malloc(len + 1);
        if (!entries[i].key.key) {
            fprintf(stderr, "Memory allocation failed. Exiting...\n");
            exit(-1);
        }

        strcpy(entries[i].data->data, predefinedWords[i]);
        entries[i].data->len = len;
        entries[i].ref_count = 0;
    }

