    void *data;
    struct Node *next;
}Node;

typedef struct List{
    Node *head;
    pthread_mutex_t lock; // for thread safety 
}List;

// Initialize the list
void init(List* l){
    l->head = NULL;
    if (pthread_mutex_init(&l->lock, NULL) != 0){
        exit(1);
    }
}

// Insert UEContext to the list. The function is thread safe.
void insert(List* l, void *data, size_t dataSize){
    pthread_mutex_lock(&l->lock); // lock the mutex

    Node* node = (Node*)malloc(sizeof(Node)); 
    node->data  = malloc(dataSize);
    node->next = NULL;

    memcpy(node->data, data, dataSize); 
    if(l->head == NULL){  
        l->head=node;
    } else {  
        Node* temp = l->head;
        while(temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = node; 
    } 

    pthread_mutex_unlock(&l->lock); // unlock the mutex
}

// Delete a UEContext from the list. The function is thread safe.
void delete(List* l, void *data){
    pthread_mutex_lock(&l->lock); // lock the mutex

    Node* temp = l->head; 
    Node* prevNode = NULL;  

    if(temp != NULL && memcmp(temp->data, data, sizeof(*data)) == 0){ 
        l->head = temp->next;
        free(temp);
    } else {
        while (temp != NULL && memcmp(temp->data, data, sizeof(*data)) != 0) { 
            prevNode = temp;  
            temp = temp->next;  
        }
        if(temp == NULL){
            return; 
        } 
        prevNode->next = temp->next; 
        free(temp);   
    }

    pthread_mutex_unlock(&l->lock); // unlock the mutex
}

