#include <time.h>
#include <string.h>

typedef struct PDU {
    void* data;
    size_t dataSize;
    time_t timestamp;
} PDU;

typedef struct UEContext {
    pthread_mutex_t lock;
    int cellID;
    int RNTI;
    char *MMEId;
    PDU **PDUs;
    size_t PDUSize;
    size_t PDUCapacity;
} UEContext;

void UEContextInit(UEContext* ctx, int cellID, int RNTI, const char* MMEId) {
    if (!ctx || !MMEId) {
        return;
    }

    ctx->cellID = cellID;
    ctx->RNTI = RNTI;
    ctx->MMEId = strdup(MMEId);
    ctx->PDUSize = 0;
    ctx->PDUCapacity = 10;
    ctx->PDUs = malloc(ctx->PDUCapacity * sizeof(PDU*));

    pthread_mutex_init(&ctx->lock, NULL);
}

void UEContextDestroy(UEContext* ctx) {
    if (!ctx) {
        return;
    }

    free(ctx->MMEId);
    for (size_t i = 0; i < ctx->PDUSize; ++i) {
        free(ctx->PDUs[i]->data);
        free(ctx->PDUs[i]);
    }

    free(ctx->PDUs);
    pthread_mutex_destroy(&ctx->lock);
}

void UEContextAddPDU(UEContext* ctx, void* data, size_t dataSize) {
    if (!ctx || !data) {
        return;
    }

    PDU* newPDU = malloc(sizeof(PDU));
    newPDU->data = malloc(dataSize);
    memcpy(newPDU->data, data, dataSize);
    newPDU->dataSize = dataSize;
    time(&newPDU->timestamp);

    pthread_mutex_lock(&ctx->lock);
    if (ctx->PDUSize == ctx->PDUCapacity) {
        ctx->PDUs = realloc(ctx->PDUs, 2 * ctx->PDUCapacity * sizeof(PDU*));
        ctx->PDUCapacity *= 2;
    }

    ctx->PDUs[ctx->PDUSize++] = newPDU;
    pthread_mutex_unlock(&ctx->lock);
}
``` 
