["Here is a rough outline of how the semaphore management system can be implemented in C using POSIX threads. Note that actual implementation would require careful consideration of thread safety, error handling, configuration fetching from external services etc.

```c
#include <pthread.h>
#include <semaphore.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

typedef struct sema_info {
    char name[256];
    sem_t* sem;
    int value;
} SemInfo;

SemInfo* pool = NULL;
int poolSize = 0;
pthread_mutex_t mutexPool = PTHREAD_MUTEX_INITIALIZER;

void handleExternalDependency() {
    // Fetch configuration from external service. 
}

sem_t* getSemaphore(const char* name) {
    pthread_mutex_lock(&mutexPool);
    for (int i = 0; i < poolSize; ++i) {
        if (strcmp(pool[i].name, name) == 0) {
            sem_wait(pool[i].sem);  // Handle wait time and active semaphore count.
            pthread_mutex_unlock(&mutexPool);
            return pool[i].sem;
        }
    }

    if (poolSize == SIZE_MAX) {
        pthread_mutex_unlock(&mutexPool);
        // Handle reaching the maximum capacity.
    } else {
        ++poolSize;
        pool = realloc(pool, poolSize * sizeof(SemInfo));
        SemInfo* newSemaphore = &pool[poolSize - 1];
        strcpy(newSemaphore->name, name);
        handleExternalDependency(); // Fetch configuration for new semaphore.
        newSemaphore->value = fetchValueFromConfigService(name); // Assuming function exists to get initial value from config service
        newSemaphore->sem = malloc(sizeof(sem_t));
        sem_init(newSemaphore->sem, 0, newSemaphore->value);
        pthread_mutex_unlock(&mutexPool);
        return newSemaphore->sem;
    }
}
```
