typedef struct {
    size_t capacity;
    size_t length;
    LTE_UERadioLinkControl_T *array;
} DynamicArray;

pthread_mutex_t arrayMutex = PTHREAD_MUTEX_INITIALIZER;

void initializeArray(DynamicArray *a, size_t initialSize) {
    a->array = (LTE_UERadioLinkControl_T*)malloc(initialSize * sizeof(LTE_UERadioLinkControl_T));
    a->length = 0;
    a->capacity = initialSize;
}

void insertArray(DynamicArray *a, LTE_UERadioLinkControl_T element) {
    pthread_mutex_lock(&arrayMutex);

    if (a->length == a->capacity) {
        a->capacity = a->capacity ? a->capacity * 2 : 1;
        a->array = (LTE_UERadioLinkControl_T*)realloc(a->array, a->capacity * sizeof(LTE_UERadioLinkControl_T));
    }

    a->array[a->length++] = element;

    pthread_mutex_unlock(&arrayMutex);
}

void freeArray(DynamicArray *a) {
    pthread_mutex_lock(&arrayMutex);

    free(a->array);
    a->array = NULL;
    a->length = 0;
    a->capacity = 0;

    pthread_mutex_unlock(&arrayMutex);
}
```
