// Function to validate RNTI uniqueness in the list
int isUniqueRNTI(uint16_t rnti) {
    Node *current = head;
    while (current != NULL) {
        if (current->data.rxInfoTag.RNTI == rnti) {
            return 0; // RNTI is not unique
        }
        current = current->next;
    }
    return 1; // RNTI is unique
}

