        fprintf(logFile, "Error: Memory allocation limit exceeded\n");
        pthread_mutex_unlock(&mutex); // Unlock mutex before return
        return NULL; 
    }

    Node *newNode = (Node*)malloc(sizeof(Node)); // Allocate memory for new node
    if (!newNode) {
        fprintf(logFile, "Error: %s\n", strerror(errno));
        pthread_mutex_unlock(&mutex); // Unlock mutex before return
        return NULL; 
    }

    newNode->data.rxInfoTag.RNTI = rnti; // Set RNTI and CRCFLAG values
    newNode->data.crcIndicationTag.CRCFLAG = crcflag;

    newNode->next = head; // Add the node at the beginning of the list
    head = newNode; 

    pthread_mutex_unlock(&mutex); // Unlock mutex after operation is completed

    return NULL;
}

