import org.apache.commons.codec.digest.DigestUtils;
import com.google.common.cache.CacheBuilder;
import com.google.common.cache.CacheLoader;
import com.google.common.cache.LoadingCache;
import java.nio.charset.StandardCharsets;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

public class HashUtils {
    private static final Logger logger = LogManager.getLogger(HashUtils.class);
    // Create a cache with maximum size of 10% of available memory, evict based on LRU
    private static LoadingCache<String, String> hashCache = CacheBuilder.newBuilder()
            .maximumWeight(Runtime.getRuntime().maxMemory() / 10)
            .weigher((key, value) -> 4 * key.length()) // assume average MD5 length is 32 bytes
            .removalListener(notification -> logger.debug("Evicted: {}", notification))
            .build(new CacheLoader<String, String>() {
                public String load(String input) throws Exception {
                    // This method will be called only when the requested data is not in cache.
                    logger.info("Cache miss for input: {}", input);
                    return DigestUtils.md5Hex(input.getBytes(StandardCharsets.UTF_8));
                }
            });

    public static String hashWithMd5AndCache(String input) {
        try {
            // Try to fetch from cache, will call the load() method if necessary.
            return hashCache.getUnchecked(input); 
        } catch (Exception e) {
            logger.error("Failed to compute MD5 with caching", e);
            throw new RuntimeException("MD5 computation failed", e);
        }
    }
}
```
