                    if (isValidFile(path)) {
                        String hash = computeHash(path);
                        Metadata metadata = metadataService.getMetadata(path);

                        // Handle hash and metadata as needed...
                    }
                } catch (Exception e) {
                    handleError(e, path);
                }
            });
        }

        executorService.shutdown();
    }

    private boolean isValidFile(Path filePath) {
        File file = filePath.toFile();
        if (!file.exists() || !file.isFile()) {
            return false;
        }

        String extension = "";
        int i = file.getName().lastIndexOf('.');
        if (i > 0) {
            extension = file.getName().substring(i);
        }

        return Arrays.asList(ALLOWED_EXTENSIONS).contains(extension);
    }

    private String computeHash(Path filePath) throws Exception {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        try (InputStream is = Files.newInputStream(filePath)) {
            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = is.read(buffer)) != -1) {
                md.update(buffer, 0, bytesRead);
            }
        }

        byte[] digest = md.digest();
        return DatatypeConverter.printHexBinary(digest).toLowerCase();
    }

    private void handleError(Exception e, Path filePath) {
        // Handle error as needed...
        System.out.println("Error processing file " + filePath.toString() + ": " + e);
    }
}
```

This class uses an ExecutorService to process files in parallel. A thread-safe fallback mechanism is implemented in case the metadata service is unavailable, but this behavior can be customized as needed. The method `isValidFile` and `computeHash` are synchronized for thread safety and minimize I/O operations by reading file chunks into a buffer instead of whole files at once. However, please note that creating and managing threads incurs overhead, which might not outweigh the benefits if there are too many files to process or they're very large.
']

