void add_connection(int id, long timestamp, char *status) {
    pthread_mutex_lock(&lock);

    // Resize connections array
    list.connections = realloc(list.connections, ++list.count * sizeof(Connection*));

    Connection *connection = malloc(sizeof(Connection));
    connection->id = id;
    connection->timestamp = timestamp;
    strcpy(connection->status, status);

    list.connections[list.count - 1] = connection;

    pthread_mutex_unlock(&lock);
}

void remove_connection(int id) {
    pthread_mutex_lock(&lock);

    // Find the index of connection to be removed
    int i = 0;
    for (; i < list.count; ++i) {
        if (list.connections[i]->id == id)
            break;
    }

    // If found, remove it and free its memory
    if (i < list.count) {
        free(list.connections[i]);

        for (; i < list.count - 1; ++i) {
            list.connections[i] = list.connections[i + 1];
        }

        --list.count;
    }

    pthread_mutex_unlock(&lock);
}

void update_connection(int id, long timestamp, char *status) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < list.count; ++i) {
        if (list.connections[i]->id == id) {
            list.connections[i]->timestamp = timestamp;
            strcpy(list.connections[i]->status, status);
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}

void cleanup() {
    for (int i = 0; i < list.count; ++i) {
        free(list.connections[i]);
    }
    free(list.connections);
}
```

