void* insert(NFAPI_CRC_INDICATION_PDU_T data) {
    Node *temp = malloc(sizeof(Node));
    temp->data = data;
    temp->next = NULL;

    pthread_mutex_lock(&lock);
    Node* current = head;
    int isUnique = 1;
    while (current) {
        if (current->data.RNTI == data.RNTI){
            isUnique = 0;
            break;
