    if(isUnique) {
        temp->next = head;
        while(!__sync_bool_compare_and_swap(&head, temp->next, temp)) {} // CAS operation to ensure no race condition during concurrent insertions
        ++totalNodes; 
        ++uniqueRNTIs;
    } else {
        free(temp);
    }
}

