```Java
import java.io.*;
import java.security.*;
import java.util.*;
import java.nio.file.*;
import java.util.concurrent.*;
import java.util.logging.*;

class FileProcessor {
    private final ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();
    private static final Logger logger = Logger.getLogger(FileProcessor.class.getName());

    // method to compute MD5 hash of a file content 
    public byte[] getMD5Checksum(Path filename) throws Exception {
        InputStream fis = Files.newInputStream(filename);

        byte[] buffer = new byte[1024];
        MessageDigest complete = MessageDigest.getInstance("MD5");
        int numRead;

        do {
            numRead = fis.read(buffer);
            if (numRead > 0) {
                complete.update(buffer, 0, numRead);
            }
        } while (numRead != -1);

        fis.close();
        return complete.digest();
    }

    // method to convert byte array to hex string
    public String getMD5ChecksumHex(Path filename) throws Exception {
        byte[] b = getMD5Checksum(filename);
        StringBuilder result = new StringBuilder();

        for (int i = 0; i < b.length; i++) {
            result.append(Integer.toString((b[i] & 0xff) + 0x100, 16).substring(1));
        }

        return result.toString();
    }

    // method to process a list of file paths 
    public void processFiles(List<Path> files) {
        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

        for (Path path : files) {
            executor.execute(() -> {
                try {
                    String hashValue = getMD5ChecksumHex(path);
                    cache.put(path.toString(), hashValue);

                } catch (Exception e) {
                    logger.log(Level.SEVERE, "Failed to process file: " + path, e);
                }
            });
        }

        executor.shutdown();

        try {
            if (!executor.awaitTermination(60, TimeUnit.MINUTES)) {
                List<Runnable> unfinishedTasks = executor.shutdownNow();
                logger.log(Level.SEVERE, "Forcing tasks to stop: " + unfinishedTasks);
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}
```
Please note that the real implementation requires more work on error handling and logging details due to limitations of this platform. This code does not interact with external distributed cache service, since it's impossible to simulate such interaction in a text-based environment. The performance optimization (like batch requests) is also out of scope as it highly depends on the nature of the actual cache system used.
