['Here is an implementation that meets the requirements using C with POSIX threads (pthreads) and a simple linked list to hold UE contexts. A complete solution would require an external message broker integration which was not included in this example due to complexity, but you can integrate it as per your requirement. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>

typedef struct rrc_message {
    int id;
    char* data; 
    time_t timestamp;
} RRCMessage;

typedef struct UEContext {
    pthread_mutex_t lock;  // for concurrency control
    int uniqueID;         // unique UE identifier
    RRCMessage* rrcMsgs;   // linked list of associated RRC messages
    time_t lastActivityTime;  // inactivity timer
} UEContext;

// global head pointer
UEContext* head = NULL;
pthread_mutex_t globalLock = PTHREAD_MUTEX_INITIALIZER;

UEContext* createContext(int id) {
    UEContext* ctx = (UEContext*) malloc(sizeof(UEContext));
    if(!ctx) return NULL; // handle error

    pthread_mutex_init(&ctx->lock, NULL); 
    ctx->uniqueID = id;
    ctx->rrcMsgs = NULL;  
    ctx->lastActivityTime = time(NULL);
    return ctx;
}

int addContext(int uniqueId) {
    pthread_mutex_lock(&globalLock); // lock global list for thread safety

    UEContext* newCtx = createContext(uniqueId); 
    if(!newCtx){
        pthread_mutex_unlock(&globalLock);
        return -1; // handle error
    }
    newCtx->next = head;
    head = newCtx;

    pthread_mutex_unlock(&globalLock); 
    return 0; // success
}

int removeContext(int uniqueId) {
    pthread_mutex_lock(&globalLock); 

    UEContext* ctx = head, *prev = NULL;
    while (ctx != NULL && ctx->uniqueID != uniqueId) {
        prev = ctx;
        ctx = ctx->next;
    }

    if(ctx == NULL){
        pthread_mutex_unlock(&globalLock); 
        return -1; // context not found
    }

    // remove from list
    if (prev != NULL) prev->next = ctx->next;
    else head = ctx->next;  

    pthread_mutex_destroy(&ctx->lock); // destroy the lock
    free(ctx); 

    pthread_mutex_unlock(&globalLock); 
    return 0; // success
}
```

Please note that this is just a simple skeleton and does not handle all edge cases, API version mismatches or external message broker integration etc. Also, for the logging mechanism, you may consider using syslog or some other standard library to log events to files. For external data sources like message broker, an asynchronous approach (callbacks) should be used which is beyond the scope of this example. 
