["Below is a simple implementation using `pthread` to ensure thread-safety:
```c
#include <stdlib.h>
#include <string.h>
#include <stdatomic.h>
#include <pthread.h>

typedef struct PHY_TEST_RX_PDU { /* ... */ } PHY_TEST_RX_PDU;
typedef struct PHY_TEST_TX_PDU { /* ... */ } PHY_TEST_TX_PDU;
typedef struct PHY_TEST_UL_CQI_PDU { /* ... */ } PHY_TEST_UL_CQI_PDU;
typedef union PHY_TEST_PDU { 
    PHY_TEST_RX_PDU rx;
    PHY_TEST_TX_PDU tx;
    PHY_TEST_UL_CQI_PDU ulcqi;
} PHY_TEST_PDU;

typedef struct DynamicArray {
    atomic_size_t size;
    pthread_mutex_t lock;
    union PHY_TEST_PDU** data;
} DynamicArray;

DynamicArray* createDynArray() {
    DynamicArray* arr = malloc(sizeof(DynamicArray));
    if (arr == NULL) return NULL;
    atomic_init(&arr->size, 0);
    pthread_mutex_init(&arr->lock, NULL);
    arr->data = NULL;
    return arr;
}

void destroyDynArray(DynamicArray* arr) {
    for (size_t i = 0; i < atomic_load(&arr->size); ++i)
        free(arr->data[i]);
    free(arr->data);
    pthread_mutex_destroy(&arr->lock);
    free(arr);
}

int addElement(DynamicArray* arr, PHY_TEST_PDU* element) {
    if (element == NULL) return -1; // invalid input
    pthread_mutex_lock(&arr->lock);
    size_t newSize = atomic_fetch_add(&arr->size, 1) + 1;
    arr->data = realloc(arr->data, sizeof(*arr->data) * newSize);
    if (arr->data == NULL) { // memory allocation failure
        pthread_mutex_unlock(&arr->lock);
        return -2;
    }
    arr->data[newSize - 1] = element;
    pthread_mutex_unlock(&arr->lock);
    return 0; // success
}
```
In this code, `DynamicArray` is a structure that represents a dynamic array of `PHY_TEST_PDU` structures. The array's size (number of elements it contains) and the actual data are stored in the structure. Thread safety is ensured by locking access to the array with a mutex whenever an operation on it is performed.

This code does not include functionality for removing or accessing elements from the array, as such operations would require additional complexity (e.g., handling of resizing when elements are removed). In production code, you might also want to add error checking in more places, and possibly use different locking primitives depending on your specific requirements.
