['Here is a simple implementation of your requirements using C language and pthread library for synchronization. Note that this is just a skeleton code to give an idea on how you might implement it. Detailed code would depend upon specific use case, error handling strategy, and other factors. 

```c
#include <stdio.h>
#include <pthread.h>
#include <unistd.h>
#include <stdlib.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RNTI;
    /* other fields */
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} Node;

Node *head = NULL;
pthread_mutex_t lock;
int validRNTI[2]; // Range of RNTIs 

void initList(int min, int max) {
    pthread_mutex_init(&lock, NULL);
    validRNTI[0] = min;
    validRNTI[1] = max;
}

Node* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node *newNode = (Node*)malloc(sizeof(Node));
    if(!newNode) return NULL;

    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

void addNode(NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&lock);
    Node *newNode = createNode(data);

    if(!head) {
        head = newNode;
    } else {
        Node *cur = head;
        while(cur->next != NULL){ 
            cur = cur->next;
        }
        cur->next = newNode;
    }
    pthread_mutex_unlock(&lock);
}

NFAPI_CRC_INDICATION_PDU_T* getNode(int RNTI) {
    pthread_mutex_lock(&lock);
    Node *cur = head;
    while(cur != NULL){
        if(cur->data.RNTI == RNTI) {
            pthread_mutex_unlock(&lock);
            return &(cur->data);
        }
        cur = cur->next;
    }
    pthread_mutex_unlock(&lock);
    return NULL;
}

void updateNode(NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&lock);
    Node *cur = head;
    while(cur != NULL){
        if(cur->data.RNTI == data.RNTI) {
            cur->data = data;
            break;
        }
        cur = cur->next;
    }
    pthread_mutex_unlock(&lock);
}

void cleanup() {
    Node *cur,*tmp;
    pthread_mutex_lock(&lock);
    cur = head;
    while(cur != NULL){
        tmp = cur->next;
        free(cur);
        cur = tmp;
    }

    head = NULL;
    pthread_mutex_unlock(&lock);
}
```
This code creates a simple linked list of `NFAPI_CRC_INDICATION_PDU_T` structures and provides basic operations for adding, updating and getting nodes. It uses mutex locking to ensure thread-safe access to the data structure. For more complex operations such as hash map or tree structure you need to modify this code accordingly. Also, make sure to check `RNTI` against valid range before performing any operation on list.
']

