typedef struct BufferMonitor {
    size_t currentSize;
    size_t maxSize;
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T* data;
} BufferMonitor;

void bufferMonitorInit(BufferMonitor* monitor, size_t initialSize) {
    monitor->currentSize = 0;
    monitor->maxSize = initialSize;
    pthread_mutex_init(&monitor->lock, NULL);
    monitor->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initialSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void bufferMonitorAdd(BufferMonitor* monitor, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&monitor->lock);

    if (monitor->currentSize == monitor->maxSize) {
        // Reallocate buffer with double the size when it's full
        monitor->data = realloc(monitor->data, monitor->maxSize * 2 * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (monitor->data == NULL) {
            // Handle allocation failure
            printf("Failed to allocate buffer\n");
            pthread_mutex_unlock(&monitor->lock);
            return;
        }

        monitor->maxSize *= 2;
    }

    monitor->data[monitor->currentSize++] = data;

    pthread_mutex_unlock(&monitor->lock);
}
```
