#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>
#include <netinet/in.h>

typedef struct {
    int socket_fd;
    char* ip_address;
    int port;
    time_t last_activity;
} ConnectionRecord;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
ConnectionRecord* connection_records[MAX_CONNECTIONS];
int num_connections = 0;

void add_connection(int socket_fd, char* ip_address, int port) {
    pthread_mutex_lock(&lock);

    ConnectionRecord* record = malloc(sizeof(ConnectionRecord));
    record->socket_fd = socket_fd;
    record->ip_address = strdup(ip_address);
    record->port = port;
    record->last_activity = time(NULL);

    connection_records[num_connections++] = record;

    pthread_mutex_unlock(&lock);
}

void remove_connection(int socket_fd) {
    pthread_mutex_lock(&lock);

    // Find and remove the connection with the given socket file descriptor
    for (int i = 0; i < num_connections; i++) {
        if (connection_records[i]->socket_fd == socket_fd) {
            free(connection_records[i]);

            // Move the last record to this position and decrement the number of connections
            connection_records[i] = connection_records[--num_connections];
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}

ConnectionRecord* get_connection(int socket_fd) {
    ConnectionRecord* result = NULL;

    pthread_mutex_lock(&lock);

    // Find the connection with the given socket file descriptor
    for (int i = 0; i < num_connections; i++) {
        if (connection_records[i]->socket_fd == socket_fd) {
            result = connection_records[i];
            break;
        }
    }

    pthread_mutex_unlock(&lock);

    return result;
}
``` 

