["Here's a simple example of how you might implement this using a doubly linked list protected by a mutex for thread safety, along with a condition variable to signal when an element is added or removed from the list. The cleanup process simply iterates over the list and removes entries older than a specified age threshold.

```c
#include <pthread.h>
#include <stdlib.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Assume you have defined these structures elsewhere.
} NFAPI_CRC_INDICATION_PDU_T;

// Structure for doubly linked list node
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T* data;
    time_t timestamp; // Keep track of the insertion time.
    struct Node* prev;
    struct Node* next;
} Node;

// Structure for doubly linked list with mutex and condition variable
typedef struct List {
    Node* head;
    Node* tail;
    size_t size; // Keep track of the current number of nodes.
    size_t maxSize; // Maximum allowed size.
    time_t ageThreshold; // Age threshold for cleanup.
    pthread_mutex_t lock;
    pthread_cond_t condition;
} List;

List* createList(size_t maxSize, time_t ageThreshold) {
    List* list = malloc(sizeof(List));
    if (list == NULL) return NULL; // Memory allocation failed.

    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    list->maxSize = maxSize;
    list->ageThreshold = ageThreshold;
    pthread_mutex_init(&list->lock, NULL); // Initialize the mutex.
    pthread_cond_init(&list->condition, NULL); // Initialize the condition variable.

    return list;
}

void destroyList(List* list) {
    Node* node = list->head;
    while (node != NULL) {
        Node* next = node->next;
        free(node); // Free each node.
        node = next;
    }

    pthread_mutex_destroy(&list->lock); // Destroy the mutex.
    pthread_cond_destroy(&list->condition); // Destroy the condition variable.
    free(list); // Free the list structure itself.
}

// Adds a new element to the end of the list, ensuring it is not already in the list and there's room for it.
int addToList(List* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* node = malloc(sizeof(Node));
    if (node == NULL) return -1; // Memory allocation failed.

    pthread_mutex_lock(&list->lock); // Lock the list for thread safety.

    // Check whether there's room in the list and the element is not already in it.
    if (list->size >= list->maxSize || findNode(list, data) != NULL) {
        pthread_mutex_unlock(&list->lock); // Unlock before returning to avoid deadlock.
        free(node); // Free the node as it's not needed if we can't add it to the list.
        return -1;
    }

    node->data = data;
    node->prev = NULL;
    node->next = NULL;
    time(&node->timestamp); // Set the insertion timestamp.

    if (list->tail == NULL) { // If list is empty, make node both head and tail.
        list->head = node;
        list->tail = node;
    } else { // Otherwise, append to end of list.
        node->prev = list->tail;
        list->tail->next = node;
        list->tail = node;
    }

    list->size++;
    pthread_cond_signal(&list->condition); // Signal that a new element was added.

    cleanupList(list); // Clean up old entries before unlocking to avoid unnecessary waiting.

    pthread_mutex_unlock(&list->lock); // Unlock the list after modifying it.

    return 0;
}

// Searches for a node in the list by comparing its data with the given element.
Node* findNode(List* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* node = list->head;
    while (node != NULL && compareData(data, node->data) != 0) node = node->next; // Iterate over the list.

    return node; // Return either the found node or NULL if not found.
}

// Compares two elements to see if they are equal (should be defined elsewhere).
int compareData(NFAPI_CRC_INDICATION_PDU_T* data1, NFAPI_CRC_INDICATION_PDU_T* data2) {
    // Implement your comparison logic here.
}

// Removes nodes from the list that are older than the specified age threshold.
void cleanupList(List* list) {
    pthread_mutex_lock(&list->lock); // Lock the list before modifying it.

    Node* node = list->head;
    while (node != NULL && time(NULL) - node->timestamp >= list->ageThreshold) { // Iterate over the list.
        if (list->size > 1) { // If there's more than one node, adjust head and tail pointers as needed.
            if (node == list->head) {
                list->head = node->next;
                list->head->prev = NULL;
            } else if (node == list->tail) {
                list->tail = node->prev;
                list->tail->next = NULL;
            } else { // Node is in the middle of the list.
                node->prev->next = node->next;
                node->next->prev = node->prev;
            }
        } else { // If there's only one node, just clear the head and tail pointers.
            list->head = NULL;
            list->tail = NULL;
        }

        free(node); // Free the node as it's no longer needed.
        list->size--;
    }

    pthread_mutex_unlock(&list->lock); // Unlock the list after modifying it.
}
```
