    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) {
        errorLog("Memory allocation failed");
        return NULL;
    }

    array->statsArray = NULL;
    array->count = 0;

    if (pthread_mutex_init(&(array->mutex), NULL) != 0) {
        errorLog("Mutex initialization failed");
        free(array);
        return NULL;
    }

    return array;
}

int addStatsToArray(DynamicArray* array, UplinkTrafficStats* stats) {
    if (pthread_mutex_lock(&(array->mutex)) != 0) {
        errorLog("Failed to lock mutex");
        return -1;
    }

    // Enlarge the array by one and assign stats to the new slot.
    array->statsArray = realloc(array->statsArray, sizeof(UplinkTrafficStats*) * (array->count + 1));
    if (!array->statsArray) {
        errorLog("Memory allocation failed");
        pthread_mutex_unlock(&(array->mutex)); // Ensure mutex is unlocked before returning.
        return -1;
    }

    array->statsArray[array->count] = stats;
    (array->count)++;

    pthread_mutex_unlock(&(array->mutex)); // Unlock mutex after data is safely updated.
    return 0;
}

