    if (pthread_mutex_lock(&(array->mutex)) != 0) {
        errorLog("Failed to lock mutex");
        return NULL;
    }

    for (int i = 0; i < array->count; i++) {
        if (strcmp(array->statsArray[i]->UE_id, UEId) == 0) {
            UplinkTrafficStats* stats = array->statsArray[i]; // Copy the stats before unlocking mutex.
            pthread_mutex_unlock(&(array->mutex)); 
            return stats;
        }
    }

    pthread_mutex_unlock(&(array->mutex)); 
    errorLog("No stats found for the given UE ID");
    return NULL;
}
