typedef struct {
    // Add fields here...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t size;
    NFAPI_CRC_INDICATION_PDU_T *elements;
} DynamicArray;

DynamicArray* createDynamicArray(size_t initialCapacity) {
    DynamicArray *array = malloc(sizeof(DynamicArray));
    if (array == NULL || pthread_mutex_init(&array->lock, NULL) != 0) {
        free(array);
        return NULL; // Failed to allocate memory or initialize mutex.
    }

    array->capacity = initialCapacity;
    array->size = 0;
    array->elements = calloc(initialCapacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array->elements == NULL) {
        pthread_mutex_destroy(&array->lock);
        free(array);
        return NULL; // Failed to allocate memory for elements.
    }

    return array;
}

void destroyDynamicArray(DynamicArray *array) {
    if (array == NULL) {
        return;
    }

    pthread_mutex_lock(&array->lock);
    free(array->elements);
    pthread_mutex_unlock(&array->lock);

    pthread_mutex_destroy(&array->lock);
    free(array);
}

int addElementToArray(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T element) {
    if (array == NULL) {
        return -1; // Invalid array.
    }

    pthread_mutex_lock(&array->lock);
    if (array->size >= array->capacity) {
        size_t newCapacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* newElements = realloc(array->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T) * newCapacity);
        if (newElements == NULL) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Failed to allocate memory.
        }

        array->capacity = newCapacity;
        array->elements = newElements;
    }

    array->elements[array->size++] = element;
    pthread_mutex_unlock(&array->lock);

    return 0; // Success.
}
```
This function uses a dynamically allocated array to store elements, which allows it to handle an arbitrary number of elements without needing to know the maximum possible size at compile time. The `pthread_mutex_t` structure is used for mutual exclusion and thread-safety, ensuring that only one thread can modify the dynamic array at a time. This approach should provide satisfactory performance under typical load conditions, but may be slower in cases where contention for the lock is high.

The `realloc()` function is used to resize the array when it becomes full, which minimizes memory usage and avoids reallocation on every addition. However, this can result in a significant slowdown if many elements are added consecutively without the array being resized. This could be mitigated by using an exponential growth strategy or similar method to minimize reallocations.
