#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_FRAMES 1024
#define HEADER_SIZE 64
#define PAYLOAD_SIZE 512

typedef struct {
    // MAC header fields
} MAC_HEADER;

typedef struct {
    // MAC payload fields
} MAC_PAYLOAD;

typedef struct {
    MAC_HEADER header;
    MAC_PAYLOAD payload;
} MAC_FRAME;

typedef struct {
    MAC_FRAME *frames;
    size_t count;
    pthread_mutex_t mutex;
} ConfigStructure;

int initConfig(size_t frameCount) {
    if (frameCount > MAX_FRAMES) {
        fprintf(stderr, "Frame count exceeds maximum limit\n");
        return -1;
    }

    // Dynamically allocating memory for ConfigStructure
    ConfigStructure *config = malloc(sizeof(ConfigStructure));
    if (config == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    // Initializing the mutex for thread-safety
    pthread_mutex_init(&config->mutex, NULL);

    config->frames = malloc(sizeof(MAC_FRAME) * frameCount);
    if (config->frames == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_destroy(&config->mutex);
        free(config);
        return -1;
    }

    config->count = frameCount;

    // Initialize MAC_FRAME structures
    for (size_t i = 0; i < frameCount; ++i) {
        initFrame(&config->frames[i]);
    }

    return 0;
}

void addFrame(ConfigStructure *config, const MAC_FRAME *frame) {
    // Acquiring the lock for thread safety
    pthread_mutex_lock(&config->mutex);

    if (config->count < MAX_FRAMES) {
        config->frames[config->count++] = *frame;
    } else {
        fprintf(stderr, "Max frame limit reached\n");
    }

    // Releasing the lock after operation
    pthread_mutex_unlock(&config->mutex);
}

void deinitConfig(ConfigStructure *config) {
    // Destroying the mutex before freeing memory to avoid potential race condition
    pthread_mutex_destroy(&config->mutex);

    // Deallocating memory for frames and config
    free(config->frames);
    free(config);
}
```
