['Sure, here's a simple implementation using Java 8 Streams API with Apache Commons IOUtils for reading large chunks of data from an InputStream. In this case, we are just logging hashes and processing times. To save in external storage, you may need to use your own persistence layer or libraries like JPA/Hibernate, Spring Data, etc:

```java
import org.apache.commons.codec.digest.DigestUtils;
import org.apache.commons.io.IOUtils;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.security.NoSuchAlgorithmException;
import java.time.Duration;
import java.time.Instant;
import java.util.Arrays;
import java.util.Base64;

public class LargeStreamProcessor {
    private static final int CHUNK_SIZE = 1024 * 1024; // 1 MB

    public void process(InputStream input) throws IOException, NoSuchAlgorithmException {
        byte[] buffer = new byte[CHUNK_SIZE];

        try (ByteArrayOutputStream outputStream = new ByteArrayOutputStream()) {
            int bytesRead;
            while ((bytesRead = input.read(buffer)) != -1) {
                if (bytesRead < buffer.length && outputStream.size() > 0) {
                    // If the last chunk is not full, write it to disk and process it
                    byte[] truncatedBuffer = Arrays.copyOfRange(buffer, 0, bytesRead);
                    Instant startTime = Instant.now();
                    String hash = DigestUtils.md5Hex(truncatedBuffer).substring(0,16);
                    Duration processingTime = Duration.between(startTime, Instant.now());

                    System.out.println("Hash: " + hash + ", Processing time: " + processingTime.toMillis() + "ms");
                } else {
                    // If the last chunk is full or it's the first one, process it directly
                    Instant startTime = Instant.now();
                    String hash = DigestUtils.md5Hex(buffer).substring(0,16);
                    Duration processingTime = Duration.between(startTime, Instant.now());

                    System.out.println("Hash: " + hash + ", Processing time: " + processingTime.toMillis() + "ms");
                }
            }
        } catch (IOException e) {
            // Handle IO exceptions
            throw new IOException("Error processing stream", e);
        } catch (NoSuchAlgorithmException e) {
            // Handle MD5 hash calculation exception
            throw new NoSuchAlgorithmException("Error calculating MD5 hash");
        }
    }
}
```
Please note that this implementation doesn't handle interruptions or resuming from last chunk. This is a complex task and depends on your specific use case. For handling interruptions, you might want to use an ExecutorService with a shutdown hook that can be invoked when the JVM shuts down unexpectedly. To resume processing from last chunk, you may need to store the offset of the last processed byte or implement some kind of checkpointing mechanism.

