    ListNode *head;
    pthread_mutex_t mutex;
    size_t totalMemoryUsed;
    const size_t maxMemoryLimit;
} CrcList;

int initCrcList(CrcList *list, size_t maxMemory) {
    if (pthread_mutex_init(&list->mutex, NULL) != 0) return 1;
    list->head = NULL;
    list->totalMemoryUsed = 0;
    list->maxMemoryLimit = maxMemory;
    return 0;
}

int addToCrcList(CrcList *list, NFAPI_CRC_INDICATION_PDU_T *data) {
    pthread_mutex_lock(&list->mutex);

    // Check memory limit before allocation
    if (list->totalMemoryUsed + sizeof(ListNode) > list->maxMemoryLimit) {
        pthread_mutex_unlock(&list->mutex);
        return 1;  // Return failure, out of memory
    }

    ListNode *node = malloc(sizeof(ListNode));
    if (node == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return 2;  // Return failure, unable to allocate memory for node
    }

    // Add data to new node and add it to the list
    node->data = data;
    node->next = list->head;
    list->head = node;

    list->totalMemoryUsed += sizeof(ListNode);

    pthread_mutex_unlock(&list->mutex);

    return 0;  // Return success
}
