typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct Node *next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int maxSize = 1000; // Max size of the list
Node *head = NULL;
int size = 0;

// Function to create a new node and append it to the list.
void add(NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&lock);

    // Validate RNTI values here...

    Node *newNode = (Node*) malloc(sizeof(Node));
    if(!newNode) {
        // Log out-of-memory condition...
        return;
    }
    newNode->data = data;
    newNode->next = NULL;

    if(head == NULL) {
        head = newNode;
    } else {
        Node *temp = head;
        while(temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }

    size++;
    if(size > maxSize){
        // Delete the first node in list and log deletion...
        Node *temp = head;
        head = head->next;
        free(temp);
        size--;
    }

    pthread_mutex_unlock(&lock);
}
```

