    /* Define your packet header structure */
} PacketHeader;

typedef struct {
    /* Define your payload structure */
} Payload;

typedef struct {
    PacketHeader header;
    Payload* payload;
    _Atomic(uint32_t) refCount;
    pthread_mutex_t lock;
} Packet;

Packet* allocatePacket() {
    Packet* packet = malloc(sizeof(Packet));
    if (!packet) return NULL;

    /* Initialize your packet */
    atomic_init(&packet->refCount, 1);
    pthread_mutex_init(&packet->lock, NULL);
    return packet;
}

void retainPacket(Packet* packet) {
    if (packet) {
        pthread_mutex_lock(&packet->lock);
        atomic_fetch_add_explicit(&packet->refCount, 1, memory_order_relaxed);
        pthread_mutex_unlock(&packet->lock);
    }
}

void releasePacket(Packet* packet) {
    if (packet) {
        pthread_mutex_lock(&packet->lock);
        if (atomic_fetch_sub_explicit(&packet->refCount, 1, memory_order_acquire) == 1) {
            /* Report packet loss or errors here */

            pthread_mutex_unlock(&packet->lock);
            free(packet);
        } else {
            pthread_mutex_unlock(&packet->lock);
        }
    }
}
```
