// A global queue that is protected by a lock
QUEUE_ITEM_T *queue = NULL;
pthread_mutex_t queueLock = PTHREAD_MUTEX_INITIALIZER;

int enQueue(void *data) {
    QUEUE_ITEM_T *item = malloc(sizeof(QUEUE_ITEM_T));
    if (item == NULL) return -1; // out of memory error

    item->data = data;
    item->next = NULL;

    pthread_mutex_lock(&queueLock);
    if (queue == NULL) {
        queue = item;
    } else {
        QUEUE_ITEM_T *temp = queue;
        while(temp->next != NULL) temp = temp->next;
        temp->next = item;
    }
    pthread_mutex_unlock(&queueLock);

    return 0; // success
}

void* deQueue() {
    pthread_mutex_lock(&queueLock);
    if (queue == NULL) {
        pthread_mutex_unlock(&queueLock);
        return NULL; // queue is empty
    } else {
        void *data = queue->data;

        QUEUE_ITEM_T *temp = queue;
        queue = queue->next;
        free(temp);

        pthread_mutex_unlock(&queueLock);
        return data; // success, returns the first item's data
    }
}
```
