    manager->count = 0;
    atomic_init(&manager->totalCount, 0);
    manager->array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T)*initialSize);
    pthread_rwlock_init(&manager->lock, NULL);
}

void addElement(struct ArrayManager *manager, NFAPI_CRC_INDICATION_PDU_T element) {
    if (element.RNTI > manager->count) {
        return;
    }

    pthread_rwlock_wrlock(&manager->lock);

    manager->array[element.RNTI] = element;
    atomic_fetch_add(&manager->totalCount, 1);

    pthread_rwlock_unlock(&manager->lock);
}

NFAPI_CRC_INDICATION_PDU_T getElement(struct ArrayManager *manager, unsigned RNTI) {
    NFAPI_CRC_INDICATION_PDU_T element;

    pthread_rwlock_rdlock(&manager->lock);

    if (RNTI < manager->count) {
        element = manager->array[RNTI];
    } else {
        // handle error
    }

    pthread_rwlock_unlock(&manager->lock);

    return element;
}

void updateElement(struct ArrayManager *manager, NFAPI_CRC_INDICATION_PDU_T newValue) {
    if (newValue.RNTI >= manager->count) {
        return;
    }

    pthread_rwlock_wrlock(&manager->lock);

    manager->array[newValue.RNTI] = newValue;

    pthread_rwlock_unlock(&manager->lock);
}

void deleteElement(struct ArrayManager *manager, unsigned RNTI) {
    if (RNTI >= manager->count) {
        return;
    }

    pthread_rwlock_wrlock(&manager->lock);

    // shift elements forward to fill the gap
    for(int i = RNTI; i < manager->count - 1; ++i) {
        manager->array[i] = manager->array[i + 1];
    }

    atomic_fetch_sub(&manager->totalCount, 1);
    --manager->count;

    pthread_rwlock_unlock(&manager->lock);
}
