```java
import java.security.*;
import java.util.*;
import org.apache.commons.codec.digest.*;
import com.google.common.cache.*;
import org.slf4j.*;

public class MD5HashService {
    private static final int MAX_LENGTH = 1024;
    private LoadingCache<String, String> cache;
    private Logger logger = LoggerFactory.getLogger(MD5HashService.class);

    public MD5HashService() {
        this(true); // Enable caching by default
    }

    public MD5HashService(boolean enableCaching) {
        if (enableCaching) {
            cache = CacheBuilder.newBuilder().maximumSize(10_000).build(new CacheLoader<String, String>() {
                @Override 
                public String load(String input) throws Exception {
                    return DigestUtils.md5Hex(input);
                }});
        } else {
            cache = null; // Disable caching
        }
    }

    public String hash(String input) {
        if (input == null || input.length() > MAX_LENGTH) {
            String errMsg = "Invalid input: " + input;
            logger.error(errMsg);
            throw new IllegalArgumentException(errMsg);
        }

        try {
            if (cache != null && cache.asMap().containsKey(input)) {
                return cache.get(input); // Retrieve from cache
            } else {
                String hash = DigestUtils.md5Hex(input); // Compute hash

                if (cache != null) {
                    cache.put(input, hash); // Cache the result
                }

                return hash;
            }
        } catch (Exception e) {
            logger.error("Failed to compute hash for input: " + input, e);
            throw new RuntimeException("Failed to compute hash", e);
        }
    }
}
```
