typedef struct Queue {
    NFAPI_CRC_INDICATION_PDU_T** buffer;
    int head;
    int tail;
    int size;  // Maximum number of elements in the queue
    pthread_mutex_t mutex;
    pthread_cond_t can_produce, can_consume;
} Queue;

void init(Queue* q, int n) {
    q->buffer = (NFAPI_CRC_INDICATION_PDU_T**)calloc(n, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    q->head = 0;
    q->tail = 0;
    q->size = n;
    pthread_mutex_init(&q->mutex, NULL);
    pthread_cond_init(&q->can_produce, NULL);
    pthread_cond_init(&q->can_consume, NULL);
}

void enqueue(Queue* q, NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&q->mutex);

    while((q->tail + 1) % q->size == q->head) {  // Queue is full
        printf("Warning: queue is full. Waiting for consumers...\n");
        pthread_cond_wait(&q->can_produce, &q->mutex);
    }

    q->buffer[q->tail] = data;
    q->tail = (q->tail + 1) % q->size;

    pthread_cond_signal(&q->can_consume);  // Wake up any sleeping consumers
    pthread_mutex_unlock(&q->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* dequeue(Queue* q) {
    pthread_mutex_lock(&q->mutex);

    while(q->tail == q->head) {  // Queue is empty
        printf("Warning: queue is empty. Waiting for producers...\n");
        pthread_cond_wait(&q->can_consume, &q->mutex);
    }

    NFAPI_CRC_INDICATION_PDU_T* result = q->buffer[q->head];
    q->head = (q->head + 1) % q->size;

    pthread_cond_signal(&q->can_produce);  // Wake up any sleeping producers
    pthread_mutex_unlock(&q->mutex);

    return result;
}
```
Please remember to manage memory (allocate/deallocate) for each NFAPI_CRC_INDICATION_PDU_T when enqueuing and dequeuing. This is a basic example, you might need to add more functionalities such as error handling and data validation according to your requirements.
