    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    pthread_mutex_init(&pdulist.lock, &attr);
}

// Function to add a new PDU structure into the list
int addPdu(UDT_DATA_PDU_T* pdu) {
