    // Apply lock to prevent concurrent access from multiple threads
    pthread_once(&once, initList);
    pthread_mutex_lock(&pdulist.lock);

    if(pdulist.count < MAX_PDU) {
        pdulist.pdu[pdulist.count] = malloc(sizeof(UDT_DATA_PDU_T));

        // Deep copy of PDU data to prevent memory leaks or corruption
        *pdulist.pdu[pdulist.count] = *pdu;
        pdulist.count++;
    } else {
        return -1; // List is full
    }

    pthread_mutex_unlock(&pdulist.lock);
    return 0;
}

// Function to retrieve the last added PDU structure
UDT_DATA_PDU_T* getLastPdu() {
    pthread_once(&once, initList);
    pthread_mutex_lock(&pdulist.lock);

    if(pdulist.count > 0) {
        return pdulist.pdu[pdulist.count-1];
    } else {
        return NULL; // No PDU in the list
    }

    pthread_mutex_unlock(&pdulist.lock);
}
