void addElement(int UE_ID, int RB_ID, double RX_POWER_LEVEL) {
    for (int i = 0; i < size; ++i) {
        if (array[i].UE_ID == UE_ID) {
            array[i].RX_POWER_LEVEL = RX_POWER_LEVEL;
            return;
        }
    }
    ++size;
    array = realloc(array, size * sizeof(PHY_RX_STATS_T));
    if (!array) {
        --size;
        fprintf(stderr, "Error allocating memory for new element.\n");
        return;
    }

    array[size-1].UE_ID = UE_ID;
    array[size-1].RB_ID = RB_ID;
    array[size-1].RX_POWER_LEVEL = RX_POWER_LEVEL;
}

PHY_RX_STATS_T* getElement(int UE_ID) {
    for (int i = 0; i < size; ++i) {
        if (array[i].UE_ID == UE_ID) {
            return &array[i];
        }
    }
    fprintf(stderr, "Element not found.\n");
    return NULL;
}
