pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

LTEPHY_PHY_RX_FRAME_INFO_T* initializeFrames(int num_frames, int *num_symbols) {
    pthread_mutex_lock(&mutex);  // Lock for thread safety

    LTEPHY_PHY_RX_FRAME_INFO_T* frames = (LTEPHY_PHY_RX_FRAME_INFO_T*)malloc(sizeof(LTEPHY_PHY_RX_FRAME_INFO_T) * num_frames);
    if (!frames) {
        pthread_mutex_unlock(&mutex);  // Unlock on failure
        return NULL;
    }

    for (int i = 0; i < num_frames; ++i) {
        frames[i].RX_UE_INFORMATION_TAG = i;  // Assign valid values to fields
        frames[i].RNTI = i;

        LTEPHY_PHY_RX_SYMBOL_INFO_T* symbols = (LTEPHY_PHY_RX_SYMBOL_INFO_T*)malloc(sizeof(LTEPHY_PHY_RX_SYMBOL_INFO_T) * num_symbols[i]);
        if (!symbols) {  // If memory allocation fails, free all previously allocated memory and return NULL
            for (int j = 0; j < i; ++j) {
                free(frames[j].symbols);
            }
            free(frames);

            pthread_mutex_unlock(&mutex);  // Unlock on failure
            return NULL;
        }

        frames[i].symbols = symbols;
    }

    pthread_mutex_unlock(&mutex);  // Release lock after successful initialization
    return frames;
}
