            randomValue = UnityEngine.Random.Range(min, max + 1);
        } while (generatedValues.Contains(randomValue));
        lock (lockObject)
        {
            generatedValues.Add(randomValue);
        }
        return randomValue;
    }

    public int GetUniqueInt()
    {
        if ((max - min + 1) <= generatedValues.Count)
            throw new InvalidOperationException("No unique values left in the range.");

        lock (lockObject)
        {
            return GenerateUniqueRandomInt();
        }
    }

    public int GetRandomInt()
    {
        return UnityEngine.Random.Range(min, max + 1);
    }

    public float GetRandomFloat()
    {
        return (float)(UnityEngine.Random.value * (max - min) + min);
    }
}
```

Please note that this is a very basic implementation and does not include thorough testing or additional features such as caching, thread safety handling, resource tracking, scalability considerations, etc. In a production environment, these elements should be considered accordingly.
