pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void addOrUpdateContext(S1MessageType s1MsgType, void *NAS_PDU) {
    pthread_mutex_lock(&mutex);  // Lock for thread safety

    // Check if context already exists
    for (int i = 0; i < numOfContexts; i++) {
        if (memcmp(&contextArray[i].s1MsgType, &s1MsgType, sizeof(S1MessageType)) == 0) {
            // Update existing context
            free(contextArray[i].NAS_PDU);  // Free previous NAS PDU memory
            contextArray[i].NAS_PDU = NAS_PDU;  // Assign new NAS PDU memory

            pthread_mutex_unlock(&mutex);  // Unlock mutex after update
            return;
        }
    }

    // Add new context
    numOfContexts++;
    contextArray = realloc(contextArray, numOfContexts * sizeof(UEContext));  // Reallocate memory for new context

    if (contextArray == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&mutex);  // Unlock mutex after error handling
        return;
    }

    UEContext* newContext = &contextArray[numOfContexts - 1];
    memcpy(&newContext->s1MsgType, &s1MsgType, sizeof(S1MessageType));
    newContext->NAS_PDU = NAS_PDU;

    // Randomly set CRCFLAG
    srand((unsigned int)time(NULL));  // Seed random generator
    NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_indication = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (nfapi_crc_indication == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&mutex);  // Unlock mutex after error handling
        return;
    }

    nfapi_crc_indication->CRCFLAG = rand() % 2 == 0 ? false : true;  // Random boolean value
    newContext->NFAPI_CRC_INDICATION_PDU = atomic_load(&nfapi_crc_indication);  // Store the pointer in an atomic operation

    pthread_mutex_unlock(&mutex);  // Unlock mutex after successful addition or update
}

UEContext* getContext(S1MessageType s1MsgType) {
    pthread_mutex_lock(&mutex);  // Lock for thread safety

    // Search for context
    for (int i = 0; i < numOfContexts; i++) {
        if (memcmp(&contextArray[i].s1MsgType, &s1MsgType, sizeof(S1MessageType)) == 0) {
            pthread_mutex_unlock(&mutex);  // Unlock mutex after retrieval
            return &contextArray[i];
        }
    }

    pthread_mutex_unlock(&mutex);  // Unlock mutex after no context found
    return NULL;
}
