typedef struct {
    pthread_mutex_t lock;
    size_t maxFrames, currentFrameIndex, frameCount;
    RX_UE_INFORMATION_TAG** frames;
} FrameManager;

void initFrameManager(FrameManager* manager, size_t maxFrames) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->maxFrames = maxFrames;
    manager->frames = malloc(sizeof(RX_UE_INFORMATION_TAG*) * maxFrames);
    manager->currentFrameIndex = 0;
    manager->frameCount = 0;
}

void destroyFrameManager(FrameManager* manager) {
    pthread_mutex_destroy(&manager->lock);
    for (size_t i = 0; i < manager->maxFrames; ++i)
        free(manager->frames[i]);
    free(manager->frames);
}

void addFrame(FrameManager* manager, RX_UE_INFORMATION_TAG* frame) {
    pthread_mutex_lock(&manager->lock);

    if (manager->frameCount < manager->maxFrames) {
        manager->frames[manager->currentFrameIndex] = malloc(sizeof(RX_UE_INFORMATION_TAG));
        memcpy(manager->frames[manager->currentFrameIndex], frame, sizeof(RX_UE_INFORMATION_TAG));
    } else { // Replace the oldest frame with a new one.
        free(manager->frames[manager->currentFrameIndex]);
        manager->frames[manager->currentFrameIndex] = malloc(sizeof(RX_UE_INFORMATION_TAG));
        memcpy(manager->frames[manager->currentFrameIndex], frame, sizeof(RX_UE_INFORMATION_TAG));
    }

    manager->currentFrameIndex = (manager->currentFrameIndex + 1) % manager->maxFrames;
    if (manager->frameCount < manager->maxFrames) ++manager->frameCount;

    pthread_mutex_unlock(&manager->lock);
}
