// A buffer pool of fixed-size buffers (DataPackets)
#define BUFFER_POOL_SIZE 1024
typedef struct {
    pthread_mutex_t lock;
    int index;
    DataPacket *packets[BUFFER_POOL_SIZE];
} BufferPool;

// Initialize the buffer pool
void init_buffer_pool(BufferPool *bp) {
    bp->index = 0;
    pthread_mutex_init(&bp->lock, NULL);
}

// Get a packet from the buffer pool with thread-safe operation
DataPacket* get_packet(BufferPool *bp) {
    DataPacket *packet = NULL;

    // Lock to ensure thread safety
    pthread_mutex_lock(&bp->lock);

    if (bp->index < BUFFER_POOL_SIZE) {
        packet = bp->packets[bp->index++];

        // Initialize the data in the packet
        packet->packet_id = 0;
        packet->timestamp = 0;
        packet->payload_size = 0;
        if (packet->payload) {
            free(packet->payload);
            packet->payload = NULL;
        }
    } else {
        // Handle potential overflow here, e.g., log an error message or grow the buffer pool
    }

    pthread_mutex_unlock(&bp->lock);  // Unlock when done

    return packet;
}

// Release a packet back to the buffer pool with thread-safe operation
void release_packet(BufferPool *bp, DataPacket *packet) {
    pthread_mutex_lock(&bp->lock);  // Lock to ensure thread safety

    if (--bp->index >= 0) {
        bp->packets[bp->index] = packet;
    } else {
        ++bp->index;  // Reset the index in case of underflow
    }

    pthread_mutex_unlock(&bp->lock);  // Unlock when done
}
