} AudioConfig;

typedef struct AudioSample {
    time_t timestamp;
    unsigned long id;
    float amplitude;
} AudioSample;

typedef struct CircularBuffer {
    pthread_mutex_t lock;
    AudioSample *buffer;
    size_t capacity, head, tail;
} CircularBuffer;

CircularBuffer* initializeBuffer(size_t capacity) {
    CircularBuffer* buffer = malloc(sizeof(CircularBuffer));
    if (!buffer) return NULL;  // failed to allocate memory

    pthread_mutex_init(&buffer->lock, NULL);
    buffer->capacity = capacity;
    buffer->head = 0;
    buffer->tail = 0;

    buffer->buffer = malloc(sizeof(AudioSample) * capacity);
    if (!buffer->buffer) {
        free(buffer);  // cleanup half-initialized buffer
        return NULL;   // failed to allocate memory
    }

    memset(buffer->buffer, 0, sizeof(AudioSample) * capacity);
    return buffer;
}

void destroyBuffer(CircularBuffer* buffer) {
    if (buffer) {
        pthread_mutex_destroy(&buffer->lock);
        free(buffer->buffer);
        free(buffer);
    }
}

