using Newtonsoft.Json.Converters;
using Newtonsoft.Json.Linq;
using System.Runtime.Caching;
using System.Net.Http;
using System.Collections.Generic;
using Microsoft.Extensions.Logging;

public class MessageDto
{
    public string UserId { get; set; }
    public DateTime Timestamp { get; set; }
}

public interface IMessageProcessor
{
    MessageDto Process(string base64EncodedData);
}

public abstract class BaseMessageProcessor : IMessageProcessor
{
    protected readonly ILogger<BaseMessageProcessor> logger;
    private ObjectCache cache = MemoryCache.Default;
    public BaseMessageProcessor(ILogger<BaseMessageProcessor> logger) {
        this.logger = logger;
    }

    public MessageDto Process(string base64EncodedData)
    {
        var cacheKey = $"message:{base64EncodedData}";
        if (cache[cacheKey] is MessageDto messageDto) return messageDto;

        var decompressedBytes = Decompress(Convert.FromBase64String(base64EncodedData));
        var jsonText = Encoding.UTF8.GetString(decompressedBytes);
        JObject data = JsonConvert.DeserializeObject<JObject>(jsonText);

        string userId = ExtractUserId(data);
        DateTime timestamp = ExtractTimestamp(data);

        messageDto = new MessageDto { UserId = userId, Timestamp = timestamp };
        CacheItemPolicy policy = new CacheItemPolicy();
        policy.AbsoluteExpiration = DateTimeOffset.Now.AddMinutes(5); // adjust as needed
        cache.Set(cacheKey, messageDto, policy);

        logger.LogInformation($"Processed message for user {userId}");
        return messageDto;
    }

    protected abstract string ExtractUserId(JObject data);
    protected abstract DateTime ExtractTimestamp(JObject data);
    protected abstract byte[] Decompress(byte[] compressedData);
}

public class GzipMessageProcessor : BaseMessageProcessor {
    public GzipMessageProcessor(ILogger<GzipMessageProcessor> logger) : base(logger) {}

    protected override string ExtractUserId(JObject data) => (string)data["user_id"]; // adjust as needed
    protected override DateTime ExtractTimestamp(JObject data) => (DateTime)data["timestamp"]; // adjust as needed

    protected override byte[] Decompress(byte[] compressedData) {
        using (var compressedStream = new MemoryStream(compressedData))
        using (var decompressionStream = new GZipStream(compressedStream, CompressionMode.Decompress))
        using (var resultStream = new MemoryStream()) {
            decompressionStream.CopyTo(resultStream);
            return resultStream.ToArray();
        }
    }
}
``` 

