#include <string.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int PDSCH_RECEIVE_BLOCK_TAG;
} BlockInfo;

typedef struct {
    BlockInfo *data;
    size_t used;
    size_t capacity;
} DynamicArray;

void init(DynamicArray* array, size_t initialSize) {
    array->data = (BlockInfo*)malloc(initialSize * sizeof(BlockInfo));
    array->used = 0;
    array->capacity = initialSize;
}

void insert(DynamicArray* array, BlockInfo element) {
    if (array->used == array->capacity) {
        array->capacity *= 2;
        array->data = (BlockInfo*)realloc(array->data, array->capacity * sizeof(BlockInfo));
    }
    array->data[array->used++] = element;
}

void delete(DynamicArray* array, size_t index) {
    if (index < array->used) {
        memmove(&array->data[index], &array->data[index + 1], (array->used - index - 1) * sizeof(BlockInfo));
        --array->used;
    }
}

void freeArray(DynamicArray* array) {
    free(array->data);
    array->data = NULL;
    array->capacity = 0;
    array->used = 0;
}

int main() {
    DynamicArray arr;
    init(&arr, 2); // Initial capacity of the dynamic array

    BlockInfo block1 = {1, 101, 2001};
    insert(&arr, block1);

    BlockInfo block2 = {2, 102, 2002};
    insert(&arr, block2);

    delete(&arr, 0); // deleting the first element of array

    freeArray(&arr);

    return 0;
}
```
