void add(NFAPI_CRC_INDICATION_PDU_T value) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    memcpy(&newNode->data, &value, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_lock(&listLock);  // Lock to ensure thread safety
    newNode->next = head;
    head = newNode;
    if (count() > max_entries) {  // If maximum size is exceeded, remove last element
        Node* node = head;
        while (node->next->next != NULL) {
            node = node->next;
        }

        free(node->next);
        node->next = NULL;
    }
    pthread_mutex_unlock(&listLock);  // Unlock
}

int count() {
    int c = 0;
    Node* node = head;
    while (node != NULL) {
        c++;
        node = node->next;
    }

    return c;
}
