```c
#include <stdlib.h>
#include <stdatomic.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h> // For usleep() function

typedef struct TrafficFlow {
    char FlowIdentifier[256];
    _Atomic(int) FlowState;
    _Atomic(double) BandwidthRequest;
} TrafficFlow;

// Array of TrafficFlow structures, and associated mutex for thread safety.
TrafficFlow* traffic_flows = NULL;
size_t traffic_flows_len = 0;
pthread_mutex_t traffic_flows_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add or update a TrafficFlow entry.
void set_traffic_flow(const char* flow_id, int flow_state, double bandwidth_request) {
    pthread_mutex_lock(&traffic_flows_lock);

    // Find existing entry if it exists.
    for (size_t i = 0; i < traffic_flows_len; ++i) {
        if (!strcmp(traffic_flows[i].FlowIdentifier, flow_id)) {
            atomic_store(&traffic_flows[i].FlowState, flow_state);
            atomic_store(&traffic_flows[i].BandwidthRequest, bandwidth_request);

            // Release lock and return early.
            pthread_mutex_unlock(&traffic_flows_lock);
            return;
        }
    }

    // If we reach here, this is a new entry. Add it to the array.
    ++traffic_flows_len;
    traffic_flows = realloc(traffic_flows, traffic_flows_len * sizeof(TrafficFlow));
    TrafficFlow* tf = &traffic_flows[traffic_flows_len - 1];

    strncpy(tf->FlowIdentifier, flow_id, sizeof(tf->FlowIdentifier) - 1);
    atomic_init(&tf->FlowState, flow_state);
    atomic_init(&tf->BandwidthRequest, bandwidth_request);

    pthread_mutex_unlock(&traffic_flows_lock);
}

// Function to retrieve a TrafficFlow entry. Returns NULL if not found.
TrafficFlow* get_traffic_flow(const char* flow_id) {
    pthread_mutex_lock(&traffic_flows_lock);

    for (size_t i = 0; i < traffic_flows_len; ++i) {
        if (!strcmp(traffic_flows[i].FlowIdentifier, flow_id)) {
            pthread_mutex_unlock(&traffic_flows_lock);
            return &traffic_flows[i];
        }
    }

    pthread_mutex_unlock(&traffic_flows_lock);
    return NULL;
}
```
Please note that this is a simplified example and real-world code would require more considerations for error handling, memory management, performance optimization, threading model design, communication with external service and other important factors. It's also recommended to use existing library such as `libcurl` or third party services for interfacing with an external traffic management service in a production environment.
