#include <netinet/in.h>
#include <arpa/inet.h>

typedef struct {
    struct in_addr ip;
    int port;
} ConnectionRequestKey;

typedef struct ConnectionRequest {
    time_t timestamp;
    ConnectionRequestKey key;
    struct ConnectionRequest *next;
} ConnectionRequest;

ConnectionRequest* head = NULL;
size_t count = 0;
time_t startTime;
time_t endTime;

int compareKeys(ConnectionRequestKey key1, ConnectionRequestKey key2) {
    return (key1.port == key2.port && key1.ip.s_addr == key2.ip.s_addr);
}

void addNewConnectionRequest(struct in_addr ip, int port) {
    time_t now = time(NULL);
    ++count;
    if (startTime == 0) startTime = now; // set the first request timestamp
    endTime = now; // update last request timestamp

    ConnectionRequest *newRequest = malloc(sizeof(ConnectionRequest));
    newRequest->timestamp = now;
    newRequest->key.ip = ip;
    newRequest->key.port = port;
    newRequest->next = NULL;

    if (head == NULL) {
        head = newRequest;
        return;
    }

    ConnectionRequest *current = head;
    while(current != NULL) { 
        if(compareKeys(newRequest->key, current->key)) {
            free(newRequest); // remove duplicates
            return;
        }
        if (current->next == NULL) break;
        else current = current->next;
    }

    current->next = newRequest; // add new connection request to list
}

void printConnectionCount() {
    printf("Total unique requests processed: %zu\n", count);
}

double calculateTimeDifference() {
    return difftime(endTime, startTime);
}
```
