#include <stdlib.h>
#include <string.h>

typedef struct record {
    long* offset;
    int value;
} Record;

Record* initialize(size_t num_offsets, size_t num_keys, int min_value, int max_value) {
    // Ensure the input parameters are within valid range.
    if (num_offsets < 1 || num_offsets > 1000 || num_keys < 1 || num_keys > 10000 || min_value >= max_value) {
        return NULL;
    }

    // Calculate the total memory needed for all structures.
    size_t total_size = sizeof(long)*num_offsets + sizeof(int)*num_keys + sizeof(Record)*num_offsets;

    // Check if total size exceeds 1MB, return NULL if it does.
    if (total_size > 1024*1024) {
        return NULL;
    }

    // Allocate memory for all structures in a single call to malloc.
    void *memory = malloc(total_size);
    if (memory == NULL) {
        return NULL;
    }

    // Initialize offsets array and keys array within the allocated memory block.
    long* offsets = (long*)memory;
    int* keys = (int*)(offsets + num_offsets);

    // Seed random number generator for value initialization.
    srand(time(NULL));

    // Initialize keys array with random values within the specified range.
    for (size_t i = 0; i < num_keys; ++i) {
        keys[i] = rand() % (max_value - min_value + 1) + min_value;
    }

    // Initialize offsets array with random values within the specified range.
    for (size_t i = 0; i < num_offsets; ++i) {
        long offset = rand() % (max_value - min_value + 1) + min_value;
        offsets[i] = offset;

        // Assign each 'offset' pointer in the records to a corresponding value in the 'offsets' array.
        Record* record = (Record*)(keys + num_keys);
        record[i].offset = &(offsets[i]);
        record[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    // Return the initialized records.
    return (Record*)(keys + num_keys);
}
```

