void addNewEvent(int deviceId, time_t timestamp, char* data) {
    pthread_mutex_lock(&mutex);

    if (eventCount == maxSize) {
        maxSize *= 2; // Double the maximum size when capacity is reached
        events = realloc(events, maxSize * sizeof(NetworkEvent));  // Resize the array

        if (!events) {
            perror("Memory allocation failed");
            pthread_mutex_unlock(&mutex);
            return;
        }
    }

    events[eventCount].device_id = deviceId;
    events[eventCount].timestamp = timestamp;
    events[eventCount].data = data; // Assuming the size of DataPayload is less than maximum
    eventCount++;

    pthread_mutex_unlock(&mutex);
