    *segments = (NFAPI_CRC_INDICATION_PDU_T**)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * MAX_SEGMENTS);

    if (*segments == NULL) return -1; // error handling memory allocation failure

    srand(time(NULL));

