    for (int i = 0; i < MAX_SEGMENTS; ++i) {
        (*segments)[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if ((*segments)[i] == NULL) { // error handling memory allocation failure
            for (int j = 0; j < i; ++j) free((*segments)[j]); 
            return -1; 
        }

        (*segments)[i]->infoTag.RNTI = rand() & RNTI_MASK; // set random RNTI
        rntiSum += (*segments)[i]->infoTag.RNTI;
