#include <pthread.h>

typedef struct {
    int antenna_ports;
    float channel_bandwidth;
    float ref_signal_power;
} LTE_PHY_config;

typedef struct Node{
    LTE_PHY_config data;
    struct Node* next;
}Node;

Node *head = NULL;
pthread_mutex_t lock; 

void init() {
    head = NULL;
    if (pthread_mutex_init(&lock, NULL) != 0) {
        printf("\nMutex initialization failed\n");
        return;
    }
}

int add(LTE_PHY_config new_data) {
    pthread_mutex_lock(&lock);

    Node *newNode = (Node*)malloc(sizeof(Node));
    if(!newNode){
        return -1; // Allocation failed
    }

    newNode->data = new_data;
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
    return 0; // Successful addition
}

int update(LTE_PHY_config new_data) {
    pthread_mutex_lock(&lock);

    Node *temp = head;
    while (temp != NULL) {
        if (memcmp(&(temp->data), &new_data, sizeof(LTE_PHY_config)) == 0){
            temp->data = new_data;
            break; 
        }
        temp = temp->next;
    }

    pthread_mutex_unlock(&lock);
    return 0; // Successful update
}

int delete(LTE_PHY_config data) {
    pthread_mutex_lock(&lock);

    Node *temp = head, *prev = NULL;
    while (temp != NULL && memcmp(&(temp->data), &data, sizeof(LTE_PHY_config)) != 0) {
        prev = temp;
        temp = temp->next;
    }

    if(temp == NULL){
        return -1; // Data not found
    } 

    if (prev != NULL) {
        prev->next = temp->next;
    } else {
        head = temp->next;
    }

    free(temp);
    pthread_mutex_unlock(&lock);
    return 0; // Successful deletion
}
```
The above implementation uses a linked list for maintaining the dynamic array of structures. It provides functions to add, update and delete elements in thread safe manner by using mutex locks. It also compares memory content of two structs to perform update operation which is efficient considering the size of LTE_PHY_config struct.
