typedef struct {
    long* offset;
    int value;
} record;

typedef struct {
    pthread_mutex_t lock;
    size_t num_offsets, num_keys;
    long* offsets;
    int* keys;
    record** records;
} config_data;

config_data* init(size_t num_offsets, size_t num_keys, int min_value, int max_value) {
    if (num_offsets > 1000 || num_keys > 10000 || ((num_offsets * sizeof(long)) + (num_keys * sizeof(int))) > 1048576) return NULL;

    config_data* data = malloc(sizeof(config_data));
    if (!data) return NULL;

    pthread_mutex_init(&data->lock, NULL);
    data->num_offsets = num_offsets;
    data->num_keys = num_keys;

    // Allocate memory for the arrays
    data->offsets = malloc(num_offsets * sizeof(long));
    if (!data->offsets) {
        free(data);
        return NULL;
    }

    data->keys = malloc(num_keys * sizeof(int));
    if (!data->keys) {
        free(data->offsets);
        free(data);
        return NULL;
    }

    // Allocate memory for the records array
    data->records = malloc(num_keys * sizeof(record*));
    if (!data->records) {
        free(data->offsets);
        free(data->keys);
        free(data);
        return NULL;
    }

    // Initialize the records array
    srand(time(NULL));
    for (size_t i = 0; i < num_keys; ++i) {
        data->records[i] = malloc(sizeof(record));
        if (!data->records[i]) {
            // Free all previously allocated records and return NULL if allocation fails
            for (size_t j = 0; j < i; ++j) free(data->records[j]);
            free(data->offsets);
            free(data->keys);
            free(data);
            return NULL;
        }
        data->records[i]->offset = NULL;
        data->records[i]->value = rand() % (max_value - min_value + 1) + min_value;
    }

    return data;
}
