sem_t semaphore;

void add(int rnti, int crcflag) {
    Node *newNode = (Node *)malloc(sizeof(Node));
    newNode->data.RNTI = rnti;
    newNode->data.CRCFLAG = crcflag;
    sem_wait(&semaphore);
    newNode->next = head;
    head = newNode;
    sem_post(&semaphore);
}

void *readFromFile(void *arg) {
    char* filename = (char*) arg;
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("Error while opening the file");
        exit(EXIT_FAILURE);
    }

    char buffer[256];
    ssize_t bytesRead;
    int rnti, crcflag;
    while ((bytesRead = read(fd, buffer, sizeof(buffer) - 1)) > 0) {
        buffer[bytesRead] = 0;

        if (sscanf(buffer, "%d %d", &rnti, &crcflag) == 2 && rnti >= 0 && crcflag >= 0 && rnti <= 65535 && crcflag <= 255) {
            add(rnti, crcflag);
        } else {
            fprintf(stderr, "Invalid data found in the file: %s\n", buffer);
        }
    }

    if (bytesRead == -1) {
        perror("Error while reading from the file");
        exit(EXIT_FAILURE);
    }

    close(fd);
}

void startReadingFromFile(char* filename) {
    pthread_t threadId;
    sem_init(&semaphore, 0, 1);
    pthread_create(&threadId, NULL, readFromFile, (void*)filename);
}
