    while (N > 0){ 
        // Handle cases where the list size exceeds 1024 elements by partitioning into multiple segments.
        int segmentSize = N > MAXSEGMENTSIZE ? MAXSEGMENTSIZE : N;

        *tail = malloc(sizeof(**tail));

        if (*tail == NULL){
