    if (!new_config) return NULL;

    strncpy(new_config->mac_address, mac, sizeof(new_config->mac_address) - 1);
    new_config->vlan_id = vlan;
    new_config->port_setttings = NULL;
    new_config->num_port_settings = 0;

    pthread_mutex_init(&new_config->lock, NULL);

    return new_config;
}

void add_port_settings(nicp_config *config, const char *packet, size_t packet_size) {
    if (!config || !packet) return;

    pthread_mutex_lock(&config->lock);

    config->num_port_settings++;
    config->port_setttings = realloc(config->port_setttings, sizeof(port_settings*) * config->num_port_settings);

    port_settings *new_ps = malloc(sizeof(port_settings));
    new_ps->packet = malloc(packet_size);
    memcpy(new_ps->packet, packet, packet_size);
    new_ps->packet_size = packet_size;

    config->port_setttings[config->num_port_settings - 1] = new_ps;

    pthread_mutex_unlock(&config->lock);
}

void remove_nicp_config(nicp_config *config) {
    if (!config) return;

    for (size_t i = 0; i < config->num_port_settings; ++i) {
        free(config->port_setttings[i]->packet);
        free(config->port_setttings[i]);
    }

    if (config->port_setttings) {
        free(config->port_setttings);
    }

    pthread_mutex_destroy(&config->lock);
}
