// Structure for PORT_SETTINGS
typedef struct {
    char *buffer; // Dynamically allocated buffer
} PortSettings;

// Structure for NICP configurations
typedef struct Node {
    char MAC_ADDRESS[20];
    int VLAN_ID;
    PortSettings PORT_SETTINGS; 
    struct Node *next; // Pointer to the next node in the list
} Node, *List;

// Function to create a new NICP configuration
Node* createConfiguration(char mac[20], int vlanId, size_t bufferSize) {
    Node *newNode = (Node*)malloc(sizeof(Node));

    if (newNode == NULL) return NULL; // Check for allocation failure

    strcpy(newNode->MAC_ADDRESS, mac); 
    newNode->VLAN_ID = vlanId;
    newNode->PORT_SETTINGS.buffer = (char*)malloc(bufferSize);

    if (newNode->PORT_SETTINGS.buffer == NULL) { // Check for allocation failure
        free(newNode); 
        return NULL;
    }

    newNode->next = NULL; // Initialize the next pointer to null as it will be added at the end of the list
    return newNode;
}

// Function to add a new configuration to the list
void addConfiguration(List *list, Node *newNode) {
    if (*list == NULL) { 
        *list = newNode; // If the list is empty, set the new node as the head of the list
    } else {
        Node *current = *list;

        while (current->next != NULL) { // Traverse to the end of the list
            current = current->next;
        }

        current->next = newNode; // Add the new node at the end of the list
    }
}

// Function to remove a configuration from the list
void removeConfiguration(List *list, char mac[20]) {
    Node *current = *list;
    Node *previous = NULL;

    while (current != NULL) { 
        if (strcmp(current->MAC_ADDRESS, mac) == 0) { // If the MAC address matches
            if (previous == NULL) {
                *list = current->next; // Remove the head of the list
            } else {
                previous->next = current->next; // Remove the node from the middle or end of the list
            }

            free(current->PORT_SETTINGS.buffer); 
            free(current);

            return;
        }

        previous = current;
        current = current->next;
    }
}
```

