class CRCHashGenerator {
public:
    // Define a structure for the input data.
    struct InputData {
        RX_UE_INFORMATION_TAG rx_ue_information;
        RNTI rnti;
    };

    // Define a function to generate CRC checksums.
    uint32_t generateCRC(const InputData& data) {
        std::shared_lock<std::shared_mutex> lock(_crcCacheMutex);
        auto it = _crcCache.find(data);

        if (it != _crcCache.end() && 
            std::chrono::system_clock::now() < it->second.expiry) {
            return it->second.checksum;
        }

        // Compute the checksum here, then update the cache.
        uint32_t crc = computeCRC(data);
        _crcCache[data] = 
             CacheEntry{std::chrono::system_clock::now() + 
                       std::chrono::minutes(_expiryTime), 
                       crc};
        return crc;
    }

    // Define a function to handle batch input data.
    std::vector<uint32_t> generateCRC(const std::vector<InputData>& data) {
        std::vector<uint32_t> results;
        for (const auto& item : data) {
            results.push_back(generateCRC(item));
        }
        return results;
    }

