#define MAX_NODES 10000

// Replace this with actual structure definition
typedef struct NFAPI_CRC_INDICATION_PDU_T {
    //...
} NFAPI_CRC_INDICATION_PDU_T;

// Define a node for our linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct Node* next;
} Node;

// Global variables and lock
Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int size = 0;

// Function to create a new node
Node* createNode(NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* temp = (Node*)malloc(sizeof(Node)); 
    if(temp == NULL) {
        return NULL;  // Out of memory error
    }
    temp->data = data;
    temp->next = NULL;

    return temp;
}

// Function to insert a node at the end of the list
void insertNode(NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&lock);  // Lock for thread safety
    if (size >= MAX_NODES) {
        pthread_mutex_unlock(&lock);  // Unlock before returning
        return;
    }

    Node* newNode = createNode(data);
    if (newNode == NULL) {
        pthread_mutex_unlock(&lock);  // Unlock before returning
        return;
    }

    if (head == NULL) {
        head = newNode;
    } else {
        Node* current = head;
        while(current->next != NULL){
            current = current->next;
        }
        current->next = newNode;
    }

    size++;  // Increment the size of list
    pthread_mutex_unlock(&lock);  // Unlock after operation is done
}

// Function to validate data integrity
int verifyDataIntegrity() {
    Node* current = head;
    while(current != NULL) {
        if (current->data == NULL || current->next == current || 
            (current->next && current->next->prev != current)) {
            return 0;  // Data integrity check failed, node orphaned
        }
        current = current->next;
    }

    return 1;  // All nodes are valid
}

// Function to free allocated memory for the entire list
void destroyList() {
    pthread_mutex_lock(&lock);  // Lock for thread safety
    Node* current = head;
    while(current != NULL) {
        Node* temp = current->next;
        free(current->data);
        free(current);
        current = temp;
    }

    size = 0;  // Reset the size of list
    head = NULL;
    pthread_mutex_unlock(&lock);  // Unlock after operation is done
}
```
