pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int count = 0;

int addToList(uint16_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    pthread_mutex_lock(&lock);  // synchronize access

    if (count >= 10000 || !checkRange(RX_UE_INFORMATION_TAG, RNTI)) {
        pthread_mutex_unlock(&lock);  
        return -1;  // error: either limit reached or range is incorrect.
    }

    NFAPI_CRC_INDICATION_PDU_T * newNode = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newNode == NULL) {  // allocation failed
        pthread_mutex_unlock(&lock);  
        return -2;  // error: memory allocation failed.
    }

    newNode->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newNode->RNTI = RNTI;

    srand(time(0));  // for random number generation
    newNode->CRC_INDICATION_REL8_TAG = malloc(sizeof(CRC_INDICATION_REL8_TAG_T));
    if (newNode->CRC_INDICATION_REL8_TAG == NULL) {  // allocation failed
        free(newNode);
        pthread_mutex_unlock(&lock);  
        return -2;  // error: memory allocation failed.
    }

    newNode->CRC_INDICATION_REL8_TAG->CRCFLAG = rand();  // assign a random number to CRCFLAG.

    newNode->next = list;
    list = newNode;
    count++;

    pthread_mutex_unlock(&lock);  
    return 0;  // success
}

int checkRange(uint16_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    return (RX_UE_INFORMATION_TAG >= 0x0001 && RX_UE_INFORMATION_TAG <= 0x7FFF) 
            && (RNTI >= 0x0001 && RNTI <= 0x7FFF);
}
```
