['Here is a C implementation for your requirements. Note that actual error handling, thread safety measures and other considerations are omitted here for simplicity. 

```c
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int uniqueId;
    time_t lastConnectionAttempt;
    int failedAttempts;
    char currentStatus[256];
} UE;

typedef struct node {
    UE *ue;
    struct node* next;
} Node;

typedef struct {
    pthread_mutex_t lock;
    Node* ues;
} Context;

Context* init_context() {
    Context* ctx = (Context*)malloc(sizeof(Context));
    if (!ctx) return NULL;

    pthread_mutex_init(&ctx->lock, NULL);
    ctx->ues = NULL;
    return ctx;
}

UE* create_ue() {
    UE* ue = (UE*)malloc(sizeof(UE));
    if (!ue) return NULL;

    // Initialize the UE fields.
    time(&ue->lastConnectionAttempt);
    ue->failedAttempts = 0;
    strcpy(ue->currentStatus, "initialized");
    return ue;
}

void add_ue(Context* ctx, UE* newUe) {
    pthread_mutex_lock(&ctx->lock);

    Node* temp = (Node*)malloc(sizeof(Node));
    if (!temp) return;

    temp->ue = newUe;
    temp->next = ctx->ues;
    ctx->ues = temp;

    pthread_mutex_unlock(&ctx->lock);
}

void remove_ue(Context* ctx, int ueId) {
    pthread_mutex_lock(&ctx->lock);

    Node *temp = ctx->ues, *prev;

    if (temp != NULL && temp->ue->uniqueId == ueId) {
        ctx->ues = temp->next;  
        free(temp->ue);
        free(temp);
        return;
    }

    while (temp != NULL && temp->ue->uniqueId != ueId) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) return;

    prev->next = temp->next;

    free(temp->ue);
    free(temp); 

    pthread_mutex_unlock(&ctx->lock);
}
```
Please note that you would need to add more code to handle congestion, latency and cooldown periods as well as integrate with health check service. Also, this code does not take into account possible memory leaks or errors in mutex handling which should be handled in a production-level implementation. 
