typedef struct CRC_INDICATION_REL8_TAG {
    int flag; // Replace with actual type and member if known
} CRC_INDICATION_REL8_TAG;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T *head = NULL;

int insert(int tag, int rnti, CRC_INDICATION_REL8_TAG *flag) {
    pthread_mutex_lock(&mutex);

    NFAPI_CRC_INDICATION_PDU_T *newNode = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newNode == NULL) {
        // Handle memory allocation failure gracefully.
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    newNode->RX_UE_INFORMATION_TAG = tag;
    newNode->RNTI = rnti;
    newNode->CRCFLAG = flag;
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&mutex);
    return 0;
}

int delete(int tag, int rnti) {
    pthread_mutex_lock(&mutex);

    NFAPI_CRC_INDICATION_PDU_T **pp = &head;
    while (*pp != NULL) {
        if ((*pp)->RX_UE_INFORMATION_TAG == tag && (*pp)->RNTI == rnti) {
            NFAPI_CRC_INDICATION_PDU_T *nodeToDelete = *pp;
            *pp = nodeToDelete->next;
            free(nodeToDelete);
            break;
        }
        pp = &((*pp)->next);
    }

    pthread_mutex_unlock(&mutex);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T *find(int tag, int rnti) {
    pthread_mutex_lock(&mutex);

    NFAPI_CRC_INDICATION_PDU_T *node = head;
    while (node != NULL) {
        if (node->RX_UE_INFORMATION_TAG == tag && node->RNTI == rnti) {
            pthread_mutex_unlock(&mutex);
            return node;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&mutex);
    return NULL;
}
```
