    node->prev = list->tail;
    node->next = NULL;

    if (list->tail != NULL) {
        list->tail->next = node;
    } else {
        list->head = node;
    }

    list->tail = node;

    pthread_mutex_unlock(&list->lock);
}

void deleteNode(DoublyLinkedList* list, Node* node) {
    if (node == NULL || list->head == NULL) return;

    pthread_mutex_lock(&list->lock);

    if (node->prev != NULL) {
