void addFramesToPDU(NFAPI_RX_PDU_T* pdu, NFAPI_RX_FRAME_T* frames, size_t numFrames) {
    if (numFrames == 0) return;

    NFAPI_RX_FRAME_T* newFrames = realloc(pdu->frames, 
            (pdu->numFrames + numFrames) * sizeof(NFAPI_RX_FRAME_T));

    if (newFrames == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    pdu->frames = newFrames;
    memcpy(&pdu->frames[pdu->numFrames], frames, numFrames * sizeof(NFAPI_RX_FRAME_T));
    pdu->numFrames += numFrames;
}

void iteratePDU(const NFAPI_RX_PDU_T* pdus, size_t numPDUs, void (*func)(NFAPI_RX_FRAME_T*)) {
