    NFAPI_CRC_INDICATION_PDU_T *newData = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (newData == NULL) {
        // handle memory allocation failure...
    }

    return newData;
}

void insertNode(int RNTI) {
    pthread_mutex_lock(&lock);

    Node* node = malloc(sizeof(Node));

    if (node == NULL) {
        // handle memory allocation failure...
    }

    node->data = createData();
    node->next = head;
    head = node;

    pthread_mutex_unlock(&lock);
}

void deleteNode(int RNTI) {
    pthread_mutex_lock(&lock);

    Node* temp = head;
    Node* prev = NULL;

    if (temp != NULL && temp->data->RNTI == RNTI) {  // Checking for the head node.
        head = temp->next;
        free(temp);
    } else {
        while (temp != NULL && temp->data->RNTI != RNTI) {  // Search for the key to be deleted
            prev = temp;
            temp = temp->next;
        }

        if (temp == NULL) return;  // Key not found

        prev->next = temp->next;
        free(temp);
    }

    pthread_mutex_unlock(&lock);
}
```
