int addUE(UEList* list, NFAPI_CRC_INDICATION_PDU_T ue) {
    // Acquire the lock and ensure single access to the list
    while (atomic_flag_test_and_set(&list->lock)) {}

    if (list->size >= list->capacity) {
        // If reached maximum capacity, attempt to double it.
        size_t newCapacity = list->capacity * 2;

        if(newCapacity > MAX_UE_SIZE) {
