        if (!newData) {
            atomic_flag_clear(&list->lock);
            return -2; // Could not allocate memory.
        }

        list->data = newData;
    }

    list->data[list->size] = ue;
    list->size++;

    atomic_flag_clear(&list->lock);

    return 0; // Success.
}
