['Here is a C implementation of what you have requested. It's designed around POSIX threads for thread safety, OpenSSL for hash map operations (for easy message management), and curl library for network fetching.

```c
#include <stdio.h>
#include <openssl/ssl.h>
#include <openssl/bio.h>
#include <openssl/err.h>
#include <curl/curl.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    char* sender_id;
    time_t timestamp;  // Unix timestamp
    char* payload;
} Message;

Message** messages = NULL;
size_t message_count = 0;
pthread_mutex_t mutex;
time_t ttl;  // Time To Live in seconds

static size_t writeCallback(char* ptr, size_t size, size_t nmemb, void* userdata) {
    Message* msg = malloc(sizeof(Message));
    if (!msg) return -1;

    // Parse the response and populate msg fields.
    // Assuming it's a JSON formatted message.

    pthread_mutex_lock(&mutex);
    messages = realloc(messages, (message_count + 1) * sizeof(Message*));
    if (!messages) {
        pthread_mutex_unlock(&mutex);
        free(msg);
        return -1;
    }
    messages[message_count++] = msg;
    pthread_mutex_unlock(&mutex);

    return size * nmemb;
}

void* fetchMessages() {
    CURL *curl = curl_easy_init();
    if (!curl) return NULL;

    struct curl_slist *headers = NULL;  // Optional headers here.
    char url[] = "http://example.com/messages";  // Remote service URL.

    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writeCallback);

    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "Error during HTTP request: %s\n", curl_easy_strerror(res));
    }

    curl_easy_cleanup(curl);
    return NULL;
}

void removeExpiredMessages() {
    time_t now = time(NULL);
    pthread_mutex_lock(&mutex);

    for (size_t i = 0, j = 0; i < message_count; ++i) {
        if ((now - messages[i]->timestamp) > ttl) free(messages[i]);  // Remove expired.
        else messages[j++] = messages[i];  // Move non-expired to the left.
    }

    message_count = j;
    pthread_mutex_unlock(&mutex);
}
```

This code provides a basic structure for managing messages in memory, and includes mechanisms for fetching data from an external source over HTTP(S) and removing expired messages. Note that the trade-off is that we're assuming that fetched messages are immutable (i.e., once they've been added to our array, they can't be modified or removed), which might not be suitable for all use cases.
