#include <ctype.h>

/* 
 * Define constants for maximum filename length, max append digits etc.
 */
#define MAX_FILENAME_LEN 256
#define NEW_MAX_FILENAME_LEN 512
#define APPENDED_DIGITS_LIMIT 9

/* 
 * Function to calculate the number of vowels in a string
 */
int countVowels(char* str) {
    int count = 0;
    for (int i = 0; str[i] != '\0'; ++i) {
        char c = toupper(str[i]);
        if(c=='A'|| c=='E' || c=='I' ||c=='O' ||c=='U'){
            count++;
        }
    }
    return count;
}

/* 
 * Function to calculate the number of uppercase letters in a string
 */
int countUpperCase(char* str) {
    int count = 0;
    for (int i = 0; str[i] != '\0'; ++i) {
        if(isupper(str[i])){
            count++;
        }
    }
    return count;
}

/* 
 * Function to rename a file based on its content and metadata
 */
void renameFile(char* filename) {
    char newFilename[NEW_MAX_FILENAME_LEN] = "";

    // Check if filename exceeds maximum length
    if (strlen(filename) > MAX_FILENAME_LEN){
        printf("Error: Filename is too long.\n");
        return;
    }

    // Calculate the number of vowels in filename
    int numVowels = countVowels(filename);

    // If vowel count exceeds limit, trim it to limit
    if (numVowels > APPENDED_DIGITS_LIMIT){
        numVowels = APPENDED_DIGITS_LIMIT;
    }

    // Generate new filename by appending number of vowels as suffix
    strcat(newFilename, filename);
    char num[3];
    sprintf(num, "%d", numVowels);
    strcat(newFilename, num);

    // Calculate uppercase letters in the new filename
    int numUpperCase = countUpperCase(newFilename);
    char extension[5];

    // Assign file type based on number of uppercase letters
    if (numUpperCase > 10){
        strcpy(extension, ".txt");
    }else if(numUpperCase > 5 && numUpperCase <= 10){
        strcpy(extension, ".log");
    }else{
        strcpy(extension, ".csv");
    }

    // Append file type to the filename
    strcat(newFilename, extension);

    if (strlen(newFilename) > NEW_MAX_FILENAME_LEN){
        printf("Error: New filename is too long.\n");
        return;
    }

    // Rename the file. Note that actual renaming may need system calls, and thus depends on specific system/OS
    // This example just prints out new name for testing purposes
    printf("New filename: %s\n", newFilename);
}
