['Below is an outline of the solution in C using libjpeg, poppler-glib, glib, and threading mechanisms to process multiple JPEG files and convert them into PDF format concurrently:

```C
#include <stdio.h>
#include <dirent.h>
#include <pthread.h>
#include <poppler-document.h>
#include <poppler-page.h>
#include <poppler-image.h>
#include <jpeglib.h>

typedef struct {
    char* filePath;
    // Additional config data as needed...
} ConfigData;

void *processFile(void *arg) {
    ConfigData *config = (ConfigData *) arg;

    FILE *file = fopen(config->filePath, "rb");
    if(!file) {
        // Handle file open error
    }

    struct jpeg_decompress_struct cinfo;
    struct jpeg_error_mgr jerr;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_decompress(&cinfo);

    // Read JPEG header and allocate memory for decompression
    jpeg_mem_src(&cinfo, filePath->file, fileSize);

    // Decompress JPEG to RGB pixels
    (void)jpeg_read_header(&cinfo, TRUE);
    (void)jpeg_start_decompress(&cinfo);

    int width = cinfo.output_width;
    int height = cinfo.output_height;

    // Allocate buffer for RGB pixels
    unsigned char *buffer = malloc(3*width*height);
    if(!buffer) {
        // Handle memory allocation error
    }

    // Read one scanline at a time into our buffer
    while (cinfo.output_scanline < cinfo.output_height) {
       unsigned char *rowPointer = &buffer[3*width*cinfo.output_scanline];
       jpeg_read_scanlines(&cinfo, row_pointer, 1);
    }

    // Finish decompression and release JPEG decompress object
    (void)jpeg_finish_decompress(&cinfo);
    jpeg_destroy_decompress(&cinfo);
    fclose(file);

    PopplerDocument *doc = poppler_document_new_from_data(buffer, 3*width*height, NULL);
    if(!doc) {
        // Handle document creation error
    }

    // Convert JPEG to PDF using poppler library
    PopplerPage *page = poppler_document_get_nth_page(doc, 0);
    cairo_surface_t *img = poppler_page_render(page, 72.0, 72.0);

    // Save the PDF file
    PopplerDocument *pdf = poppler_document_new_from_file("input.pdf", NULL, NULL);
    if(!pdf) {
        // Handle document creation error
    }

    gchar *tmp = poppler_image_to_pixbuf(img, 72.0, 72.0, &err);
    poppler_document_save(doc, "output.pdf", NULL);

    // Cleanup
    cairo_surface_destroy(img);
    g_object_unref(page);
    g_free(tmp);

    return NULL; 
}

int main() {
