int currentConnections = 0;
int maxConnections;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* convertAndCompress(void* job) {
    Job* myJob = (Job*)job;

    // Validate file format.
    if (!isJpegFile(myJob->inputFile)) {
        logError("Invalid input file format.");
        return NULL;
    }

    // Use third-party tool to convert and watermark the image.
    int result = callThirdPartyToolForConversionAndWatermarking(myJob->inputFile, myJob->outputFile, &myJob->config);

    if (result != 0) {
        logError("Failed to convert and watermark the image.");
        return NULL;
    }

    // Compress the PDF.
    result = compressPdf(myJob->outputFile);

    if (result != 0) {
        logError("Failed to compress the PDF file.");
        return NULL;
    }

    pthread_mutex_lock(&lock);
    currentConnections--;
    pthread_mutex_unlock(&lock);

    return NULL;
}

void processFile(char* input, char* output, Config* config) {
    while (1) {
        pthread_mutex_lock(&lock);
        if (currentConnections < maxConnections) break;
        pthread_mutex_unlock(&lock);

        // Sleep for a short period to prevent busy-waiting.
        usleep(500);
    }

    Job myJob = {input, output, *config};
    pthread_t thread;

    if (pthread_create(&thread, NULL, convertAndCompress, &myJob) != 0) {
        logError("Failed to create a new thread.");
        return;
    }

    pthread_detach(thread);

    pthread_mutex_lock(&lock);
    currentConnections++;
    pthread_mutex_unlock(&lock);
}
```

Please note that this is just a basic outline and does not include all possible error handling, concurrency management, memory usage optimization, or system resource management that would be needed in a complete solution. For instance, you may need to use more advanced thread synchronization techniques (such as semaphores) if your third-party tool does not support simultaneous calls on the same file. Also, you might want to consider using a job queue and worker threads for better concurrency handling.
