#define MAX_RECORDS 100000 // maximum number of records before resource exhaustion

typedef struct {
    int value;
} record;

void allocateMemory(int numRecords, int **offsets, record ***records, int **keys) {
    *offsets = (int *) malloc(numRecords * sizeof(int));
    if (*offsets == NULL && numRecords > 0) {
        printf("Failed to allocate memory for offsets\n");
        exit(EXIT_FAILURE);
    } else {
        printf("Allocated memory for offsets: %ld bytes\n", numRecords * sizeof(int));
    }

