    if (*records == NULL && numRecords > 0) {
        printf("Failed to allocate memory for records\n");
        exit(EXIT_FAILURE);
    } else {
        printf("Allocated memory for records: %ld bytes\n", numRecords * sizeof(record *));
    }

    *keys = (int *) malloc(numRecords * sizeof(int));
    if (*keys == NULL && numRecords > 0) {
        printf("Failed to allocate memory for keys\n");
        exit(EXIT_FAILURE);
    } else {
        printf("Allocated memory for keys: %ld bytes\n", numRecords * sizeof(int));
    }
}

void deallocateMemory(int **offsets, record ***records, int **keys) {
    if (*offsets != NULL) {
        free(*offsets);
        printf("Deallocated memory for offsets\n");
    }

    if (*records != NULL) {
        free(*records);
        printf("Deallocated memory for records\n");
    }

    if (*keys != NULL) {
        free(*keys);
        printf("Deallocated memory for keys\n");
    }
}

int main() {
    int numRecords = 10; // example usage, adjust as needed
    int *offsets = NULL;
    record **records = NULL;
    int *keys = NULL;

    if (numRecords > MAX_RECORDS) {
        printf("Too many records requested. Aborting.\n");
        exit(EXIT_FAILURE);
    }

    allocateMemory(numRecords, &offsets, &records, &keys);

    // Fill in the arrays as necessary

    deallocateMemory(&offsets, &records, &keys);

    return 0;
}
```
