    void *metadata; // Assuming metadata is a pointer to arbitrary data, could be anything
    struct TAI_MIB_OBJECT *prev;
    struct TAI_MIB_OBJECT *next;
} TAI_MIB_OBJECT;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
TAI_MIB_OBJECT *head = NULL;
TAI_MIB_OBJECT *tail = NULL;

int addObject(char *objectID, int objectType, void *metadata) {
    if (objectID == NULL || metadata == NULL) {
        printf("Error: Invalid input parameters.\n");
        return -1;
    }

    TAI_MIB_OBJECT *newObject = malloc(sizeof(TAI_MIB_OBJECT));
    if (newObject == NULL) {
        printf("Error: Failed to allocate memory for new object.\n");
        return -1;
    }

    newObject->table = malloc(sizeof(MIB_TABLE));
    if (newObject->table == NULL) {
        free(newObject);
        printf("Error: Failed to allocate memory for MIB_TABLE.\n");
        return -1;
    }

    newObject->table->OBJECT_ID = objectID;
    newObject->table->OBJECT_TYPE = objectType;
    newObject->metadata = metadata;
    newObject->prev = NULL;
    newObject->next = NULL;

    pthread_mutex_lock(&lock);
    if (head == NULL) {
        head = newObject;
        tail = newObject;
    } else {
        newObject->prev = tail;
        tail->next = newObject;
        tail = newObject;
    }
    pthread_mutex_unlock(&lock);

    return 0;
}
```

