typedef struct {
    uint16_t port;
    uint32_t seqNum;
} TransportLayerHeader;

typedef struct {
    uint32_t lchan_id;
    uint32_t ue_context_id;
    atomic_flag processingFlag; // to avoid race condition
    _Atomic(TransportLayerHeader) header;
} LTE_Uu_TransportLayer_Message;

typedef struct {
    size_t length;
    size_t capacity;
    LTE_Uu_TransportLayer_Message* array;
    pthread_mutex_t mutex;
} DynamicArray;

void initDynamicArray(DynamicArray *array, size_t initialCapacity) {
    assert(initialCapacity > 0);
    array->capacity = initialCapacity;
    array->length = 0;
    array->array = malloc(sizeof(LTE_Uu_TransportLayer_Message) * initialCapacity);
    pthread_mutex_init(&array->mutex, NULL);
}

void pushBackToDynamicArray(DynamicArray* array, LTE_Uu_TransportLayer_Message message) {
    pthread_mutex_lock(&array->mutex);
    if (array->length == array->capacity) {
        size_t newCapacity = array->capacity * 2;
        LTE_Uu_TransportLayer_Message* newArray = realloc(array->array, sizeof(LTE_Uu_TransportLayer_Message) * newCapacity);
        if (newArray == NULL) {
            fprintf(stderr, "Memory allocation failure");
            exit(1);
        } else {
            array->capacity = newCapacity;
            array->array = newArray;
        }
    }
    array->array[array->length++] = message;
    pthread_mutex_unlock(&array->mutex);
}

void* processMessage(LTE_Uu_TransportLayer_Message *message) {
    bool expected = false;
    if (!atomic_compare_exchange_strong(&message->processingFlag, &expected, true)) return NULL; // skip if processing or already processed

    // TODO: Process the message. The message shouldn't be modified after setting its processing flag to true.

    expected = true;
    atomic_compare_exchange_strong(&message->processingFlag, &expected, false); // reset processing flag
}
