void validateToken(const char *tokenStr) {
    struct json_object *jobj = json_tokener_parse(tokenStr);

    if (jobj == NULL) {
        fprintf(stderr, "Invalid JSON\n");
        return;
    }

    struct json_object *accessTokenObj;
    if (!json_object_object_get_ex(jobj, "access_token", &accessTokenObj)) {
        fprintf(stderr, "Missing 'access_token'\n");
        return;
    }

    struct json_object *expiryObj;
    if (!json_object_object_get_ex(jobj, "expires_in", &expiryObj)) {
        fprintf(stderr, "Missing 'expires_in'\n");
        return;
    }

    long int expiry = json_object_get_int(expiryObj);
    if (expiry <= 0) {
        fprintf(stderr, "'expires_in' should be a positive integer\n");
        return;
    }
}

int main() {
    const char *jsonStr = "{\"access_token\":\"abc123\", \"expires_in\":3600}";
    validateToken(jsonStr);

    return 0;
}
